quests[10026] = { id = 10026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Störungen", description = "Es ist mir ein wenig peinlich, aber mir ist hier in den Wäldern von Terokkar etwas widerfahren, was mir seit meinen Lehrjahren nicht mehr passiert ist.\n\nManchmal scheitern meine Zauber, obwohl ich genau weiß, dass ich alles richtig gemacht habe. Ich bin fast wahnsinnig geworden, als das zum ersten Mal passiert ist.\n\nIch glaube, ich habe den Grund dafür gefunden. Die Wälder sind voller Wesen, die Sphärenjäger genannt werden. Das sind dämonische Kreaturen mit einem Hang zur Magie und zur Störung magischer Ströme. Der beste Weg, um mit ihnen fertigzuwerden, ist, sie einfach zu töten.", sourceObjective = "Andarl in Allerias Feste möchte, dass Ihr 10 Sphärenjäger tötet.", completion = "<Andarl wischt sich die Stirn mit dem Ärmel seiner Robe ab.>\n\nZum Glück. Ich habe schon befürchtet, dass die Biester die restlichen Waldbewohner vertrieben haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10027] = { id = 10027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Störungen", description = "Es gibt nichts Ärgerlicheres, als einen Zauber vorzubereiten, und dann von einer unsichtbaren Macht unterbrochen zu werden. Nach dem vierten Mal wusste ich, dass es kein Zufall sein konnte, und habe Keb'ezil losgeschickt, um die Ursache herauszufinden.\n\nIch garantiere Euch, dass Ihr nie einen Wichtel treffen werdet, der widerspenstiger ist als Keb.\n\nWie auch immer, er konnte die Quelle des Problems finden, eine verteufelte Kreatur namens Sphärenjäger. Sie haben die Angewohnheit, überall, wo sie auftauchen, die magischen Energien zu stören. Ich habe genug von ihren Störungen.", sourceObjective = "Tötet 10 Sphärenjäger und kehrt dann zu Kurgatok in der Steinbrecherfeste zurück.", completion = "Keb'ezil ist sehr erleichtert, dass Ihr Euch um das kleine Problem gekümmert habt, nicht wahr Keb?\n\n<Der Wichtel ignoriert seinen Meister und scheint beleidigt zu sein.>\n\nIhr müsst ihm seine schlechten Manieren nachsehen. Ihr wisst ja, wie Dämonen sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[10028] = { id = 10028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefäße der Macht", description = "Zwischen den Ruinen von Tuurem gibt es einige Gefäße mit roher, magischer Energie. Wir können von Glück sagen, dass die Zerschlagenen, die in der Stadt eingefallen sind, keine Ahnung von dieser Machtquelle mitten unter ihnen haben, aber wir dürfen nicht hoffen, dass das so bleibt.\n\nMithilfe dieser Gefäße und ihrer Macht können die verstreuten Überlebenden meines Volkes der Verlockung der dämonischen Magie widerstehen. Jeder Quel'dorei, den wir vor dem Wahnsinn unseres Prinzen retten können, ist einer mehr, der uns beim Wiederaufbau unseres verlorenen Ruhms helfen kann. Bringt mir die Gefäße, {class}.", sourceObjective = "Bringt 8 Draeneigefäße zu Ros'eleth in Allerias Feste.", progress = "Konntet Ihr ein paar unbeschädigte Gefäße finden?", completion = "Ich hoffe, dass dies nicht die einzigen Gefäße in der Stadt sind. Es ist ein guter Anfang, aber ich schätze, wir werden noch viel mehr davon brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10029] = { id = 10029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister rufen", description = "Die Geister der Toten in der Knochenwüste rufen nach mir! Sie leiden!\n\n{class}, Ihr müsst zur Knochenwüste im Süden reisen und meinen Gehilfen Soolaveen bei der Flüchtlingskarawane aufsuchen. Er muss es auch spüren und wird Eure Hilfe dabei brauchen, die Geister dort zur Ruhe zu bringen.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht noch einholen. Ich weiß, dass sie in Norden der Knochenwüste Rast machen wollten, bevor sie weiter Richtung Süden nach Auchindoun ziehen wollten.", sourceObjective = "Anachoret Lyteera möchte, dass Ihr ihren Gehilfen Soolaveen bei der Flüchtlingskarawane in der Knochenwüste der Wälder von Terokkar findet.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[10030] = { id = 10030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochen zurückholen", description = "Die Knochen der Draenei, die bei der Explosion von Auchindoun gestorben sind, sind überall in der Knochenwüste verstreut. Viele ihrer Geister sind daher ruhelos und können nicht ins nächste Leben übertreten.\n\n{name}, Ihr müsst mir helfen, ihre Knochen wieder zu besorgen und sie zu ihrer letzten Ruhestätte zu bringen. Nur dann werden sie Frieden finden und den Segen des Lichts erlangen.\n\nSammelt die ruhelosen Knochen mit größter Vorsicht und bringt sie zu Ramdor dem Wahnsinnigen in Auchindoun in der Mitte der Knochenwüste. Trotz seines Namens wird er wissen, wie er sich um sie zu kümmern hat.", sourceObjective = "Sammelt 10 ruhelose Knochen und bringt sie zu Ramdor dem Wahnsinnigen bei der westlichen Seite des Rings der Beobachtung in Auchindoun, das sich in der Mitte der Knochenwüste in den Wäldern von Terokkar befindet.", progress = "Was ist das? Wer seid Ihr?", completion = "Super, genau das, was ich brauche... noch mehr Knochen.\n\n<Ramdor seufzt.>\n\nJa, ja, ich werde mich darum kümmern, dass die Gebeine dieser ehrenwerten Vorfahren ein anständiges Begräbnis bekommen, keine Sorge.\n\nWenn Ihr den Toten wirklich helfen wollt, habe ich noch eine andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10031] = { id = 10031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Verirrten den Weg zeigen", description = "Viele Geister der Draenei wurden von der Explosion in Auchindoun verderbt und wandeln nun voller Pein in der Wüste.\n\n{name}, ich flehe Euch an, gebt ihnen ihren Seelenfrieden wieder. Vernichtet die verirrten Geister und die Skelette der Zerschlagenen, die die Knochenwüste hinter den Mauern Auchindouns heimsuchen.\n\nWas? Ihr denkt, es wäre besser, sie in blinder Wut umherstreifen zu lassen?\n\nKehrt danach zu Anachoret Soolaveen bei der Flüchtlingskarawane zurück und berichtet ihm, was Ihr erreicht habt.", sourceObjective = "Tötet 10 verirrte Geister und 10 Skelette eines Zerschlagenen und kehrt dann zu Anachoret Soolaveen bei der Flüchtlingskarawane in der Knochenwüste in den Wäldern von Terokkar zurück.", completion = "Ihr habt getan, was nötig war. Auch wenn es mich traurig macht, dass die Geister meiner Vorfahren zu schrecklichen Untoten verwandelt wurden, hat Euer Handeln sie endlich zur Ruhe gebracht.\n\nVielen Dank, dass Ihr sie befreit habt, {name}. Bitte nehmt dieses bescheidene Zeichen meiner Hochachtung für Euch und Eure Selbstlosigkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10032] = { id = 10032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakte von Tuurem", description = "Ist Euch das Verhalten der Verirrten in Tuurem aufgefallen? Sie streifen in den Ruinen umher und suchen nach allen Überbleibseln der Draenei, die sie in die Finger bekommen können.\n\nIhre zerschlagenen Meister wissen es besser. Sie haben ihr früheres Leben abgestreift und sind zu etwas ganz anderem geworden.\n\nIch glaube, wir können die Gier der Verirrten ausnutzen und alte Draeneirelikte von ihnen sammeln. Warum sollten wir unser Leben im Kampf gegen die Zerschlagenen riskieren, wenn wir unsere Ziele weise auswählen können?", sourceObjective = "Sammelt 6 Artefakte von Tuurem von den Strauchdieben von Tuurem und den Jägern von Tuurem und bringt sie zu Rakoria in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10033] = { id = 10033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruf: Tötet die Knochenpeitscher!", description = "Es wurde ein Kopfgeld auf die Knochenpeitscher der Knochenwüste ausgesetzt. Als Überträger der Pest müssen sie von nun an vernichtet werden!\n\nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.\n\nMeldet Euch bei Taela Immerlauf, um Eure Belohnung einzufordern.", sourceObjective = "Tötet 20 Knochenpeitscher und meldet Euch dann bei Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar.", completion = "Ja, ich bin mir sicher, dass Ihr all die Knochenpeitscher getötet habt. Ist ja auch klar, weil der Hauptmann auf dem Anschlag einen Beweis gefordert hat.\n\n<Taela schaut Euch sarkastisch an.>\n\nIch nehme Euch beim Wort. Ich bin mir nicht sicher, wen ich so geärgert habe, dass ich zu diesem Dienst verdonnert wurde, aber vielen Dank für Eure Mühe für die Allianz. Hier habt Ihr eine Entschädigung für Euren Aufwand.", sourceObjectiveStatus = "unverified-source-field" }
quests[10034] = { id = 10034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruf: Tötet die Knochenpeitscher!", description = "Die Knochenpeitscher der Knochenwüste haben Mawg gebissen und ihn krank gemacht. Jetzt möchte er, dass sie alle vernichtet werden!\n\nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.\n\nKehrt zu Mawg Grimmschlag zurück, wenn Ihr die Aufgabe erledigt habt, und er wird Euch gut belohnen.", sourceObjective = "Tötet 20 Knochenpeitscher und meldet Euch dann bei Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar.", completion = "Ihr müsst viele von diesen Knochenpeitschern getötet haben! Gut, ich hasse sie! Seit mich einer von ihnen gebissen hat, habe ich dauernd Ohnmachtsanfälle.\n\nWisst Ihr, wie peinlich das ist? Hier, nehmt dies als Dank, dass Ihr meine Rache vollstreckt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10035] = { id = 10035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "In der Knochenwüste gibt es ein Wesen, das so bösartig, so widerlich und so Furcht einflößend ist, dass nur die besten Jäger es wagen, ihm aufzulauern.\n\nIch spreche von Torgos, dem König der Knochenpeitscher, der sich beim Rhazeversteck am westlichen Ende der Weiten herumtreibt.\n\nUnglücklicherweise haben die Arakkoa eine Vogelscheuche aufgestellt, die als 'Torgos' Fluch' bekannt ist und ihn von dort fernhält. Ich wette, dass er trotzdem herauskommen würde, wenn Ihr den Leichnam seines Weibchens Trachela am Fuß dieser Vogelscheuche platziert. Ihr findet sie beim Aashügel im nördlichen Teil der Wüste.\n\nBringt mir eine Schwanzfeder von Torgos.", sourceObjective = "Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar zurück.", progress = "Habt Ihr die Feder? Muss ich Euch für Eure waghalsige Kühnheit belohnen?", completion = "Ich bin beeindruckt, {class}. Torgos war eines der hartgesottensten Wesen, das ich auf dieser Seite von Nagrand kenne.\n\nNun, ich denke, Ihr habt Euch etwas aus dem Schatz von Allerias Feste verdient. Sucht Euch etwas aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[10036] = { id = 10036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "Ich will Torgos, den König der Knochenpeitscher tot sehen!\n\nVor nicht allzu langer Zeit, als ich beim Rhazeversteck am westlichen Ende der Wüste auf Jagd war, fiel dieses Tier mich an.\n\n<Mawg tippt seine Augenklappe an.>\n\nEr hat mir mein Auge genommen, und nun will ich sein Leben dafür! Bringt mir eine seiner Schwanzfedern als Beweis und ich werde Euch gebührlich belohnen.\n\nIhr werdet den Leichnam seines Weibchens Trachela brauchen, um ihn hervorzulocken, da er Todesangst vor der alten Vogelscheuche der Arakkoa hat, die als Torgos' Fluch bekannt ist.\n\nIhr findet sie beim Aashügel im Norden der Wüste.", sourceObjective = "Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", progress = "Habt Ihr ihn getötet? Ist Torgos tot?\n\nHabt Ihr den Beweis?", completion = "Ich danke Euch, {name}. Ihr habt meine Rache ausgeübt, und wie versprochen werde ich Euch belohnen.\n\nSucht Euch hiervon etwas aus und benutzt es weise!", sourceObjectiveStatus = "unverified-source-field" }
quests[10037] = { id = 10037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich würd' lieber angeln", description = "Da wir gerade von Seen sprechen, da gibt es einen See im Nordosten, an dem man richtig toll angeln kann. Früher bin ich da immer mit meinen Freunden hin, aber meine Mutter erlaubt es mir nicht mehr.\n\nSie sagt, es sei zu gefährlich, aber ich habe da oben noch nichts außer ein paar Spinnen gesehen. Als ob Spinnen einem irgendwas anhaben könnten...\n\nIch mochte am liebsten die Aale von da oben. Wenn Ihr zum See hoch geht, könntet Ihr mir dann ein paar dieser Aale bringen? Sie sind störrisch, aber wenn man sie einmal gebändigt hat, kann man sie ganz leicht mitnehmen.", sourceObjective = "Bringt 8 makellose Schimmerschuppenaale zu Seth in Shattrath.", progress = "<Seth zieht Euch am Mantel.>\n\nHabt Ihr die Aale? Hä? Hä?", completion = "Danke! Ich kann mich nicht erinnern, wann ich das letzte Mal Aal gegessen habe.\n\nWie soll ich sie bloß kochen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10038] = { id = 10038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Gefreiter Wöch", description = "Ich habe gerade einen Bericht von einem unserer Späher in der Nähe von Grangol'var erhalten. Er sagt, dass eine schattenhafte Truppe in die Ruinen dort eingezogen ist.\n\n{name}, ich möchte, dass Ihr mit Gefreiter Wöch sprecht und schaut, wie Ihr ihm dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.\n\nGeht nach Westen an der Steinbrecherfeste vorbei. Sein letzter Bericht besagt, dass er sich in der Nähe des nördlichen Eingangs zum Dorf befindet.", sourceObjective = "Sprecht mit Gefreiter Wöch in der Nähe des nördlichen Eingangs von Grangol'var in den Wäldern von Terokkar.", completion = "Es wird auch langsam Zeit, dass Ihr kommt. Ich habe diesen Bericht schon vor über einer Woche zur Allerias Feste geschickt!\n\nBürokratie!", sourceObjectiveStatus = "unverified-source-field" }
quests[10039] = { id = 10039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Späherin Neftis", description = "Ich wurde informiert, dass eine unserer Späherinnen in der Nähe von Grangol'var zurzeit eine schattenhafte Truppe beobachtet, die vor Kurzem dorthin gezogen ist.\n\n{name}, ich möchte, dass Ihr mit Späherin Neftis sprecht und schaut, wie Ihr ihr dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.\n\nGeht von hier aus nach Süden und dann nach Westen, um den Norden der Knochenwüste herum. Ihr letzter Bericht besagt, dass sie sich in der Nähe des südlichen Eingangs zum Dorf befindet.", sourceObjective = "Sprecht mit Späherin Neftis in der Nähe des südlichen Eingangs von Grangol'var in den Wäldern von Terokkar.", completion = "Es wird auch langsam Zeit, dass Ihr kommt. Ich habe diesen Bericht schon vor über einer Woche zur Steinbrecherfeste geschickt!\n\nBlutelfen und ihre Bürokratie!", sourceObjectiveStatus = "unverified-source-field" }
quests[10040] = { id = 10040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sind sie?", description = "Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!\n\nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.\n\nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.", sourceObjective = "Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Gefreiter Wöch in Grangol'var in den Wäldern von Terokkar zurück.", progress = "Habt Ihr schon mit ihnen gesprochen? Was hatten sie zu sagen?", completion = "Gut, Ihr seid endlich zurück! Was habt Ihr herausgefunden? Wer sind sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[10041] = { id = 10041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sind sie?", description = "Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!\n\nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.\n\nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.", sourceObjective = "Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Späherin Neftis in Grangol'var in den Wäldern von Terokkar zurück.", completion = "Gut, Ihr seid endlich zurück! Was habt Ihr herausgefunden? Wer sind sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[10042] = { id = 10042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet den Schattenrat!", description = "Was? Diese Kerle gehören zum Schattenrat?!\n\n{name}, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.\n\nWenn Ihr damit fertig seid, meldet Euch bei Leutnant Kieshammer in Allerias Feste.\n\nViel Glück, {class}.", sourceObjective = "Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Leutnant Kieshammer in Allerias Feste in den Wäldern von Terokkar zurück.", completion = "Das sind schlechte Nachrichten! Aber ich habe die richtige Wahl getroffen, als ich Euch geschickt habe, um Wöch zu helfen. Das letzte, was wir brauchen können, ist, dass der Schattenrat einen starken Posten genau vor unserer Haustür errichtet.\n\n{name}, als Anerkennung für Eure Taten in Grangol'var erlaube ich Euch hiermit, Euch eine dieser wundervollen Belohungen auszusuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10043] = { id = 10043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet den Schattenrat!", description = "Was? Diese Kerle gehören zum Schattenrat?!\n\n{name}, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.\n\nWenn Ihr damit fertig seid, meldet Euch bei Beraterin Faila in der Steinbrecherfeste.\n\nViel Glück, {class}!", sourceObjective = "Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", completion = "Das sind schlechte Nachrichten! Aber ich habe die richtige Wahl getroffen, als ich Euch geschickt habe, um Neftis zu helfen. Das letzte, was wir brauchen können, ist, dass der Schattenrat einen starken Posten genau vor unserer Haustür errichtet.\n\n{name}, Ihr habt Euch etwas Nettes verdient. Sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10044] = { id = 10044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei der Großmutter", description = "Die Großmutter hat mich gebeten, Euch aufzusuchen und Euch eine Nachricht zu überbringen. Sie möchte unverzüglich mit Euch sprechen.\n\nMein Wille mag vielleicht gebrochen sein, aber macht besser keinen Fehler, {name}. Wenn Ihr die Großmutter verärgert, werde ich Euch mit aller Kraft, die noch in mir steckt, bestrafen. Ihr findet sie in der Haupthalle.\n\n<Garrosh zeigt auf das große Gebäude im Norden.>\n\nHört Euch an, was sie zu sagen hat, und tut, was sie Euch aufträgt.", sourceObjective = "Sprecht mit Großmutter Geyah und hört Euch an, was sie zu sagen hat.", progress = "Bitte setzt Euch, mein Kind.", completion = "Wir müssen zuerst Euren Geist erweitern, damit Ihr mit den Ahnen sprechen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10045] = { id = 10045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutaten sammeln", description = "Mutter Kashur möchte mit Euch sprechen, {name}. Bevor Ihr das könnt, müsst Ihr jedoch ein paar Kräuter sammeln, um einen Trank zuzubereiten, der Euren Geist erweitert, damit Ihr mit den Geistern sprechen könnt.\n\nIhr müsst Olembawurzeln aus Terokkar, Marschenbeeren aus den Zangarmarschen, Telaarifarn aus Nagrand und Drachenwirbel aus dem Schergrat sammeln. Ich habe die Anleitung zum Anbau dieser Kräuter auf dieses Pergament geschrieben. Kehrt zu mir zurück, wenn Ihr die Zutaten beisammen habt.", sourceObjective = "Großmutter Geyah in Garadar in Nagrand möchte, dass Ihr 1 Olembawurzel, 1 Marschenbeere, 1 Telaarifarn und 1 Drachenwirbel sammelt.", progress = "Hallo, Kind.", completion = "Ihr seid sehr geschickt, {name}. Unsere besten Kräutersammler hätten doppelt so lange gebraucht, um die Kräuter zu sammeln.\n\n\n\nHabt keine Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[10046] = { id = 10046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Dunkle Portal", description = "Vor zwei Wochen haben unsere Späher beobachtet, wie eine schwer bewaffnete Streitmacht der Allianz unter dem Kommando von Feldkommandeur Romus aus der Burg Nethergarde aufgebrochen ist. Mit so vielen Soldaten, Vorräten und einem so erfahrenen Kommandanten können sie nur ein Ziel haben: die Scherbenwelt.\n\nDer Kriegshäuptling hat eine Vorhut durch das Portal geschickt, aber wenn die Allianz glaubt, dass so viele Truppen von Nöten sind, sollten vielleicht auch wir Verstärkung schicken.\n\nReist durch das Dunkle Portal und meldet Euch bei Nazgrel in Thrallmar.", sourceObjective = "Reist durch das Dunkle Portal und sprecht mit Nazgrel in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10047] = { id = 10047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Ruhms", description = "Sie haben sie den Pfad des Ruhms genannt, eine Straße, die vom Herzen ihrer grausamen Festung zum Dunklen Portal führt, befestigt mit den Knochen meines Volks.\n\nEs war ihnen nicht genug, uns wie Tiere zu jagen, unsere Städte zu zerstören und die Überlebenden zu quälen. Nein, sie mussten auch noch unsere Knochen als Pflastersteine verwenden, und meinen Brüdern und Schwestern ein anständiges Begräbnis unter dem Licht verweigern.\n\nDiese gequälten Seelen wandeln immer noch durch diese Lande und schreien nach Erlösung. Ich bitte Euch, {name}, helft mir, sie beizusetzen.", sourceObjective = "Reinigt 8 zertrampelte Skelette auf dem Pfad des Ruhms mit dem Weihwasser der Draenei und kehrt dann zu Warpseher Kryv in der Ehrenfeste zurück.", progress = "Die Schreie scheinen irgendwie... schwächer geworden zu sein. Möge das Licht dafür sorgen, dass es nicht nur Wunschdenken ist.", completion = "Ihr habt meinen aufrichtigen Dank für Eure Mühen, {name}. Wenn auch noch viel zu tun ist, macht es mich froh, dass einige nun ihren wohlverdienten Frieden gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10050] = { id = 10050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerschütterliche Seelen", description = "Am Ende unserer Invasion wurde das Rüstlager im Süden von den heimtückischen Todesrittern der Horde angegriffen. Diese bösartigen Schemen haben die Verteidiger des Rüstlagers verflucht und ihre Seelen zwischen dem Reich der Lebenden und dem der Toten gefangen.\n\nDiese ehrwürdigen Seelen müssen befreit werden! Ich bitte Euch, {name}, beendet das Leid meiner Kameraden, denn ich bringe es nicht selbst übers Herz, sie zu töten.", sourceObjective = "Ehrenwache Wesilow möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberer und 5 unerschütterliche Ritter beim Expeditionsrüstlager tötet.", completion = "Die Söhne sind Euch für Eure Mühen dankbar, auch wenn nur wenige über das Rüstlager sprechen möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10051] = { id = 10051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Posten der Feuerschwingen!", description = "Was für ein Glück, dass Ihr hier seid!\n\n{class}, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit von Allerias Feste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!\n\nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!", sourceObjective = "Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Hauptmann Auric Sonnenjäger in Allerias Feste in den Wäldern von Terokkar.", completion = "Isla Sternenmähne ist gerade gegangen, aber sie hat mir einen vollständigen Bericht über die Vorkommnisse im Posten der Feuerschwingen gegeben. Verständlich, dass sie über die Geschehnisse beim Cenariusdickicht sehr bestürzt ist. Garstige Blutelfen!\n\nSie hat mir gesagt, dass Ihr die entscheidende Rolle bei ihrer Rettung gespielt habt, damit wir diese Informationen erhalten. Allerias Feste steht tief in Eurer Schuld.\n\nBitte, nehmt im Namen aller dieses Geschenk an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10052] = { id = 10052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Posten der Feuerschwingen!", description = "Was für ein Glück, dass Ihr hier seid!\n\n{class}, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit der Steinbrecherfeste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!\n\nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!", sourceObjective = "Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terkkokar.", completion = "Isla Sternenmähne ist gerade gegangen, aber sie hat mir einen vollständigen Bericht über die Vorkommnisse im Posten der Feuerschwingen gegeben. Verständlich, dass sie über die Geschehnisse beim Cenariusdickicht sehr bestürzt ist.\n\nSie hat mir gesagt, dass Ihr die entscheidende Rolle bei ihrer Rettung gespielt habt, damit wir diese Informationen erhalten. Die Steinbrecherfeste steht tief in Eurer Schuld.\n\nBitte, nehmt im Namen aller dieses Geschenk an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10055] = { id = 10055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts verkommen lassen!", description = "Verstärkung ist gut, aber ich sehe nicht, dass sie irgendwelche Karren mit Barren oder Holz durch die Gegend ziehen.\n\nSchaut Euch um, Freund. Die Bäume sind knapp und die Minen voller Legionsabschaum.\n\nMir gehen die Vorräte aus. Ich versuche schon, sie, wo ich kann, zu ersetzen. Aber so langsam müssen wir anfangen, alles, was wir bekommen können, wiederzuverwenden.\n\nAm südlichen Ende des Pfads des Ruhms steht ein Haufen alter Belagerungsmaschinen 'rum. Ein paar der Teile kann man immer noch verwenden. Habt Ihr Lust, mir bei einer kleinen Wiederverwertungsaktion zu helfen?", sourceObjective = "Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Dumphry in der Ehrenfeste.", progress = "Habt Ihr ein wenig wiederverwertbares Material unter all dem Staub, der Asche und der Kohle finden können?", completion = "Das hier ist in einem besseren Zustand, als ich befürchtet habe. Sicher, es wird eine Weile dauern bis der ganze Rost und Zunder entfernt ist, aber ich kann mich nicht beklagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10057] = { id = 10057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach den Anführern", description = "Trotz Eurer Bemühungen haben wir immer noch Probleme am Expeditionsrüstlager. Niemand weiß mit Sicherheit, was dort vor sich geht, was genau die Geister der gefallenen Soldaten an die Ruinen bindet.\n\nVielleicht gehen wir die Sache falsch an. In meiner Vision habe ich gesehen, dass jeder Geist eine Verbindung zu den Ruinen hat, aber was ist, wenn eine Verbindung zu ihren Anführern besteht?\n\nErzmagier Xintor und Feldkommandant Thalvos standen ihren Männern besonders nahe. Vielleicht bringt die Vernichtung ihrer Geister die anderen zur Ruhe.", sourceObjective = "Besiegt die Geister von Erzmagier Xintor und Feldkommandant Thalvos und kehrt dann zu Ehrenwache Wesilow im Turm nordwestlich der Ehrenfeste zurück.", completion = "Wir können nur hoffen, dass die Geister der Fußsoldaten mit dem Verschwinden der Geister ihrer Offiziere zur Ruhe kommen. Ich danke Euch ein weiteres Mal für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10058] = { id = 10058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein altes Geschenk", description = "<Der Blick des Priesters wandert langsam von seiner Tasse zu Euch.>\n\nHabt Ihr nichts Besseres zu tun, als einen Mann von seiner Tasse fernzuhalten?\n\nAch, was soll's. Ich bin der Meinung, dass Neuankömmlinge ein gutes Zeichen sind. Was würde Turalyon davon halten?\n\nIch erinnere mich noch an den Tag unserer Abreise, als ich ihm die Geheimnisse des Lichts gab. Während des Feldzugs und den folgenden Jahren hat er nicht einen einzigen Tag vergessen, seinen Mannen einen Abschnitt daraus vorzulesen.\n\nAls er uns wieder verließ, gab er mir das Buch zurück, damit ich bis zu seiner Rückkehr darauf aufpasse, aber ich Dummkopf dachte, es sei in meinem Quartier in der Waffenkammer sicher...", sourceObjective = "Besorgt die Geheimnisse des Lichts und bringt das Buch zu Vater Malgor Devidicus in der Ehrenfeste zurück.", progress = "Ich dachte, ich hätte Euch gesagt, dass Ihr mich nicht stören sollt. Was gibt's?", completion = "Ist es das? Kaum zu glauben, dass es die Schlacht überlebt hat. Die Gegebenheiten in den Ruinen waren nicht gerade gut für das Buch, aber ich bin dennoch froh, dass ich es wiederhabe.\n\nEs ist das einzige Zeichen, das ich von Turalyon habe.\n\n<Vater Devidicus scheint mit den Tränen zu kämpfen.>\n\nWenn man so lange Zeit Seite an Seite gekämpft hat, steht man sich noch näher als die eigene Familie.", sourceObjectiveStatus = "unverified-source-field" }
quests[10061] = { id = 10061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unerschütterlichen", description = "Als die Höllenorcs der Knochenmalmer das Expeditionsrüstlager angegriffen haben, fiel unsere Garnison sehr schnell. Es war eine kurze, blutige und grausame Schlacht. Es gab keine Überlebenden.\n\nObwohl wir die Toten begraben und uns an den Höllenorcs gerächt haben, spuken die Geister der Gefallenen immer noch in den Ruinen. Seit kurzem habe ich Visionen, in denen diese Geister zu einer Gefahr für Thrallmar werden.\n\nEs gibt nur einen Weg, um die Geister zur Ruhe zu bringen - Ihr müsst sie im Kampf besiegen.", sourceObjective = "Grelag möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberhexer und 5 unerschütterliche Ritter am Expeditionsrüstlager südlich der Ehrenfeste tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10063] = { id = 10063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscherliga, für Gnome geeignet?", description = "Kindermädchen! Glaubt Ihr das?\n\nSie haben mich von einer viel versprechenden Grabung abgezogen und mit Odesyus' Expedition losgeschickt, um das Kindermädchen für diesen kleinen Gnom zu spielen!\n\nIch habe noch nie von einem Gnom gehört, der Ausgrabungsleiter werden wollte, Ihr etwa?\n\nAnscheinend nehmen wir jetzt auch Gnome und dieser ist wohl besonders von Murlocs fasziniert!\n\nNun gut, er ist losgezogen und hat sich in einem alten Schildkrötenpanzer an der nördlichen Küste der Insel eingerichtet. Geht und seht selbst, wenn Ihr mir nicht glaubt!", sourceObjective = "Zieht los und sucht nach Klopper Knacksklug, der sich in einem alten Schildkrötenpanzer an der Küste nördlich der Blutwacht eingerichtet hat.", completion = "Dachte ich's mir doch! Dieser mürrische alte Zwerg sollte mir eigentlich beim Transport meiner Ausrüstung und dem Sammeln von Daten helfen, aber stattdessen sitzt er nur in dem komischen Draeneidorf herum und betrinkt sich sinnlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[10064] = { id = 10064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht zu der Hand", description = "Die Hand von Argus hat bei Verteidigers Ruh' einen Vorposten eingerichtet, allerdings sind sie dort den Blutelfen und auch der Wildnis zahlenmäßig weit unterlegen. Ihrem Posten droht ohne Verstärkung bald der Fall und somit würden wir die Ereignisse bei der Vektorspule nicht länger im Auge behalten können.\n\nErstattet Späherin Jorli bei Verteidigers Ruh' im Nordwesten Bericht und bietet ihr Eure Hilfe an, {name}.", sourceObjective = "Erstattet Späherin Jorli bei Verteidigers Ruh' Bericht.", completion = "Ich habe gehofft, dass die Blutwacht uns Verstärkung schicken würde, sobald man dort weiß, mit wem wir es hier zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10065] = { id = 10065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schneise schlagen", description = "Während unserer Mission, die Sonnenfalken und ihr Portal auszukundschaften, wurde ich ernsthaft verletzt. Späherin Loryi konnte glücklicherweise die Blutung stillen und sucht gerade nach einem Weg, um mich zur Blutwacht zu bringen.\n\nUnser Problem liegt allerdings darin, dass wir unsere Stellung hier verlassen müssen, um eine sichere Rückkehr garantieren zu können.\n\nSobald wir diesen sicheren Grund verlassen, werden uns Felshetzer anfallen. Wenn Ihr ein paar der wütenden Felshetzer aus dem Weg räumen könntet, würden wir höchstwahrscheinlich sicher an unser Ziel gelangen.", sourceObjective = "Tötet 10 wütende Felshetzer und kehrt zu Späherin Jorli bei Verteidigers Ruh' zurück.", completion = "Es sieht da draußen schon etwas besser aus, ich bin mir jedoch noch immer nicht sicher, ob es besser wäre, hier auf medizinische Versorgung zu warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10066] = { id = 10066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles im Griff", description = "Wir wagen es nicht, unseren Posten zu verlassen oder uns zu weit von Verteidigers Ruh' zu entfernen, {race}. Die mutierten Kreaturen, die sich in der unmittelbaren Nähe der Vektorspule aufhielten, wurden schwerwiegend von der Energie beeinflusst, die den Kristallen entweicht.\n\nDie mutierten Greifer scheinen bis zu einem gewissen Grad Empfindungen entwickelt zu haben. Sie haben gelernt, tückische Fallen zu erschaffen, aufzustellen und zu verbergen, damit sich selbst die umsichtigsten Kämpfer darin verfangen.\n\nWir werden niemals gegen die Sonnenfalken vorgehen können, wenn wir ständig auf unsere Schritte Acht geben müssen. Packt das Problem bei der Wurzel, {name}.", sourceObjective = "Tötet 8 mutierte Greifer und meldet Euch bei Verteidigerin Corin bei Verteidigers Ruh'.", progress = "Konntet Ihr ein paar mutierte Greifer ausmerzen?", completion = "Gut gemacht, {name}. Ohne die Tücken der Greifer, wird es jetzt wesentlich einfacher sein, Verstärkung von der Blutwacht zu erhalten oder Angriffe gegen die Sonnenfalken zu starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10067] = { id = 10067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelte Wassergeister", description = "Die meisten der Kreaturen, die von der Energie der Kristalle berührt wurden, wurden auf die gleiche Art verdorben: seltsame Male auf ihrer Haut, aggressiveres Verhalten und kleine Kristallsplitter in ihren Körpern. Wie dem auch sei, die besudelten Wassergeister der Blutmythosinsel scheinen sich vollständig in Kristall zu verwandeln.\n\nIch habe bis jetzt noch nichts gesehen, was derart auf die Kristalle reagiert hat. Als wir den Besudelten Teich untersucht haben, haben sie sich als besonders gefährlich herausgestellt. Wir müssen sie loswerden, bevor die Sonnenfalken sie als neue Energiequelle missbrauchen können.", sourceObjective = "Tötet 6 besudelte Wassergeister und kehrt zu Verteidigerin Corin bei Verteidigers Ruh' zurück.", completion = "Gut gemacht, {name}. Es ist besonders wichtig, dass wir keine Möglichkeit außer Acht lassen, die den Sonnenfalken weiterhin ihre Existenz sichern könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[10068] = { id = 10068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostnova", description = "Je stärker Ihr werdet, desto mehr entwickelt sich Eure Verbindung zum Arkanen und Ihr findet Zugang zu neuen Zaubern.\n\n\n\nMacht Euch auf, um noch stärker zu werden. Und wenn Ihr etwas Neues gelernt habt, kommt Ihr zurück, um es mir zu demonstrieren.", sourceObjective = "Erreicht Stufe 3 und erlernt Frostnova. Macht eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt Frostnova 2-mal.", completion = "Ah, wie schön, ein {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10069] = { id = 10069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wege des Lichts", description = "Es ist an der Zeit, Eure erste Lektion in den Wegen des Lichts zu lernen, {name}. Durch das Schlagen von Schlachten, werdet Ihr dem Licht näher kommen und Ihr werdet neue Fähigkeiten erlernen.\n\nGeht, sammelt mehr Erfahrung und erlernt eine neue Fähigkeit. Kehrt dann zu mir zurück, demonstriert sie mir und wir werden Eure Ausbildung fortsetzen.", sourceObjective = "Erreicht Stufe 3, um 'Siegel des Befehls' zu erlernen. Wirkt 'Siegel des Befehls' auf Euch selbst, sucht eine Trainingsattrappe auf und trefft sie.", progress = "Habt Ihr Eure neuen Fertigkeiten geübt?", completion = "Ah, wie schön, ein {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10070] = { id = 10070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuverlässiger Schuss", description = "Und nun ist es an der Zeit für Eure erste Lektion.\n\nSobald Ihr mehr Erfahrung gesammelt habt, werdet Ihr neue Techniken entdecken.\n\nGeht, sammelt mehr Erfahrung und erlernt Eure erste neue Fähigkeit. Wenn Ihr das getan habt, sucht eine der Trainingsattrappen draußen auf und probiert sie daran aus.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Findet eine Trainingsattrappe vor dem Sonnenturm und übt daran fünfmal 'Zuverlässiger Schuss'.", completion = "Das habt Ihr gut gemacht, {name}. Ihr könnt auf Euren Fortschritt stolz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10071] = { id = 10071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweiden", description = "Je stärker Ihr werdet, desto mehr Tricks werdet Ihr herausfinden können.\n\nEine der ersten Techniken, die Ihr lernen werdet, ist wahrscheinlich das Ausweiden des Gegners, nachdem Ihr schon ein paar erste Treffer gelandet habt.\n\nSorgt dafür, dass Ihr etwas Erfahrung sammeln könnt, lernt diese Technik und dann übt sie weiter an einer der Trainingsattrappen da draußen.", sourceObjective = "Erreicht Stufe 3 und erlernt das Ausweiden. Macht dann eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt Ausweiden 3-mal.", completion = "Ah, wie schön, ein {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10072] = { id = 10072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Je mehr Fertigkeiten Ihr erlangt, desto größer wird die Auswahl der Euch zur Verfügung stehenden Kräfte.\n\nIch möchte, dass Ihr loszieht, noch mehr Erfahrung sammelt und einen neuen Zauber entdeckt. Wenn Euch dies gelungen ist, kommt zurück und beweist mir Euer neues Wissen.", sourceObjective = "Erreicht Stufe 3, um das Schattenwort: Schmerz zu erlernen. Wirkt es dann 5-mal auf die Trainingsattrappen in der Nähe.", completion = "Ah, wie schön, ein {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10073] = { id = 10073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Mittlerweile habt Ihr die Gerüchte über unsereins, die Hexenmeister, gehört. Schenkt ihnen keine Beachtung; es sind diejenigen, die neidisch auf unsere furchteinflößende Macht sind, die solche Lügen verbreiten.\n\nWenn Ihr Erfahrungen sammelt, werdet Ihr die Mysterien entschlüsseln, die es Euch erlauben, die Teufelsenergien zu kontrollieren.\n\nGeht, setzt Euren Weg fort, bis Ihr eine neue Technik entdeckt habt. Ich möchte, dass Ihr diesen neuen Zauber an den Trainingsattrappen vor dem Sonnenturm ausprobiert.", sourceObjective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Macht eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt daran fünfmal das Wirken von 'Verderbnis'.", progress = "Habt Ihr den Feuerbrand gemeistert?", completion = "Ah, wie schön, eine {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10074] = { id = 10074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", description = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, das Ihr bei den Rüstmeistern eintauschen könnt.", sourceObjective = "Bringt 10 Kristallpulverproben von Oshu'gun zu Forschungsleiterin Amereldine in Halaa.", progress = "Das Kristallpulver des Bergs ist vom Erdenkern dieser Gegend durchdrungen.", completion = "Wundervoll, {name}. Das wird uns in unserem Kampf gegen den Abschaum der Allianz helfen, der sich hier in der Scherbenwelt breitgemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10075] = { id = 10075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", progress = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", completion = "Ich nehme immer gerne Kristallpulverspenden an, {name}. Ihr werdet für jedes Bündel, das Ihr mir bringt, entlohnt werden." }
quests[10076] = { id = 10076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", description = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", sourceObjective = "Bringt 10 Kristallpulverproben von Oshu'gun zu Forschungsleiter Kartos in Halaa.", progress = "Das Kristallpulver des Bergs ist vom Erdenkern dieser Gegend durchdrungen.", completion = "Wundervoll, {name}. Das wird uns in unserem Kampf gegen den Abschaum der Horde helfen, der sich hier in der Scherbenwelt breitgemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10077] = { id = 10077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", progress = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", completion = "Ich danke Euch für Euren Beitrag, {name}. Wenn Ihr noch mehr finden solltet, wisst Ihr, wo Ihr sie hinbringen könnt." }
quests[10078] = { id = 10078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unerwünschten zerstören", description = "Jetzt, da unsere Bergungsaktion ins Rollen gekommen ist, ist es an der Zeit, die zweite Phase unseres Plans einzuläuten.\n\nAm Pfad des Ruhms hat die Horde immer noch ihre alten Klingenwerfer postiert. Lasst Euch von Ihrem Alter nicht täuschen, {name}, sie sind immer noch sehr gefährlich. So sehr wir auch versuchen, alles zurückzuerobern, was wir können, können wir nicht erwarten, dass die Horde ihre Waffen einfach so abbaut.\n\nNehmt diese Fackel und zündet ihre übriggebliebene Belagerungsausrüstung an. Ich werde die Sicherheit der Ehrenfeste nicht dem Zufall überlassen.", sourceObjective = "Zündet die Klingenwerfer der Horde mit der flammenden Fackel am Pfad des Ruhms an. Kehrt dann mit der flammenden Fackel zu Dumphry in der Ehrenfeste zurück.", progress = "Ihr scheint guter Laune zu sein. Haben die brennenden Belagerungsmaschinen der Horde Euch erheitert?", completion = "Das nenne ich Einsatz!\n\nIch bin froh, dass wir endlich Unterstützung erhalten haben, aber ich bin nicht so sicher, ob sie die richtige Einstellung gegenüber der Horde haben. Dort, wo ich herkomme, ist jeder, der eine Waffe auf Euch richtet, ein Feind und muss vernichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10079] = { id = 10079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt diese Mine zum Beben!", description = "Die Mine wurde von diesem Gan'argpack überrannt!\n\nSie haben nicht nur meine Arbeiter aus den Tunneln getrieben, sondern hämmern auch noch Tag und Nacht darin herum! Und jetzt sitzt mir auch noch Danath im Rücken! Sagt, er würde mir meine Bierration streichen, wenn ich mich nicht bald darum kümmere!\n\nKeiner der Minenarbeiter will dort hineingehen, und die Wächter sind zu sehr damit beschäftigt, sich vollaufen zu lassen.\n\nIch flehe Euch an, {name}, helft mir! Danath mag mir meinen Stolz nehmen, aber niemals mein Bier!", sourceObjective = "Tötet 12 Pioniere der Gan'arg und kehrt dann zu Großknecht Biggums zurück.", completion = "Bei Bronzebarts bronzenem... Bart, Ihr habt es geschafft! Ihr seid ein Held, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10081] = { id = 10081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutter Kashur treffen", description = "Erschreckt Euch nicht über das, was Ihr sehen werdet, wenn die Wirkung eintritt. Diese Geister sind überall um uns herum - immer. Der Trank erlaubt Euch nur, sie zu verstehen und zu sehen. Ihr werdet seine Wirkung brauchen, wenn Ihr mit Mutter Kashur sprecht.\n\nIhr findet sie ein gutes Stück im Südwesten beim Ahnengrund.", sourceObjective = "Großmutter Geyah möchte, dass Ihr mit Mutter Kashur sprecht.", completion = "Der Trank, den Ihr zu Euch genommen habt, hat keine echte Wirkung. Ihr könnt einen Geist nur sehen, wenn er es zulässt. Der Trank ist nur ein Symbol Eures Glaubens und Eurer Hingabe. Es war ein Test. Und Ihr habt ihn bestanden...", sourceObjectiveStatus = "unverified-source-field" }
quests[10082] = { id = 10082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die aufgebrachten Ahnen", description = "Seht Ihr, wie sie unter uns wandeln? Der Ahnengrund ist normalerweise sehr ruhig und friedlich.\n\nIn letzter Zeit haben sich die Geister der Ahnen jedoch erhoben und sind sehr aufgebracht. Etwas muss sie sehr stören. Wir müssen herausfinden, was das sein könnte, aber zuerst müssen wir die direkte Bedrohung beseitigen.\n\nDie Geister, die Ihr hier seht, sind nicht wirklich unsere Ahnen, sondern ein Abbild ihrer gegenwärtigen Lage. Ihr müsst die aufgebrachten Orcgeister zerstören. Tut dies und kehrt dann zu mir zurück.", sourceObjective = "Mutter Kashur möchte, dass Ihr 8 aufgebrachte Orcgeister tötet.", completion = "Es ergibt keinen Sinn. Sie erheben sich weiter. Es muss etwas Heimtückischeres dahinter stecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10085] = { id = 10085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei den Ahnen", description = "Ich brauche Euch, um zu den Dörfern unserer Ahnen zu reisen, {name}. Geht zu jedem einzelnen und schaut, ob unsere Vorfahren noch da sind.\n\nGeht zum Sonnenwindposten im Norden, zu den Ruinen des Lachenden Schädels ganz im Norden bei den Bergen, besucht Garadar im Nordosten und zuletzt die Ruinen des Blutenden Auges an der Grenze zwischen Nagrand und den Wäldern von Terokkar im Osten.\n\nBerichtet mir, sobald Ihr die Ahnen in ihrem Zuhause beobachtet habt.", sourceObjective = "Mutter Kashur im Ahnengrund in Nagrand möchte, dass Ihr den Sonnenwindposten, die Ruinen des Lachenden Schädels, Garadar und die Ruinen des Blutenden Auges besucht.", completion = "Das ist sehr beunruhigend. Ihr sagt keiner der Ahnen war in seinem Dorf? Sie gehen alle nach Süden?", sourceObjectiveStatus = "unverified-source-field" }
quests[10086] = { id = 10086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich arbeite... für die Horde!", description = "Könnt Ihr das fassen? Diese Orcs haben mich angeheuert, um ihre beschädigten Befestigungsanlagen abzustützen und Sprengstoff herzustellen. Ist das nicht ein Traumjob? Nur zu schade, dass uns die Materialien ausgehen, aber ein gewitzter Goblin wie ich weiß sich immer zu helfen!\n\nKönntet Ihr mich dabei unterstützen? Ich benötige ein wenig gebrauchtes Holz und Metall von den zerstörten Belagerungsmaschinen entlang des Pfads des Ruhmes. Geht dorthin und sammelt, aber gebt auf diese rothäutigen Orcs Acht!\n\nWenn Ihr fertig seid, kommt zurück und holt Euch eine fette Belohnung ab!", sourceObjective = "Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Megzeg Knaxknöchel in Thrallmar.", progress = "Wie geht es mit der Sammelaktion voran? Habt Ihr etwas Wiederverwertbares finden können?", completion = "Die Materialien sind ausgezeichnet! Vielleicht ein wenig verbogen oder angesengt, aber ich habe mich noch nie von minderwertigem Material aufhalten lassen, wenn es darum ging, Präzisionssprengstoff herzustellen!\n\nDanke, {name}. Ihr habt wirklich ein Händchen exquisiten Müll!", sourceObjectiveStatus = "unverified-source-field" }
quests[10087] = { id = 10087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zündet es an... für die Horde!", description = "Ich bin ein glücklicher, glücklicher Goblin! Ich darf hier Sprengstoff und Killermaschinen herstellen in der Gewissheit, dass sie sofort bei wichtigen Missionen eingesetzt werden!\n\nWo wir gerade von Missionen sprechen, ich habe einen Befehl aus Thrallmar erhalten: Verbrennt die Kanonen der Allianz entlang des Pfads des Ruhms... die Kanonen, die gefährlich auf die Befestigungsanlagen der Horde gerichtet sind. Nehmt diese Fackel und begebt Euch zu jeder Kanone. Zündet die Fackel an und bestaunt den Funkenflug!", sourceObjective = "Zündet die östliche und die westliche Kanone der Allianz mit der flammenden Fackel an und kehrt danach zu Megzeg Knaxknöchel in Thrallmar zurück.", progress = "Ich habe nach Zeichen von brennenden Kanonen Ausschau gehalten - Rauchschwaden oder den Schreien brennender Höllenorcs...\n\nHattet Ihr Erfolg mit Eurem Auftrag?", completion = "Dachte ich's mir doch! Ich konnte die Zerstörung von hier aus zwar nicht richtig sehen, aber ich kann sie mir redlich vorstellen! Ausgezeichnet!\n\nGut gemacht, {name}. Das oberste Kommando von Thrallmar wird sich freuen, von Eurem Erfolg zu hören!", sourceObjectiveStatus = "unverified-source-field" }
quests[10091] = { id = 10091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeleninstrumente", description = "Pah! Sie haben mich gefoltert und versucht, etwas über die Verteidigungsanlagen von Shattrath aus mir herauszuquetschen.\n\nIch habe mich geweigert - da haben sie die anderen Spione an Höllenschlund verfüttert, und ich sollte der Nächste sein. Aber ich habe ihnen nichts verraten!\n\nSie sind wahnsinnig! Sie sind versessen darauf, dämonische Mächte zu beschwören, die sie auf gar keinen Fall kontrollieren können!\n\nSie benutzen besondere Seeleninstrumente, um ihre Seelensplitter herzustellen und ihre Beschwörungen noch mächtiger zu machen. Ihr müsst ihnen diese Instrumente stehlen!\n\nIch würde Euch ja begleiten, aber ich muss nach Shattrath zurück um der Spionagemeisterin des Unteren Viertels zu berichten.", sourceObjective = "Stehlt 5 Seeleninstrumente und bringt sie zu Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath.", progress = "Ja? Was kann ich für Euch tun, {class}?", completion = "To'gun hat mir bereits seinen Bericht abgeliefert. Er hätte Euch unterstützen sollen!\n\nIch habe ihn zurückgeschickt, um Grik'tha zu helfen. Ich finde, die beiden sind ein schönes Paar.\n\nDies sind also die Seeleninstrumente, mit denen der Schattenrat seine Beschwörungskraft erhöht? Ich finde, sie sehen gefährlich aus. Vielleicht können die Seher sie brauchen?\n\nHier, nehmt einen davon als Belohnung für Euren Kampf gegen den Schattenrat im Labyrinth.", sourceObjectiveStatus = "unverified-source-field" }
quests[10093] = { id = 10093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Telhamat", description = "Zum Glück ist der Pfad des Ruhms nicht das einzige Zeichen meines Volks in diesen Ländereien. Im Westen befinden sich immer noch ein paar unserer geheiligten Stätten, auch wenn einige von ihnen überrannt wurden.\n\nWährend Velen sich auf seine Reise nach Azeroth vorbereitete, haben diejenigen von uns, die hier bleiben sollten, versucht, sich wieder in unseren heiligen Orten niederzulassen.\n\nIm westlichen Teil der Höllenfeuerhalbinsel könnt Ihr beim Tempel von Telhamat eine kleine Gruppe von Draenei finden, die von Amaan dem Weisen angeführt werden. Ich bin mir sicher, dass er Euch gerne kennenlernen würde.", sourceObjective = "Sprecht mit Amaan dem Weisen beim Tempel von Telhamat im Westen der Höllenfeuerhalbinsel.", completion = "Ah, Ihr habt also Seher Kryv getroffen. Er ist ein weiser und begabter Mann, und seine Freunde sind auch meine Freunde.\n\nMacht es Euch gemütlich und stellt Euch den anderen vor, die diesen Tempel ihr Zuhause nennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10094] = { id = 10094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex des Blutes", description = "Es ist nun zwei Jahre her, dass die Beschwörung des Schattenrats dieses einst großartige Mausoleum explodieren und die Knochenwüste entstehen lies.\n\nJetzt befinden sie sich im Krieg mit einer unglaublich mächtigen Kraft im Inneren.\n\n{name}, Ihr müsst in das Schattenlabyrinth eindringen und herausfinden, wogegen sie kämpfen und ob es eine Gefahr für uns sein könnte. Unserer Spione haben berichtet, dass sie ein verbotenes Buch mit unheiligen Beschwörungen verwenden, bekannt als der Kodex des Blutes.\n\nSucht in ihm nach Antworten.", sourceObjective = "Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.", completion = "Während Ihr den magiegeladenen Folianten öffnet, überkommt Euch ein Gefühl des Schreckens.\n\nIrgendetwas ist hier eindeutig falsch!\n\nIhr lest weiter, aber was Ihr lest scheint unglaublich zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[10095] = { id = 10095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Herz des Labyrinths", description = "Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren! Es hat die Explosion von Auchindoun verursacht und die Knochenwüste erschaffen.\n\nJetzt nur noch als Murmur bekannt, droht es, den Schattenrat zu überrennen und zu entkommen!\n\nNun, da der Großmeister und der Rest der Führung tot sind, seid Ihr die einzige Hoffnung der Scherbenwelt im Kampf gegen dieses Monster!\n\n{name}, tief in Eurem Herzen wisst Ihr, dass Ihr und Eure Freunde nicht versagen dürfen!", sourceObjective = "Vernichtet Murmur und informiert danach Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath über die Geschehnisse im Schattenlabyrinth.", completion = "Murmur ist fast ausgebrochen?! Sie haben das Biest zwei Jahre sicher im Inneren verwahrt... Ich frage mich, was sie wohl falsch gemacht haben, dass sie nach all der Zeit die Kontrolle darüber verlieren.\n\nWas auch immer es sein mag, {name}, Ihr habt uns alle gerettet! Mir wird schwindelig, wenn ich daran denke, was Shattrath und dem Rest der Scherbenwelt zugestoßen wäre, wenn das Ding sich hätte befreien können!\n\nIch bin so froh, dass Ihr die Sache in die Hand genommen und die Bedrohung durch den Schattenrat in Auchindoun beseitigt habt. Wie können wir Euch je dafür belohnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10096] = { id = 10096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Sporloks", description = "Ikeyen hat mir erzählt, was ihm in diesen Höhlen widerfahren ist, und ich finde es einfach nur schrecklich!\n\nWisst Ihr, vielleicht sollten wir diesen armen Sporloks helfen. Ikeyen sagt, dass sie dort in der Funggorhöhle leben, aber die Marschenbestien sind kürzlich dort eingefallen.\n\nWarum geht Ihr nicht dort hin und schaut, dass Ihr ein paar von diesen Marschenbestien erlegt? Die Höhle ist ganz nah im Südwesten.", sourceObjective = "Tötet 10 Marschengräber und 10 Marschenlauerer und kehrt dann zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen zurück.", completion = "Gut! Diese Marschenbiester haben kein Recht, das Zuhause der Sporloks zu überfallen!\n\nEs wäre besser, wenn diese Tiere lernen würden, in Harmonie zu leben, aber wenn das nicht geht, müssen wir uns eben um die Situation kümmern!\n\nHier, bitte nehmt etwas hiervon als Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10097] = { id = 10097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder gegen Bruder", description = "Die Sethekk haben Skettis mit Fanfaren verlassen, als Auchindoun explodiert ist. Das war sicher ein Vorbote für die Ankunft unseres Meisters.\n\nMein Bruder, Syth, war einer ihrer Anführer und hat uns gesagt, dass es unsere Pflicht wäre, in die Tempelruinen zu gehen und unserem Gott zu begegnen.\n\nNachdem wir unser Lager in den Ruinen aufgeschlagen und sie die Sethekkhallen getauft hatten, kamen mir Zweifel an den Fähigkeiten meines Bruders und seines Verbündeten Ikiss.\n\nNach einiger Zeit hat mich Syth aus den Hallen geworfen und mir verboten, meine Schwester Lakka mitzunehmen. Helft Ihr mir, sie zu retten?", sourceObjective = "Tötet Dunkelwirker Syth in den Sethekkhallen und befreit Lakka. Kehrt zu Isfar außerhalb der Sethekkhallen zurück, wenn Ihr die Aufgabe abgeschlossen habt.", completion = "Ich kann Euch nicht genug danken, {name}. Zu wissen, dass Lakka frei ist, bedeutet, dass ich endlich all meine Bande zu den Sethekk abwerfen kann.\n\nEin Teil von mir wird mir Syths Tod niemals verzeihen, aber es musste getan werden. Wenn ich nach Skettis komme, werde ich die Todesriten für ihn vollziehen. Vielleicht kann sein Geist zur Ruhe kommen, wenn er für die Irreführung unseres Volkes gebüßt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10098] = { id = 10098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Erbe", description = "Mein Volk verehrt einen uralten Helden namens Terokk. Arakkoaküken erfreuen sich an den Geschichten über seine Taten und den Beschreibungen seines prächtigen Federkleids.\n\nEr lebte für hunderte von Jahren unter meinem Volk, doch eines Tages verschwand er urplötzlich, und ließ nur seine Maske, seinen Speer und seine Schriften zurück.\n\nDiese Relikte werden von den Arakkoa hoch verehrt, und es brach ihnen das Herz, als die Sethekk die Gegenstände bei ihrem Aufbruch aus Skettis verschleppten.\n\nIch habe alles, was ich über den Verbleib der Schriftrollen in den Hallen weiß, niedergeschrieben.", sourceObjective = "Bringt Terokks Maske, Terokks Federkiel und die Sage von Terokk zu Isfar außerhalb der Sethekkhallen.", progress = "Die Relikte von Terokk sind schon viel zu lange aus Skettis fort. Konntet Ihr sie von den Sethekk zurückholen?", completion = "Vielleicht wird mir meine Rolle bei den Verbrechen der Sethekk niemals vergeben werden, aber ich möchte versuchen, meine Sünden zu büßen, indem ich die Relikte von Terokk meinen Volk zurückgebe.\n\nVielen Dank für Eure Hilfe dabei, {name}. Ihr habt keine Ahnung, welch großartige Tat Ihr heute geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10099] = { id = 10099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Genie", description = "Diese verfluchten Gan'arg wuseln immer noch in die Mine! Für jeden, den wir umbringen, scheinen zwei oder drei weitere aufzutauchen!\n\nIrgendwas in den Tiefen der Mine muss diese Menge steuern. Ihr scheint das letzte Mal ganz gut klargekommen zu sein, und das Licht weiß, dass Ihr <der/die> Einzige seid, <der/die> mutig genug ist, wieder in die Mine zu gehen. Findet heraus, wer für dieses Ärgernis verantwortlich ist und bestraft ihn dafür!", sourceObjective = "Sucht und tötet Z'kral in den Minen unter der Ehrenfeste und meldet Euch dann bei Großknecht Biggums zurück.", progress = "Ich traue mich fast nicht zu fragen. Euch aus der Mine herauskommen zu sehen kann nur zwei Dinge bedeuten: entweder habt Ihr diesen Bastard umgebracht oder Ihr habt keine Lust mehr. Nun, welches von beiden ist es?", completion = "Ich bin froh, dass Ihr Euch um, um... wie sagtet Ihr hieß er noch gleich? Z'kral?\n\nEurer Beschreibung nach war es wohl mehr ein es als ein er. Nun ja, was zählt ist, dass es tot ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10101] = { id = 10101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Geister sprechen", description = "Oshu'gun, der diamantene Berg, war einst ein heiliger Ort meines Volkes. Dort versammelten sich die Klans jedes Jahr, um das Frühlingsfest zu feiern. Dort kommunizierten unsere Schamanen mit unseren altehrwürdigen Vorfahren. Er bildete das Zentrum unserer Kultur - bis die Schatten uns übernahmen. Als die Klans zu einer Horde wurden, verstummten die Geister von Oshu'gun. Unsere Vorfahren haben sich von uns abgewendet.\n\nDoch nun werden sie in ihrer Ruhe gestört. Reist nach Oshu'gun und findet heraus, was die Geister beunruhigt.", sourceObjective = "Mutter Kashur im Ahnengrund in Nagrand bittet Euch, Eurer Vision auf den Grund zu gehen. Findet K'ure in Oshu'gun.", completion = "<Eine sanfte, melodische Stimme erklingt in Eurem Kopf.>\n\nIch bin K'ure von den Naaru, {name}. Ihr steht hier im Herzen meines alten Schiffs.\n\nOshu'gun, wie die Orcs es genannt haben, ist das Schiff, mit dem die Draenei zuerst auf diese Welt gekommen sind. Obwohl wir schon vor hunderten von Jahren hier vom Himmel gefallen und abgestürzt sind, sind meine Energien immer noch in diesen Trümmern gefangen. Leider bin ich der Grund für die Schmerzen der Orcgeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[10102] = { id = 10102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gelüftetes Geheimnis", description = "Als meine Energien sich über die Jahrhunderte nach und nach verflüchtigten, nahm eine Leere meinen Platz ein und verschlang die Seelen in der Nähe. Hilflos musste ich zusehen, wie ganze Generationen von Orcseelen in den Wirbel hineingezogen wurden. Vor Kurzem bemächtigten meine Feinde sich des Wirbels und benutzten ihn, um zahllose Leerdiener in ihre Brennende Legion zu rufen.\n\nNun liegt der Schlüssel zur Beendigung dieses Kreislaufs und der Befreiung der Orcgeister bei einem anderen Naaru, A'dal. Ich konnte seine Essenz in der uralten Stadt Shattrath in den Wäldern von Terokkar fühlen.", sourceObjective = "Sprecht mit A'dal in Shattrath.", completion = "<Ihr seid der Meinung, dass das Wesen Euch, wenn es das könnte, zunicken würde.>\n\nNatürlich... Wir haben nach der Essenz eines Naaru gesucht. K'ure liegt seit Jahrhunderten im Sterben, und die Leere hat ihn schon fast ganz erfüllt. Wir haben seine Anwesenheit nicht spüren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10103] = { id = 10103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Zurai", description = "Mit der Ankunft von Feldkommandeur Romus und seinen Streitmächten sind die Allianz und ihre Draeneifreunde mutiger geworden. Sie wandeln alle alten Draeneiruinen von hier bis Shattrath in Heerlager um.\n\nAls Antwort darauf haben die Trolle einen neuen Außenposten im östlichen Teil der Zangarmarschen errichtet, südlich des Todesmoors. Sie nennen ihn Sumpfrattenposten. Ich bin froh, dass sie sich in einer solchen Umgebung ihren Humor bewahrt haben. Ich wollte jedenfalls nicht mit ihnen tauschen.\n\nDer Kommandeur des Posten hat mich gebeten, ihm alle Mann zu schicken, die ich entbehren kann.", sourceObjective = "Meldet Euch bei Zurai im Sumpfrattenposten in den Zangarmarschen.", completion = "Um ehrlich zu sein hatte ich mehr Leute erwartet, aber Ihr müsst reichen. Willkommen im Sumpfrattenposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10104] = { id = 10104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorgen um Tuurem", description = "Die Gerüchte über Tuurem sind beunruhigend. Manche sagen, die Ruinen der Stadt laufen vor verrückten Zerschlagenen und Verirrten über, während gierige Artefaktjäger Draeneirelikte stehlen.\n\nEs ist schwer zu sagen, welche wahr und welche falsch sind, aber es liegt in unserer Verantwortung, die Ruinen so gut es geht zu schützen. Sucht Andarl in Allerias Feste in den Wäldern von Terokkar. Er ist eine Art Forscher für magische Relikte. Er weiß wahrscheinlich besser als alle anderen Bescheid, was dort vor sich geht.", sourceObjective = "Sprecht mit Andarl in Allerias Feste in den Wäldern von Terokkar.", completion = "Ich fühle mich geschmeichelt, dass Euer Freund von den Zerschlagenen mich für einen Gelehrten für Relikte seines Volkes hält, aber um ehrlich zu sein habe ich seit meiner Ankunft nicht viel Gelegenheit gehabt, sie zu studieren. Das war sicherlich meine Absicht, aber als ich hier ankam musste ich feststellen, dass es andere Dinge gibt, um die ich mich dringend kümmern muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[10105] = { id = 10105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachrichten für Rakoria", description = "Jetzt, da der Sumpfrattenposten fertig ist, haben wir nicht mehr so viel Kontrolle über die Wege, die in die Marschen und aus ihnen heraus führen. Unsere Anwesenheit in den Wäldern von Terokkar ist nun viel unsicherer. Trotzdem wartet Rakoria in der Steinbrecherfeste auf Nachrichten über unsere Fortschritte hier.\n\nSie ist sehr schlau und tüchtig, {name}, aber seid vorsichtig, wenn Ihr in ihrer Nähe seid. Sie hat viele Waren, die sie nur zu gerne auf den Weg schicken würde, aber glaubt nicht, dass sie nur unser Bestes im Sinn hat. Rakoria geht dorthin, wo sie den besten Gewinn machen kann.", sourceObjective = "Sprecht mit Rakoria in der Steinbrecherfeste in den Wäldern von Terokkar.", completion = "Ich hatte gehofft, seine Leute würden den Außenposten früher fertigstellen, aber sein Geld kostet es ja schließlich nicht. Immerhin geht es voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[10106] = { id = 10106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, {name}, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", progress = "{name}, kehrt zu mir zurück, wenn Ihr bei der Einnahme der Befestigungsanlagen geholfen habt!", completion = "Gut gemacht, {name}. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[10107] = { id = 10107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatische Maßnahmen", description = "Kilrath hat Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Südosten, nahe der Grenze zu Terokkar. Viel Erfolg, {name}!\n\nSeid auf der Hut, er ist ein Klingenmeister...", sourceObjective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.", progress = "Sprecht.", completion = "Wie also lautet Eure Entscheidung? Soll es Krieg geben, oder werdet Ihr mich unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10108] = { id = 10108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatische Maßnahmen", description = "Die Agenten der Jägerin haben Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Osten. Viel Erfolg, {name}!\n\nSeid auf der Hut, er ist ein Klingenmeister...", sourceObjective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.", progress = "Sprecht.", completion = "Wie also lautet Eure Entscheidung? Soll es Krieg geben, oder werdet Ihr mich unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10109] = { id = 10109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich muss sie haben!", description = "Könnt Ihr sie sehen?? Bei Gazlows wundervollem Mundgeruch, ich muss diese Eier haben! Ihr seht aus wie jemand, den man gebrauchen kann.\n\nIch sag Euch was, {race}, wenn Ihr ein paar Dinge für mich sammelt, damit ich meinen Spring-o-Mat 4000 zum Laufen bekomme, werde ich Euch einen Schlüssel geben, mit dem auch Ihr die Maschine bedienen könnt! Was man mit einem Spring-o-Mat 4000 machen kann? Wohl eher was man damit nicht machen kann...\n\nIch brauche Luftelementargas von den Luftelementaren in Nagrand. Sie sind überall, fragt mich also nicht, wo Ihr sie finden könnt!", sourceObjective = "Wazdaz gegenüber der Klanwacht im Süden von Nagrand möchte, dass Ihr ihm 3 Einheiten Luftelementargas bringt.", progress = "Habt Ihr das Gas?", completion = "Ausgezeichnet! Nur ein paar kleine Einstellungen und dieses Ding ist so gut wie neu. Oh richtig, Euer Schlüssel! Bitte sehr.\n\nDer Spring-o-mat hat übrigens noch ein paar Macken, die ich noch reparieren muss. Äh, seid einfach vorsichtig damit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10110] = { id = 10110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", progress = "Kehrt zu mir zurück, wenn Ihr bei der Einnahme der Befestigungsanlagen geholfen habt!", completion = "Gute Arbeit, {name}. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10111] = { id = 10111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir das Ei!", description = "Jetzt, da Ihr initiiert wurdet, möchte ich, dass Ihr mir dieses Ei bringt! Benutzt den Spring-o-Mat und versucht, das Nest genau in der Mitte zu treffen. Aber seid vorsichtig! Schlechte Sprünge können in körperlichen Schäden oder dauerhaften schweren Wunden resultieren.", sourceObjective = "Wazdaz in Nagrand möchte, das Ihr den Spring-o-Mat 4000 benutzt, um in das Nest in dem nahe gelegenen Baum zu springen und das geheimnisvolle Ei zu stehlen.", progress = "Habe ich meine Vorliebe für Eier erwähnt?", completion = "Nun, es ist kein Ei... Aber Hühnchen mag ich auch! Ich beiße mich einfach durch diese riesige Klaue durch! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[10112] = { id = 10112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein persönlicher Gefallen", description = "Hmmm? Eine Kiste sagt Ihr? Oder waren es mehrere? Wisst Ihr aus welchem Material sie war?\n\nUnd wie heißt der Händler? Empoor? Und Ihr seid Euch sicher, dass er ein Zerschlagener ist? Ich mache nicht viele Geschäfte mit ihresgleichen.\n\nVielleicht hilft es meinem Gedächtnis ein wenig auf die Sprünge, wenn Ihr mir einen Gefallen tut.\n\nDie Arakkoa der Skith - diese primitiven Zauberer - haben neulich eine große Schiffladung meiner magischen Waren gestohlen. Ich will alles zurückhaben!\n\nIhr könnt das Skithversteck südlich von Shattrath finden.", sourceObjective = "Holt 5 von Lathrais gestohlenen Waren zurück und bringt sie zu Windhändler Lathrai bei der Taverne Weltenend im Unteren Viertel in Shattrath.", progress = "Hmm, wird mein Gedächtnis schon besser?", completion = "Ja, ich glaube, es wird alles deutlicher.\n\nUnd ich glaube, dass Euer Eifer in dieser Angelegenheit mit mehr als nur den Informationen, die Ihr sucht, belohnt werden sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[10113] = { id = 10113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwarys Safari", description = "\"Geht und sucht ein paar Vorräte\", hat er gesagt. Ich bin fast fünfzehn Mal getötet worden, bevor ich diesen Ort hier überhaupt gefunden habe! Diese Zerschlagenen sind vielleicht nicht das gastfreundlichste Volk, das ich kenne, aber immerhin haben sie nicht versucht, mir die Haut von den Knochen zu ziehen!\n\nWie auch immer, ich gehe nicht zurück. Meine Tage als Großwildjäger sind vorbei. Wenn ihr zufällig nach Nordosten Richtung Zangarmarschen geht und bei Nesingwarys Safari vorbeikommt, sagt dort Bescheid, dass \"die Flinte\" gekündigt hat.\n\nHey, vielleicht könnt Ihr ja meinen Platz einnehmen! Viel Glück, <Fremder/Fremde>.", sourceObjective = "\"Die Flinte\" Jones möchte, dass Ihr mit Hemet Nesingwary in Nesingwarys Safari am nordöstlichen Rand von Nagrand sprecht.", completion = "Ich schätze, wir müssen einen Ersatz für den Wasserträger finden. Nun, Ihr seht aus wie ein kräftiger {class}. Interesse an einem Job? Oder kommt Ihr wegen der Jagd?", sourceObjectiveStatus = "unverified-source-field" }
quests[10114] = { id = 10114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwarys Safari", description = "Diese Orcs haben noch nie zuvor einen Tauren gesehen, könnt Ihr das glauben? Wenn Hauptmann Kroghan nicht wäre, würden sie mich wahrscheinlich in diesem Moment zum Abendessen verschlingen!\n\nAber wo sind meine Manieren? Ich bin Ohlorn Fernreiser, herausragender Jäger! Ich gehöre zu Nesingwarys Expedition, die sich von Azeroth aus auf die Jagd nach Großwild hierher begeben hat. Wenn Ihr Euch für die Jagd interessiert, solltet Ihr meine Truppe in Nesingwarys Safari östlich von hier an den Grenzen zu den Zangarmarschen besuchen.", sourceObjective = "Ohlorn Fernreiser möchte, dass Ihr mit Shado 'Fitz' Fernreiser in Nesingwarys Safari in Nagrand sprecht.", completion = "Ich bin erleichtert zu hören, dass er in Sicherheit ist. Seid Ihr hier, um an der Jagd teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10115] = { id = 10115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolchfennkrise", description = "Die Kurenai und die Draenei sind nicht immer der gleichen Meinung, besonders nicht, wenn es um die Verirrten geht. Wir helfen den Verirrten, die sich an uns wenden, gerne, aber wir werden sie niemals verfolgen. Manche Draenei sind andererseits überzeugt davon, dass sie alle 'erlöst' werden müssen.\n\nEs gibt jedoch Zeiten, in denen sogar die Verirrten zu weit gehen, wie zum Beispiel der Dolchfennstamm. In ihrem Dorf im Westen hantieren sie mit Giften herum, lügen und betrügen, was für uns sehr unnatürlich ist.\n\nWir müssen dem ein Ende bereiten, bevor der bösartige Dolchfennstamm seinen Einfluss noch weiter ausbreiten kann.", sourceObjective = "Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn.", completion = "Ihr habt gute Arbeit geleistet, {name}. Keiner ist der Meinung, dass es noch Erlösung für den Dolchfennstamm gegeben hätte, aber ich glaube nicht, dass die Draenei in dieser Situation schnell genug gehandelt hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10116] = { id = 10116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Häuptling Mummaki", description = "Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamms der Verirrten, wegen seiner brutalen Angriffe auf die Oreborzuflucht.\n\nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Kurenai und Draenei auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.\n\nReisenden wird nahe gelegt, die Gegend um Dolchfenn westlich der Oreborzuflucht zu meiden.\n\nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Ikuti eingefordert werden.", sourceObjective = "Bringt Häuptling Mummakis Totem zu Ikuti in der Oreborzuflucht.", progress = "Ihr wollt also das Kopfgeld für Häuptling Mummaki einfordern?", completion = "Bemerkenswert! Es gab schon einige vor Euch, die das Kopfgeld gewinnen wollten, aber keiner von ihnen ist je zurückgekehrt. Es ist nicht schwer sich auszumalen, was ihnen wohl zugestoßen ist.\n\nIch bin sehr erleichtert, dass wir in Zukunft nichts mehr von Mummaki und seinem Gesindel zu befürchten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10117] = { id = 10117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Häuptling Mummaki", description = "Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamm der Verirrten, wegen seiner brutalen Angriffe auf Zabra'jin und seine Einwohner.\n\nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Späher und Boten auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.\n\nReisenden wird nahe gelegt, die Gegend um Dolchfenn nordwestlich von Zabra'jin zu meiden.\n\nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Schattenjäger Denjai eingefordert werden.", sourceObjective = "Bringt Häuptling Mummakis Totem zu Schattenjäger Denjai.", progress = "Ihr wollt also das Kopfgeld für Häuptling Mummaki einfordern?", completion = "Ihr habt meinen Dank, {name}. Ich hatte mir schon überlegt, einen Teil der Garnison dorthin zu schicken und Mummaki selbst zu erledigen. Welche Folgen das jedoch für Zabra'jin gehabt hätte, ist schwer zu sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10118] = { id = 10118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Dolchfenn", description = "Von allen Stämmen der Verirrten in den Zangarmarschen ist der Dolchfennstamm der gerissenste und aggressivste. Er ist sehr gut organisiert und macht keinen Hehl daraus, dass er gerne die Kontrolle über alle Verirrten in den Marschen hätte.\n\nIhren Angriffen sind schon viele meiner Späher und Boten zum Opfer gefallen. Ich kann es mir nicht leisten, noch mehr Männer zu verlieren.\n\nWenn wir nicht bald handeln, werden sie die komplette Kontrolle über alle Straßen erlangen und Zabra'jin einkesseln.", sourceObjective = "Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn und kehrt dann zu Schattenjäger Denjai in Zabra'jin zurück.", completion = "Ich glaube, Ihr habt ihnen eine ziemlich deutliche Botschaft zukommen lassen. Vielleicht haben meine Männer nun nicht mehr so viel Angst vor dem Dolchfennstamm. Oder sie schämen sich zumindest für ihren Mangel an Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[10119] = { id = 10119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Dunkle Portal", description = "Zwanzig Jahre lang war es ruhig um das Dunkle Portal – es wurde zu einem Symbol längst vergangener Zeiten.\n\n<Reldorn sieht sich um.>\n\nIch habe nicht geglaubt, dass ich den heutigen Tag erleben würde, aber hier stehen wir nun und schauen tief in den Abgrund.\n\nAuf der anderen Seite des Portals sind wir in einem grausamen Krieg gefangen – ein Krieg, den wir nicht ohne Hilfe gewinnen können. Ihr müsst durch das Dunkle Portal reisen und unseren Truppen helfen, {class}.\n\nMeldet Euch umgehend bei Kommandant Duron. Er erwartet Euch in der Scherbenwelt...", sourceObjective = "Reist durch das Dunkle Portal und sucht Kommandant Duron. Er wartet auf der anderen Seite auf Eure Ankunft - in der Scherbenwelt.", completion = "Willkommen in der Scherbenwelt, {name} -- willkommen im Alptraum! Auch wenn das erste Expeditionskorps es unbeschadet hierher geschafft hat, versucht die Legion nun, das Portal zurückzuerobern und unsere Verstärkung daran zu hindern, es zu durchschreiten.\n\nIch würde Euch gerne hier einsetzen, aber unsere Truppen und die Soldaten der Horde können die Kolonnen der Legion, die diese Plattform erobern wollen, selbst zurückhalten.\n\nIhr müsst dorthin gehen, wo Ihr am meisten gebraucht werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10120] = { id = 10120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ankunft in der Scherbenwelt", description = "Mit der Unterstützung der Allianz können meine Leute die Verteidigung hier aufrechterhalten, aber Ihr müsst dringend meinen Bericht zu General Krakork in Thrallmar bringen. Mit seiner Hilfe können wir diese Dämonen zurück in den Abgrund drängen, aus dem sie gekommen sind! Sprecht mit Vlagga Freyfeder auf der Anhöhe hinter uns. Sie wird Euch schnell auf den Weg dorthin bringen.", sourceObjective = "Generalleutnant Orion beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Orions Bericht zu Vlagga Freyfeder bringt.", progress = "Ich habe gesehen, wie Ihr mit Orion gesprochen habt - es muss eine wichtige Angelegenheit sein...", completion = "Ihr seid also Orions neuer Bote? Ich hoffe, es ergeht Euch besser als dem letzten, den er geschickt hat, {class}. Mit der vorrückenden Legion schafft Ihr es niemals zu Fuß nach Thrallmar. Sagt Bescheid und mein treuer Flügeldrache wird Euch sicher dorthin bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10121] = { id = 10121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brennende Legion ausrotten", description = "Auch wenn dieses Land voller neuer, unbekannter Feinde ist, ist die Brennende Legion immer noch die größte Bedrohung für unsere Expedition. Einer meiner vertrauenswürdigsten Krieger, Unteroffizier Schädelbrecher, hat die Taktiken der Legion untersucht und versucht, das wahre Ziel der Legion in diesem Land herauszufinden. Ihr findet ihn bei der Versorgungskarawane außerhalb des südlichen Walls.\n\nUnd {name}, hütet Euch vor der Legion. Ihre Bösartigkeit darf nicht unterschätzt werden.", sourceObjective = "Sprecht mit Unteroffizier Schädelbrecher bei der Versorgungskarawane außerhalb von Thrallmar im Osten.", completion = "Ihr habt sicher auf Eurem Flug vom Dunklen Portal die Krieger der Legion überall in der Landschaft gesehen. Auch wenn wir sie in der Schlacht am Berg Hyjal vor etwa 5 Jahren besiegt haben, haben diese verfluchten Dämonen immer noch nicht genug. Wenn sie auf eine Herausforderung aus sind, wird die Horde ihnen entsprechend antworten!\n\nWir Orcs haben mit der Legion mehr als nur eine Rechnung zu begleichen! Was ist mit Euch, {name}? Soll ich Euch von unserem Feind erzählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10122] = { id = 10122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erstreckung der Zitadelle", description = "Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.\n\nIch habe einen meiner besten Späher, Gefreiter Imarion, losgeschickt, um ihre Vorgehensweise zu erkunden, aber er ist noch nicht mit seinem Bericht zurückgekehrt.\n\nImarion sollte sich auf das nördlichste Lager entlang des Südlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet ihn, {name}. Ohne seinen Bericht sitzen wir hier hilflos herum.", sourceObjective = "Durchsucht das nördlichste Lager entlang des Südlichen Bollwerks nach einer Spur von Gefreiter Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10123] = { id = 10123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsfunkenklamm", description = "Verdammnislord Kazzak hat das Kommando über die Brennende Legion in der Scherbenwelt. Da wir Kazzak nicht direkt angreifen können - noch nicht - müssen wir zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.\n\nSie haben Schreckenslords in der Teufelsfunkenklamm östlich von hier postiert. Sie sind für diese höllischen Stürme, die auf uns herabprasseln, verantwortlich. Sie und ihre Diener zu vernichten wäre ein schwerer Schlag für die Legion.", sourceObjective = "Unteroffizier Schädelbrecher bei der Versorgungskarawane östlich von Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet.", completion = "Ausgezeichnete Arbeit, Soldat. Die Häufigkeit der Angriffe wird nun sicher nachlassen - zumindest bis sie neue Schreckenslords schicken.\n\nNun zu den schlechten Nachrichten: ich habe Eure neuen Befehle...", sourceObjectiveStatus = "unverified-source-field" }
quests[10124] = { id = 10124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorposten: Häschersturz", description = "Eure Fähigkeiten in der Schlacht sind dem Oberkommando aufgefallen, {class}. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 200 Schritte nach Osten und biegt bei der herstehenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To'arch.\n\nUnd jetzt weggetreten!", sourceObjective = "Meldet Euch bei Vorpostenkommandant To'arch im Häschersturz.", completion = "Ihr habt also die Teufelsfunkenklamm aufgeräumt, was? Gut zu hören - wir brauchen Soldaten wie Euch, die sich kopfüber in die Schlacht stürzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10125] = { id = 10125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Die Kommunikation unterbrechen", description = "Direkt im Osten liegt die Front der Legion. Die Front dient der Brennenden Legion als mobile Kommandobasis. Ihr könnt die Sender der Legion aus der Erde herausragen sehen. Mit ihrer Hilfe kommuniziert die Legion mit ihren Konstruktionslagern in der ganzen Scherbenwelt. Sie dienen ebenfalls als Schutzeinrichtung zur Verschlüsselung sämtlicher Übertragungen, sodass eine magische Überwachung nicht mehr möglich ist.\n\nIch möchte, dass Ihr diesen Sprengstoff nehmt und die Sender damit zerstört. Zerstört sie alle, {name}! Sie sind von Süden nach Norden an der Grenze der Front der Legion aufgereiht.", sourceObjective = "Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr To'archs Sprengstoff benutzt, um den Sender der Legion: Bosheit, Sender der Legion: Zorn, Sender der Legion: Hass und Sender der Legion: Furcht zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[10127] = { id = 10127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Das Band zerreißen", description = "Es wäre Vernachlässigung meiner Pflicht, wenn ich Euch nicht befehlen würde, die Dämonen an der Front der Legion, östlich von dieser Basis, zu vernichten.\n\nBeide Seiten der Front sind nach dem selben Muster aufgebaut: Teufelstreiber wandeln zwischen den Lagern der Legion hin und her, die von Zornwächtern bewacht werden. Die ganze Operation wird von einer Unterwerferin der Shivan beaufsichtigt. Tötet sie alle und überlasst Kazzak den Rest.\n\nUnd passt auf die patrouillierenden Teufelshäscher auf. Ich weiß, dass Ihr stark seid, aber diese Biester machen mit Euch kurzen Prozess.", sourceObjective = "Vorpostenkommandant To'arch am Häschersturz auf de Höllenfeuerhalbinsel möchte, dass Ihr 4 Teufelstreiber, 8 Zornwächter und Unterwerferin Shi'aziv tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10129] = { id = 10129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Tore Murketh und Shaadraz", description = "Wir haben die beiden Haupttransporter, mit denen die Brennende Legion ihre Verstärkung herbeiholt, ausgemacht: Tor Murketh und Tor Shaadraz.\n\nWenn Ihr den Pfad des Ruhmes nach Osten hinaufschaut, könnt Ihr sie an beiden Seiten der Straße erkennen. Ich möchte, dass Ihr sie beide in Stücke sprengt!\n\nHier sind die Bomben, die Ihr dafür benötigt. Sie wurden speziell von einem Goblin in Area 52 entworfen. Sprecht mit Schwadronskommandant Brack - er wird Euch einen Wyvern zur Verfügung stellen.", sourceObjective = "Sprecht mit Schwadronskommandant Brack, bombardiert Tor Murketh und Tor Shaadrez und kehrt dann zu Vorpostenkommandant To'arch im Häschersturz zurück.", progress = "Wenn Ihr beim ersten Versuch verfehlt, startet einen neuen...", completion = "Das wird sie um Wochen zurückwerfen! Fantastische Arbeit, {name}. Die Legion hätte sicher nie mit so starkem Widerstand gerechnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10130] = { id = 10130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die westliche Flanke", description = "Zusätzlich zu den anderen Anweisungen werden die Orc in den Befehlen angewiesen, ihre Ausrüstung und Verpflegung für einen Angriff vorzubereiten.\n\nNach den Plänen sollen Kriegsboss Nekroggs Mannen sich zu einer westlichen Flanke formieren, um die Ehrenfeste in die Zange zu nehmen.\n\nDa die Garnison der Feste sich auf die Verteidigung der östlichen Seite konzentriert, wäre ein Angriff von Westen fatal. Die Ehrenfeste kann nur gehalten werden, wenn der Angriff von Westen niemals stattfindet.", sourceObjective = "Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Leutnant Amadi im westlichen Wachturm der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10132] = { id = 10132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kolossale Bedrohung", description = "Seht Ihr diesen riesigen roten Kristall im Norden? Er ist vor Kurzem vom Himmel gefallen und hat dabei ein großes Erdbeben ausgelöst.\n\nAls wir hierher kamen, um den Grund für den Aufruhr zu erforschen, haben wir all die Kolosse hier gesehen, die zuvor noch nicht da waren.\n\nEs ist eindeutig etwas faul an dem Kristall und den Energien, die er ausstrahlt, aber ich habe keine Zeit dafür. Ich muss mich zuerst um diese Bergriesen kümmern.\n\nIch möchte, dass Ihr zum Himmelssturzgrat geht und Euch um sie kümmert.", sourceObjective = "Tötet 5 tobende Kolosse und kehrt dann zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.", completion = "Gute Arbeit.\n\nWenn Ihr mich fragt, müssen wir einfach genug von diesen Kolossen töten, dann brauchen wir uns nicht mehr um diese merkwürdigen Kristall in der Mitte kümmern.\n\nHier, nehmt eines hiervon als Belohnung der Expedition des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[10134] = { id = 10134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise des purpurnen Kristalls", description = "Als der Koloss Eurem Angriff zum Opfer fällt, bemerkt Ihr, dass er ein rotes Kristallfragment in der Hand hält.\n\nIn der Hand des Riesen schien es sehr klein und unauffällig, aber für Euch ist das Stück sehr schwer zu tragen. Es sieht sehr verdächtig nach einem Stück des riesigen roten Kristalls in der Mitte des Grats aus.\n\nDies ist ganz sicher ein Hinweis auf die merkwürdigen Dinge, die hier geschehen. Ihr seid Euch sicher, dass die Druiden beim Posten des Cenarius im Süden den Splitter sehen wollen.", sourceObjective = "Bringt den Purpurkristallsplitter zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel.", progress = "Das ist ein ganz schön großer Kristall, den Ihr da habt. Habt Ihr ihn von den Kolossen im Grat?\n\nLasst mich ihn anschauen.", completion = "Hm, für mich sieht es einfach wie ein großer Klumpen ungeschliffenen Kristalls aus.\n\nZugegeben, ich fühle eine kranke, böse Aura, die von ihm ausgeht, aber das ist nicht gerade mein Spezialgebiet. Ich bin nur hier, um die Bedrohung durch die Bergriesen aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10136] = { id = 10136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausame Pläne", description = "Magister Blutfalke hat endlich den Schriftwechsel der Legion, den Ihr gefunden habt, entziffert. Wie es aussieht, handelt es sich dabei um Angriffspläne, die von einem Leutnant des Hochlords Kazzak geschickt wurden - Arazzius der Grausame. Offensichtlich hat Arazzius den Befehl über die Bodentruppen auf der Höllenfeuerhalbinsel. Es ist an der Zeit, dass wir seinen Befehl beenden, {name}. Vernichtet ihn mit größter Vorsicht.\n\nBegebt Euch zu den Teichen von Aggonar und setzt dem so genannten 'Legionslord' ein Ende. Heute fordert die Horde die Höllenfeuerhalbinsel zurück. Die Legion möge verdammt sein.", sourceObjective = "Tötet Arazzius den Grausamen und kehrt danach zu Nazgrel in Thrallmar zurück.", completion = "Alle kommenden Generation werden diesen Tag bejubeln, {name}. Sie werden von Eurem Heldenmut singen. Ich wünschte, Thrall wäre hier, um diesen Sieg mit uns zu feiern. Die Legion liegt am Boden, und die Höllenfeuerhalbinsel gehört wieder der Horde! Vielleicht besteht doch noch Hoffnung für diese verwüstete Welt und unser Volk auf ihr.\n\nLok'tar ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10140] = { id = 10140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zur Ehrenfeste", description = "Wenn Ihr bereit seid, werde ich Euch einen Flug direkt zur Ehrenfeste besorgen.\n\nSprecht dort mit Marschall Isildor und gebt ihm Durons Bericht. Er wird sich freuen, einen weiteren Rekrut aus der Heimat zu sehen, und ich bin mir sicher, dass die Informationen in diesem Bericht sehr wichtig sind!", sourceObjective = "Fliegt zur Ehrenfeste und übergebt Marschall IsildorDurons Bericht.", progress = "Dem Licht sei Dank, dass Ihr heil hier angekommen seid. Die Ehrenfeste benötigt alle erfahrenen Krieger, die sie bekommen kann.", completion = "Unsere Expedition zu dieser verlassenen, zerschlagenen Welt wäre fast zum Stillstand gekommen, {name}. Wir haben mehr Widerstand erfahren, als wir dachten.\n\nAls ob die Brennende Legion nicht schon schlimm genug wäre, gibt es in diesen Ländern Schrecken, die wir noch nie zuvor gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10141] = { id = 10141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergeburt der Brennenden Legion", description = "Als die Brennende Legion in Azeroth eingefallen ist, war sie hier in der Scherbenwelt nicht untätig. Wir haben ihre Bewegungen über die Jahre verfolgt, aber ihre letzte Tat, {class}, ist schlimmer als alles, was wir je gesehen haben.\n\nSprecht mit Unteroffizier Altumus in der Nähe der Östlichen Versorgungskarawane. Er hat die Eindringlinge beobachtet und weiß vielleicht mehr über ihre Pläne.\n\nSeid schnell und passt auf, {name} - die Brennende Legion darf auf keinen Fall unterschätzt werden.", sourceObjective = "Sprecht mit Unteroffizier Altumus bei der Östlichen Versorgungskarawane außerhalb der Ehrenfeste im Osten.", completion = "Truppenkommandant Danath hat meine Anfrage nach Verstärkung wohl etwas falsch verstanden. Ihr seht zwar fähig aus, aber... ich habe um ein komplettes Bataillon gebeten!\n\nWisst Ihr, wir haben da ein kleines Dämonenproblem.", sourceObjectiveStatus = "unverified-source-field" }
quests[10142] = { id = 10142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Pein", description = "Verdammnislord Kazzak hat das Kommando über die Brennende Legion in der Scherbenwelt. Da wir Kazzak nicht direkt angreifen können - noch nicht - müssen wir zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.\n\nSie haben Schreckenslords am Pfad der Pein östlich von hier postiert. Sie sind für diese teuflischen Stürme, die auf uns herabprasseln, verantwortlich. Sie und ihre Diener zu vernichten wäre ein schwerer Schlag für die Legion.", sourceObjective = "Unteroffizier Altumus bei der Östlichen Versorgungskarawane östlich der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet.", progress = "Die Ehrenfeste ist sicher, solange die Bogenschützen unsere Himmel schützen.", completion = "Ausgezeichnete Arbeit, Soldat. Die Häufigkeit der Angriffe wird nun sicher nachlassen - zumindest bis sie neue Schreckenslords schicken.\n\nNun zu den schlechten Nachrichten: ich habe Eure neuen Befehle...", sourceObjectiveStatus = "unverified-source-field" }
quests[10143] = { id = 10143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionsposten", description = "Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, {class}. Sie wollen Euch an die Front zu Rohamus' Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 400 Schritte nach Osten, durch das Tal der Knochen, bis Ihr auf einen zerstörten Teufelshäscher stoßt. Ihr findet den Expeditionsposten dort, wo einst ein Lager der Legion war. Wenn Ihr angekommen seid, meldet Euch bei Vorpostenkommandant Königstein.\n\nUnd jetzt weggetreten!", sourceObjective = "Meldet euch bei Vorpostenkommandant Königstein im Expeditionsposten.", completion = "Schön, Euch kennenzulernen, Soldat.\n\nGenug gequatscht... nun hört zu - Ich habe eine wichtige Mission für Euch und ich möchte, dass Ihr sie erfüllt... und überlebt!", sourceObjectiveStatus = "unverified-source-field" }
quests[10144] = { id = 10144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verstärkung abschneiden", description = "Direkt im Nordosten liegt die Front der Legion. Entlang der Front befinden sich die infernalen Portale, mit deren Hilfe Verstärkung auf die Höllenfeuerhalbinsel und in die ganze Scherbenwelt gebracht wird. Wir müssen diese Portale zerstören, {name}!\n\nNehmt diesen Zünder. Er wurde in Area 52 hergestellt und benutzt die eigene Macht der Dämonen als Sprengstoff! Besiegt die Legion beim Portal Grimh und Portal Kaalez und haltet nach dämonischen Runensteinen Ausschau. Wenn Ihr genug Steine beisammen habt, benutzt den Zünder, um die Steine in den Portalen zu sprengen... und dann genießt das Feuerwerk!\n\nGeht, {name}, und kehrt zu mir zurück, wenn Ihr Eure Aufgabe erfüllt habt.", sourceObjective = "Besiegt die Feinde um Portal Grimh und Portal Kaalez herum, um dämonische Runensteine zu sammeln.\n\nBenutzt Königsteins Zünder in Portal Grimh und Portal Kaalez.\n\nKehrt danach mit dem Zünder zu Vorpostenkommandant Königstein zurück.", progress = "Ich wünschte, ich hätte die Feuer sehen können. Dieser Sprengstoff hat mächtig Dampf!", completion = "Gut gemacht, {name}. Die Zerstörung der Portale wird den Nachschub an Verstärkung für die Legion für eine Weile bremsen!\n\nAber noch können wir uns nicht ausruhen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10146] = { id = 10146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Tor Murketh und Tor Shaadraz", description = "Westlich des Dunklen Portals befinden sich zwei riesige Transporter: Tor Murketh und Tor Shaadraz.\n\nWenn Ihr den Pfad des Ruhmes nach Osten hinaufschaut, könnt Ihr sie an beiden Seiten der Straße erkennen. Ich möchte, dass Ihr sie in Stücke sprengt!\n\nHier sind die Bomben, die Ihr benutzen sollt. Sie wurden speziell von einem Goblin in Area 52 entworfen. Sprecht nun mit Schwadronskommandant Dabir'ee - er wird Euch einen Greifen zur Verfügung stellen und Euch losschicken.", sourceObjective = "Sprecht mit Schwadronskommandant Dabir'ee, bombardiert Tor Murketh und Tor Shaadraz und kehrt dann zu Vorpostenkommandant Wa'ppun am Expeditionsposten zurück.", progress = "Dies ist ein wichtiger Auftrag, {name}. Ich würde ihn nicht an irgendjemanden vergeben.", completion = "Das wird sie um Wochen zurückwerfen, kein Zweifel! Ihr habt mir gerade ungewöhnlich gute Laune verschafft, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10150] = { id = 10150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erstreckung der Zitadelle", description = "Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.\n\nIch habe einen meiner besten Spurenleser, Späherin Makha, losgeschickt, um ihre Vorgehensweise zu erkunden, aber sie ist noch nicht mit ihrem Bericht zurückgekehrt.\n\nMakha sollte sich auf das nördlichste Lager entlang des Nördlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet sie, {name}. Ohne ihren Bericht sitzen wir hier hilflos herum.", sourceObjective = "Durchsucht das nördlichste Lager entlang des Nördlichen Bollwerks nach einer Spur von Späherin Makha.", sourceObjectiveStatus = "unverified-source-field" }
quests[10152] = { id = 10152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die westliche Flanke", description = "Zusätzlich zu den anderen Anweisungen werden die Orc in den Befehlen angewiesen, ihre Ausrüstung und Verpflegung für einen Angriff vorzubereiten.\n\nNach den Plänen sollen Kriegsboss Nekroggs Mannen sich zu einer westlichen Flanke formieren, um Thrallmar in die Zange zu nehmen.\n\nDa die Garnison der Feste sich auf die Verteidigung der östlichen Seite konzentriert, wäre ein Angriff von Westen fatal. Thrallmar kann nur gehalten werden, wenn der Angriff von Westen niemals stattfindet.", sourceObjective = "Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Steingardist Ambelan im Rückenbrecherposten in der Nähe von Zeth'Gor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10159] = { id = 10159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet den Dornnebelhügel sauber!", description = "Wir kämpfen schon die ganze Zeit, um den Pass durch den Dornnebelhügel von den Verheerern freizuhalten. Es wäre schlecht, wenn wir ganz von der Zuflucht in den Zangarmarschen abgeschnitten wären.\n\nWir möchten die Tiere nicht vertreiben, aber wir haben kaum einen andere Wahl, sie werden Reisenden in dieser Gegend gegenüber immer aggressiver.\n\nLöscht ein paar von den Felshetzern aus, wenn Ihr könnt.", sourceObjective = "Tötet 8 Dornenfangfelshetzer und 8 Dornenfanggiftspucker und kehrt dann zu Mahuram Starkhuf im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.", progress = "Wie läuft es mit der Bereinigung des Dornnebelhügels?", completion = "Jetzt, da die Verheerer fort sind, können die Reisenden der Zuflucht des Cenarius in den Zangarmarschen wieder sicher vorankommen.\n\nDie Expedition des Cenarius ist Euch etwas schuldig, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10160] = { id = 10160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind kennen", description = "Es gibt Gerüchte, dass eine neue Brut von Orcs aufkommt. Größer, bösartiger und listiger als die Rüpel, mit denen wir uns sonst herumschlagen müssen. Wenn diese Gerüchte wahr sind, müssen unsere Streitkräfte, die ohnehin schon überansprucht sind, sich bis über ihre Grenzen hinaus belasten.\n\nIch habe meinen Leutnant, Amadi, damit betraut, die Sache zu untersuchen. Wenn Ihr uns in dieser dunklen Stunde beistehen wollt, dann meldet Euch bei ihr. Sie befindet sich in dem zerbrochenen Turm im Westen der Feste.\n\nUnd {name}, seid vorsichtig da draußen. Ihr stürzt Euch in eine neue, gefährliche Welt.", sourceObjective = "Sprecht mit Leutnant Amadi im alten Wachturm im Westen der Ehrenfeste.", completion = "<Leutnant Amadi nickt.>\n\nGut, wir können jede Hilfe gebrauchen. Die zunehmende Orcbevölkerung am südlichen Bollwerk bereitet mir Kopfschmerzen. Ich habe einen Späher losgeschickt, um sie zu erkunden, aber er ist noch nicht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10161] = { id = 10161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Notfall...", description = "Bei einem Notfall ist es die Aufgabe des Piloten, einen kühlen Kopf zu bewahren, besonders, wenn die einzigen Befehle, die der Kopilot befolgt, die seines Magens sind.\n\nDie gute Nachricht ist, dass wir nicht tagelang darauf warten müssen, dass uns Ersatzteile geliefert werden. Die schlechte Nachricht ist, dass die Ersatzteile überall von hier bis zum Tal der Knochen im Osten verstreut sind.\n\nDie andere schlechte Nachricht? Die Ersatzteile sind nicht so leicht ersetzbar. Sie, äh, sind bei unserem schnellen Abgang abgefallen. Könntet Ihr mir vielleicht helfen, genügend davon wieder vom Boden aufzusammeln?", sourceObjective = "Sammelt 30 Zeppelintrümmer und bringt sie zu \"Schreihals\" Quack Lufthans bei der Zeppelinabsturzstelle.", progress = "Habt Ihr genügend Teile gefunden? Wenn nicht muss ich die Bratpfanne verwenden, mit der Legassi die ganze Zeit herumwedelt. Dann muss ich den Zeppelin in die \"Fliegende Bratpfanne\" umbenennen.", completion = "Einige davon sind in einem ziemlich schlechten Zustand, aber ich sollte damit zurechtkommen. Es braucht nur ein wenig kreative Ingenieurskunst und es wird sicher klappen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10162] = { id = 10162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Die Abyssische Untiefe", description = "Jetzt, da Ihr Eure Flügel habt, habt Ihr vielleicht Interesse an einem weiteren Bombardement?\n\nDieses Mal haben wir die Hauptproduktionsstätte der Legion isoliert, hinter den Konstruktionslagern im Norden. Schwingt Euch auf einen Wyvern und zerstört das verdammte Ding!\n\nHier sind die Bomben. Sprecht mit Schwadronskommandant Brack wenn Ihr zum Abflug bereit seid.", sourceObjective = "Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen vernichtet.", progress = "Zeigt Ihnen, dass nicht einmal die Himmel sicher sind!", completion = "Ihr fliegt, als hättet Ihr Euer Leben lang nichts anderes getan, {name}. Hervorragende Vorstellung! Und nicht einmal ein kleiner Kratzer an den Flügeldrachenzerstörern!", sourceObjectiveStatus = "unverified-source-field" }
quests[10163] = { id = 10163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Die Abyssische Untiefe", description = "Jetzt, da Ihr Eure Flügel habt, habt Ihr vielleicht Interesse an einem weiteren Bombardement?\n\nDieses Mal haben wir die Hauptproduktionsstätte der Legion isoliert, hinter den Konstruktionslagern im Norden. Schwingt Euch auf einen Greifen und zerstört das verdammte Ding!\n\nHier sind Eure Bomben. Sprecht mit Greifnerin Heulwind wenn Ihr zum Abflug bereit seid.", sourceObjective = "Schwadronskommandant Greifgar im Trümmerposten auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen vernichtet.", progress = "Zeigt Ihnen, dass nicht einmal die Himmel sicher sind!", completion = "Ihr fliegt, als hättet Ihr Euer Leben lang nichts anderes getan, {name}. Hervorragende Vorstellung! Und nicht einmal ein kleiner Kratzer an den Greifenzerstörern!", sourceObjectiveStatus = "unverified-source-field" }
quests[10164] = { id = 10164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles wird gut", description = "Ihr habt ein ganz schönes Abenteuer hinter Euch, {name}. Und das noch bevor Ihr überhaupt einen Fuß in den Auchenaikrypta gesetzt habt.\n\nIch bin einer der glücklichen Geister. Ich war nie an Levixus gebunden oder Teil eines der bösartigen Experimente in der Nekromantie von Exarch Maladaar. Während Levixus durch Eure Hand gestorben ist, lebt Maladaar immer noch weiter und quält die Geister in der Krypta.\n\nWorum ich Euch bitte ist ganz einfach. Geht in die Auchenaikrypta und tötet Exarch Maladaar, damit die gefangenen Geister endlich Frieden finden können.", sourceObjective = "Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr in die Auchenaikrypta geht und Exarch Maladaar vernichtet.", completion = "Ihr habt es geschafft, {name}! Die Geister sind frei!\n\nAuch wenn ich keinen weltlichen Körper habe, kann ich Euch trotzdem mit Gegenständen aus der Geisterwelt belohnen. Benutzt sie mit Vorsicht, da diese Gegenstände oft unberechenbar sind und Ihrem Träger großen Schaden zufügen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10165] = { id = 10165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Konkurrenz untergraben", description = "Dieser Shaffar ist ganz schön gerissen, das muss man ihm lassen... Er hat es geschafft, das Konsortium fern zu halten, während er in aller Seelenruhe diese Gruft all ihrer Schätze beraubt. Ich glaube nicht, dass diese Dummköpfe es tatsächlich schaffen, durch seine Verteidigung zu brechen, deshalb mache ich Euch einen Vorschlag, {race}.\n\nDringt in die Managruft ein und tötet den Nexusprinzen Shaffar. Bringt mir seine Körperbandagen als Beweis Eurer Tat, und ich werde Euch fürstlich belohnen.", sourceObjective = "Nexusprinz Haramad außerhalb der Managruft möchte, dass Ihr Nexusprinz Shaffar tötet und ihm Shaffars Bandagen bringt.", progress = "Ich teile nicht gerne.", completion = "Und wieder ein Konkurrent weniger... Ihr leistet gute Arbeit für ein Wesen aus Fleisch und Blut, {race}. Sucht mich auf, wenn Ihr je im Nethersturm sein solltet. Ich wohne auf der Sturmsäule.", sourceObjectiveStatus = "unverified-source-field" }
quests[10166] = { id = 10166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weißborkes Erinnerung", description = "Dieser Anhänger bringt Erinnerungen an eine andere Zeit zurück. Eine bessere Zeit.\n\nLeider sind Erinnerungen das Letzte, was ich jetzt gebrauchen kann.\n\nIch möchte, dass Ihr dies beim Runenstein im Versengten Hain vergrabt. Dort habe ich den Treantältesten zum ersten Mal getroffen. Bettet die Erinnerung an meinen alten Freund in Frieden.", sourceObjective = "Larianna Flusswind möchte, dass Ihr Weißborkes Anhänger beim Runenstein im versengten Hain vergrabt.", progress = "Ihr seid zurück, {name}. Habt Ihr denn noch nicht genug getan?", completion = "Ich gehöre dieser Welt nicht länger an und muss mich geschlagen geben. Das Land hat sich auf ewig verändert, und nichts wird mehr sein wie früher.\n\nLasst den Anhänger hier bei mir, {name}. Eines Tages vielleicht, wenn die Elfen schon lange nicht mehr sind, wird ein Baum an genau diesem Ort wachsen - in einem versengten Wald und zwischen toten Treants.", sourceObjectiveStatus = "unverified-source-field" }
quests[10167] = { id = 10167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun...", description = "Tief in der Auchenaikrypta befindet sich ein Grab: ein Grab, dass keinesgleichen in den Zerschlagenen Weiten findet. Aus diesem Grab, dem ersten Grab, wurde das riesige Mausoleum von Auchindoun geboren.\n\nIhr müsst zu der Auchenaikrypta reisen und dieses Grab finden. Tötet den Grabwächter und befreit den Geist, der darin gefangen ist. Der Geist ist der Schlüssel...", sourceObjective = "Reist zur Auchenaikrypta in der Knochenwüste der Wälder von Terokkar und tötet Exarch Maladaar um den Geist von D'ore zu befreien.", completion = "Die Erinnerung ist sehr lebendig, {name}. Meine Energien wurden bei dem Aufprall vollkommen ausgelaugt. Ich war nichts als ein kleiner Fleck von Leerenergien, als Prophet Velen und seine Draeneifreunde meine Überreste geborgen und hierher gebracht haben. Nach einer Zeremonie wurde meine geschwächte Form hier in diesem Sarkophag zur Ruhe gebettet. Ich habe mich nun für fast tausend Jahre regeneriert. Der Kreis ist fast geschlossen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10168] = { id = 10168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was die Seele sieht", description = "Seit mehreren Jahrhunderten verbinden sich die Geister von Auchindoun nun mit meiner getrübten Essenz. Viele der Katastrophen, die diese Krypta heimgesucht haben, sind auf meinen geschwächten Zustand zurückzuführen.\n\nUnglücklicherweise kann nichts diesen Kreis aufhalten. Das gehört zur Natur der Naaru - ohne die Leere kann das Licht nicht existieren.\n\nEure einzige Möglichkeit besteht darin, die Geister von Nagrand zu vernichten, bevor sie sich in Wesen der Leere verwandeln. Benutzt die Seelenspiegel, die sich überall in der Krypta befinden, um sie zu befreien...", sourceObjective = "Sucht einen Seelenspiegel in der Auchenaikrypta und benutzt ihn, um einen getrübten Geist eines uralten Orcahnen von Nagrand zu rufen. Zerstört 15 getrübte Geister, damit die Ahnen in Frieden ruhen können.\n\nKehrt zu Mutter Kashur im Ahnengrund zurück, wenn Ihr fertig seid.", progress = "<Mutter Kashur ist sichtlich aufgebracht.>\n\nDiese Naaru sind weiser als alle Lebewesen in dieser Welt.", completion = "Ihr habt eine lange und gefährliche Reise hinter Euch und Leben und Gesundheit für die Sicherheit der Mag'har und den Frieden unserer Ahnen aufs Spiel gesetzt. Ich bin Euch dafür dankbarer, als tausend Worte sagen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10169] = { id = 10169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Würde verlieren", description = "Die Aldor haben sich heute das Wohlwollen der Sha'tar verdient. Als ob das etwas Überraschendes wäre!\n\nSchaut nur, wie sie nur ein paar Fuß von A'dal entfernt mit ihrer tollen Beinarbeit angeben. Könnten sie sich wohl noch mehr bemühen, sich bei den Naaru einzuschmeicheln?\n\nHerold Haronems Schützen sind so engagiert, dass sie sogar ihren eigenen Kochtopf mitbringen, um keine langen Pausen zum Mittagessen machen müssen. Das kann nicht ohne Strafe vonstatten gehen, {name}.\n\nIch möchte, dass Ihr diese Phiole in ihr Essen kippt. Die Folgen sollten... sehr amüsant sein.", sourceObjective = "Magister Falris in Shattrath möchte, dass Ihr die Phiole mit Beruhigungsserum zur Terrasse des Lichts bringt und sie in den Kochtopf von Haronems Regiment schüttet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10170] = { id = 10170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Großmutter", description = "Kehrt zu Großmutter Geyah in Garadar zurück und berichtet ihr von Eurem Sieg, {name}. Das wird den Mag'har sicher neuen Mut geben. Vielleicht erwacht sogar der junge Höllschrei aus seiner Melancholie.", sourceObjective = "Kehrt nach Garadar zurück und sprecht mit Großmutter Geyah.", completion = "Ich möchte, dass Ihr diese Nachrichten persönlich zu Garrosh bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10171] = { id = 10171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der untröstliche Häuptling", description = "Ihr habt so viel für die Mag'har getan, {name}. Alle wissen von Euren Taten, auch Garrosh. Geht nun zu ihm und erzählt ihm von eurem letzten Erfolg. Sagt ihm, was Ihr für ihn und sein Volk getan habt. Eure Worte werden ihn sicher trösten.", sourceObjective = "Großmutter Geyah in Garadar möchte, dass Ihr mit Garrosh sprecht.", completion = "Alle sind stolz. Stolz dass unser Volk einen weiteren Winter überleben wird. Aber danach? Was ist danach?\n\nVielleicht solltet Ihr diesen Klan anführen, {name}. Vielleicht ist es mir dann vergönnt zu sterben, wenn die Großmutter dahinscheidet. Vergönnt, die Schande meines Familiennamens auszulöschen. Ich sehne mich nach diesem Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10172] = { id = 10172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt keine Hoffnung", description = "Ihr seid <ein ehrenwerter/eine ehrenwerte:r> {race}, {name}. Ihr habt viel für die Mag'har getan. Niemand könnte Eure Dienste für mein Volk je leugnen. Dennoch ist die Zeit der Mag'har abgelaufen. Ihr habt mir mehr als alles andere gezeigt, dass ich nicht in der Lage bin, diese Leute anzuführen. Zu stark ist der Fluch meines Blutes. Ich werde nicht... ich kann nicht der nächste Höllschrei sein, der die Orcs in die Verdammnis führt.\n\nBitte, {name}, kehrt zur Großmutter zurück und erklärt ihr, was ich Euch gesagt habe. Ich schäme mich zu sehr, um zu ihr zu gehen... ihr in die Augen zu schauen.", sourceObjective = "Sprecht mit Großmutter Geyah und erzählt ihr, was Garrosh Euch gesagt hat.", completion = "<Tränen strömen über Großmutter Geyahs Gesicht.>\n\nGeht zu Eurem Kriegshäuptling. Sagt ihm, dass ich ihn hier erwarte...", sourceObjectiveStatus = "unverified-source-field" }
quests[10173] = { id = 10173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stab des Erzmagiers", description = "Erlaubt, dass ich mich vorstelle, {class}.\n\nMein Name ist Ravandwyr, Lehrling des Erzmagiers Vargoth.\n\nMein Meister ist... nennen wir es indisponiert. Ich bin hier in einer Angelegenheit von höchster Wichtigkeit.\n\nDie Ruinen von Arklon südöstlich der Stadt sind eine Brutstätte für die Aktivitäten der Brennenden Legion. Was sie mit den Ruinen vorhaben interessiert weder mich noch meinen Meister. Aber ihre Anführerin, Ekkorash, hat den Stab meines Meisters.\n\nMit diesem Beschwörungspulver könnt Ihr die Dämonin aus ihrem Versteck locken. Streut es über die Kohlenpfanne in der Mitte der Ruinen.", sourceObjective = "Besorgt Erzmagier Vargoths Stab von Ekkorash der Inquisitorin und bringt ihn zu Ravandwyr in Area 52. Um Ekkorash aus ihrem Versteck hervorzulocken, streut das Beschwörungspulver auf die Kohlenpfanne in der Mitte der Ruinen.", progress = "Ich werde nicht ruhen, bis Erzmagier Vargoth seinen Stab zurück hat. Konntet Ihr ihn den Klauen des Dämonen entreißen?", completion = "Ah, Ihr habt es also geschafft den Stab zurückzuholen. Beeindruckend, {name}. Vielleicht seid Ihr genau der {class}, den ich suche.\n\nOh ja, Eure Belohnung...\n\n\n\nIhr habt sicherlich mehr erwartet, aber das kommt schon noch mit der Zeit. Fürs Erste soll die Möglichkeit Eure Belohnung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10174] = { id = 10174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch des Violetten Turms", description = "Jetzt könnt Ihr mithilfe des Stabs Kontakt zu dem Erzmagier aufnehmen.\n\nEr lebt im Violetten Turm, auf einer Insel im Süden. Der verfluchte Turm ist sowohl eine Zuflucht als auch ein Gefängnis für ihn. Mitglieder und Verbündete der Kirin Tor können weder hinein noch hinaus, weswegen ich meinen Meister nicht sehen kann.\n\nDer Stab kann die Verteidigung des Turms durchbrechen, jedoch nur, wenn er von jemandem, der nicht zu den Kirin Tor gehört, aktiviert wird.\n\nNehmt den Stab und benutzt ihn, um ein Abbild des Erzmagiers zu erschaffen. Sagt ihm, was passiert ist und beweist ihm, dass ich ihn nicht ganz enttäuscht habe.", sourceObjective = "Benutzt Erzmagier Vargoths Stab um Kontakt mit Erzmagier Vargoth aufzunehmen.\n\nFalls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz.\n\nBereitgestellter Gegenstand:", completion = "<Erzmagier Vargoth betrachtet Euch, als Ihr ihm Ravandwyrs Nachricht übermittelt.>\n\nRavandwyr hat alles, was ein Meister sich von einem Lehrling wünschen kann. Als ich ihm den Stab gab und ihm befohlen habe, zu fliehen, habe ich gehofft, dass er ihn benutzen würde, um jemanden zu finden, der mich nach dem Abzug von Kael'thas Truppen aus dem Turm befreien kann. Seitdem habe ich viel über den Fluch herausgefunden.\n\nEr kann gebrochen werden, aber dazu brauche ich Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10175] = { id = 10175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrall, Sohn Durotans", description = "Kehrt in Eure Welt zurück, {name}. Sucht meinen Enkelsohn und sagt ihm, dass sein Blut hier ist - in dieser zerschlagenen Welt.\n\nSagt ihm, dass das Erbe seines Vaters weiterlebt.\n\nSagt ihm alles...", sourceObjective = "Reist nach Orgrimmar und überbringt Thrall Geyahs Nachricht.", completion = "<Thralls Stimme wird dumpf wie ein fernes Donnergrollen.>\n\nIch... Ich habe eine Großmutter? Sie ist am Leben?", sourceObjectiveStatus = "unverified-source-field" }
quests[10176] = { id = 10176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ar'kelos der Wächter", description = "Jetzt, da Ihr alle Gegenstände, die ich benötige, um Kael'thas Fluch zu brechen, gesammelt habt, gibt es nur noch Eines zu tun. Als Kael'thas den Turm versiegelt hat, hat er einen arkanen Golem, der als Ar'kelos bekannt ist, auf dem Grund des Turms platziert.\n\nIhr müsst Ar'kelos besiegen, damit ich innerhalb des Turms wieder meine Magie wirken kann.\n\nWenn Ihr den Violetten Turm betretet, wird der Fluch Euch treffen.\n\nSobald Ihr Ar'kelos besiegt habt, steigt den Turm hinauf und unterstützt mich bei den Vorbereitungen für das Ritual.", sourceObjective = "Betretet den Violetten Turm in der Mitte von Kirin'Var und besiegt Ar'kelos. Sprecht danach mit Erzmagier Vargoth.", progress = "Endlich treffen wir uns.", completion = "Das habt Ihr gut gemacht, {name}. Ohne das Dämpferfeld wird es viel leichter für mich, die Magie vorzubereiten, mit der ich den Fluch des Turms endlich aufheben kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10177] = { id = 10177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Auchindoun", description = "Meine Spione in Auchindoun haben uns erschreckende Berichte geschickt. Seit seiner Explosion vor ein paar Jahren hat dieser Ort nichts als Ärger gebracht.\n\nDort ist etwas - mal wieder - ganz schön schief gegangen, und der Schattenrat bereitet sich auf einen Krieg vor. Auch wenn die Berichte viele Details verschweigen, müssen sie sich auf einen Krieg im Inneren vorbereiten.\n\nIhr müsst Euch zum Eingang des Schattenlabyrinths begeben. Mein Feldkommandeur, Mahfuun, wird Euch genau erklären, was zu tun ist.", sourceObjective = "Meldet Euch bei Feldkommandeur Mahfuun beim Eingang zum Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar.", completion = "Es wird langsam Zeit, dass Ihr kommt.\n\nMehlisah hat schon vor Tagen gesagt, dass sie Hilfe schicken würde. Und wir kämpfen hier schließlich schon eine ganze Weile!", sourceObjectiveStatus = "unverified-source-field" }
quests[10178] = { id = 10178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Spion To'gun", description = "To'gun, dieser Narr! Wir können hier kaum die Angriffe zurückhalten und er geht wieder hinein um Informationen zu sammeln und die anderen Spione zu retten!\n\nIch weiß nicht, ob ich ihn umarmen oder töten soll!\n\nDer Schattenrat muss uns mithilfe von Magie ausfindig gemacht haben, denn all unsere Spionen mussten hastig von dort fliehen. Die meisten von uns haben es nicht geschafft.\n\nBitte, wenn Ihr mutig genug seid, um das Schattenlabyrinth zu betreten, könntet Ihr dann nach To'gun Ausschau halten? Er ist schon eine ganze Weile fort, und ich befürchte das Schlimmste.", sourceObjective = "Findet Spion To'gun im Schattenlabyrinth von Auchindoun.", completion = "Was? Grik'tha hat Euch nach mir geschickt?\n\nIch weiß nicht, ob ich mich geehrt fühlen oder sie eine Närrin schimpfen soll!\n\nKönntet Ihr mir vielleicht aus diesem Käfig raushelfen? Es ist ein bisschen eng hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[10179] = { id = 10179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hüter von Kirin'Var", description = "Als klar wurde, dass unsere Expedition ohne Hoffnung auf Rückkehr nach Azeroth in der Scherbenwelt gefangen war, reisten die Kirin Tor zu den Ebenen von Farahlon und erbauten Kirin'Var. Ich habe die Verwaltung des Dorfs Hüter Dierwert übertragen, aber als Kael'thas und seine Streitkräfte mich hier im Violetten Turm einsperrten, ist mein Kontakt zu ihm abgebrochen.\n\nSucht ihn in Kirin'Var und helft ihm, wo Ihr nur könnt, {name}. Ich bin sicher, dass er seit dem Angriff alle Hände voll zu tun hat.", sourceObjective = "Sprecht mit Hüter Dierwert in Kirin'Var im Nethersturm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10180] = { id = 10180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann es einfach nicht lassen", description = "Ich habe versucht, Isfar davon zu überzeugen, hier in den sicheren Mauern von Shattrath zu bleiben, aber er wollte nicht auf mich hören. Stattdessen hat er sich entschlossen, wieder auf eigene Faust nach Auchindoun zu gehen.\n\nEr hatte zwar das Glück, den Sethekkhallen einmal zu entkommen, aber wenn sie ihn erwischen wird es kein zweites Mal geben.\n\nIch bewundere seine Entschlossenheit, seine Schwester zu befreien, aber ohne Hilfe wird er es nicht schaffen.\n\nFindet Isfar und sprecht mit ihm, {name}. Wenn Ihr ihn nicht davon überzeugen könnt, zurückzukommen, könntet Ihr ihm dann vielleicht helfen Lakka zu retten?", sourceObjective = "Sprecht mit Isfar in den Sethekkhallen in Auchindoun.", completion = "Ich hätte wissen sollen, dass er nach mir schicken würde. Er hat versucht mir auszureden, in die Sethekkhallen zurückzukehren, aber ich könnte nicht damit leben, wenn Lakka etwas zustoßen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10182] = { id = 10182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfmagier Dathric", description = "Das Schwert ist von außergewöhnlicher Qualität, fein geschmiedet und perfekt für einen Kampfmagier ausbalanciert. Auf dem Knauf der Waffe sind das Siegel der Kirin Tor und der Name \"Dathric\" eingraviert.\n\nWährend Ihr die Waffe in den Händen hin und her dreht, bemerkt Ihr, dass etwas mit dem Schwert nicht stimmt. Es fühlt sich an, als wäre es zwischen zwei Welten hin- und hergerissen. Könnte dies der Gegenstand sein, der Kampfmagier Dathrics Geist an diese Welt bindet?\n\nVielleicht zerbricht das Band, wenn Ihr es an seinen angestammten Platz zurückbringt, und befreit Dathrics Geist endgültig.", sourceObjective = "Sucht die Wohnung von Kampfmagier Dathric in der Zaubergasse und bringt die Klinge zurück in sein Waffenregal. Sprecht danach mit Hüter Dierwert in Kirin'Var.", completion = "Gut gemacht, {name}. Ich kann keine Rastlosigkeit mehr in Dathrics Geist spüren. Ich würde viel dafür geben, wenn ich noch einmal mit ihm sprechen könnte, aber es ist schon gut genug, dass er nun in Frieden ruht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10183] = { id = 10183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Area 52", description = "Ich studiere hier draußen den Nether - die astralen Strömungen und so weiter. Dies ist ein idealer Platz, weit weg von den Lichtern und dem Getöse der Stadt. Wenn ich diesen Schrott doch nur am Laufen halten könnte!\n\nHey, wisst Ihr, wenn Ihr nach Arbeit sucht, solltet Ihr nach Area 52 gehen! Das liegt gleich den Pfad hoch und bei der Weggabelung rechts.\n\nWarum bringt Ihr nicht einfach meine neusten Forschungsnotizen zu Raketenchef Doppeldecker? Ich bin sicher, er hat genug Arbeit für Euch, wegen des Raketenschiffs X-52 und so.", sourceObjective = "Bringt die Notizen des Netheorologen zu Raketenchef Doppeldecker in Area 52 im Nethersturm.", progress = "Stress, Stress. Keine Zeit verschwenden! Es gibt ein Raketenschiff, das gebaut werden will!\n\nWas wollt Ihr?", completion = "Oh, Kupfernickel hat sich also endlich entschlossen, seine Entdeckungen zu berichten, was? Faule Wissenschaftler!\n\nWas ist das?\n\n<Der Chef blättert ein paar Mal durch die Notizen mit einem deutlich skeptischen Gesichtsausdruck.>\n\nEr sagt, dass die gewaltigen Netherenergien, die durch den Nethersturm fließen, alles in nur ein paar Monaten in Stücke reißen werden.\n\nDas ist ungünstig - jetzt müssen wir den Zeitplan für das Raketenschiff etwas straffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10184] = { id = 10184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösartige Überbleibsel", description = "Die meisten Geister im Dorf sind nicht mehr als blasse Überbleibsel der Magier der Kirin Tor, die sie einst waren. Sie erinnern sich nicht mehr an ihr früheres Ich und streunen blind vor Wut um die Ruinen herum.\n\nDas war jedoch nicht immer so. Direkt nach dem Angriff waren die Geister zwar rastlos, aber nicht bösartig. Mit der Zeit sind sie jedoch immer aggressiver geworden. Ich traue mich nicht, in den südlichen Teil des Dorfs zu gehen, denn sie machen nicht einmal vor mir Halt. Beruhigt sie und lasst uns hoffen, dass Ihr Ärger dann verfliegt.", sourceObjective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr 20 abtrünnige Geister auf dem Ratsplatz tötet.", completion = "<Hüter Dierwert schüttelt langsam den Kopf.>\n\nSie haben das nicht verdient, aber es ist das Beste, was wir tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10185] = { id = 10185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimmer als der Tod", description = "Nachdem die Blutelfen Kirin'Var dem Erdboden gleichgemacht hatten, haben sie mit dem Bau eines großen Gebäudes im Nordwesten begonnen. Ohne die Kräfte des Erzmagiers können wir nicht genau sagen, was dort vor sich geht.\n\nEines ist jedoch klar. Die Anwesenheit der Blutelfen hat eine Flut von gefräßigen Manaelementaren entfesselt. Sie scheinen von den Ruinen der Zaubergasse angelockt zu werden und verursachen noch weitere Zerstörung... Wir können das nicht weiter zulassen.", sourceObjective = "Tötet 10 Magiertöter und 10 Manasucher und kehrt zu Hüter Dierwert in Kirin'Var zurück.", completion = "<Der Hüter sieht bestürzt aus.>\n\nIch kann die nächste Welle schon über den Horizont kommen sehen. Sie auszumerzen hilft vielleicht für den Moment, aber wir brauchen langfristige Maßnahmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10186] = { id = 10186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid eingestellt!", description = "Lasst mich der Erste sein, der Euch an Bord willkommen heißt, Juniortechniker dritten Grades {name}!\n\nWir bauen hier draußen mein Meisterwerk - die X-52 Netherrakete!\n\nDoch zuerst müssen wir alle Teile und den Treibstoff für sie besorgen. Und da kommt Ihr ins Spiel.\n\nZuerst brauche ich Kristalle, VIELE Kristalle, für die astrallithische Antriebsmatrix. Die Draenei hatten so viele, dass sie ihnen schon zu den Ohren herauswuchsen!\n\nBegebt Euch also zu den Ruinen von Enkaat und sammelt ein paar für mich! Und kümmert Euch nicht um die Draeneigeister.", sourceObjective = "Sammelt 10 Astrallithiummatrixkristalle und kehrt dann zu Raketenchef Doppeldecker in Area 52 im Nethersturm zurück.", progress = "Sieht es etwa aus, als wäre die X-52 Netherrakete bereit zum Abflug? Durchquere ich den wirbelnden Nether im meinen bequemen Kommandostuhl? Entdecke ich fremde neue Welten? Suche nach neuen Technologien und Geschäftsgelegenheiten? Dringe in Galaxien vor, die nie ein Goblin zuvor gesehen hat?\n\nNein!\n\nAlso hoffe ich, dass Ihr die Kristalle habt, nach denen ich Euch geschickt habe.", completion = "Pah! Die sehen aber grob aus. Vielleicht können wir sie in einer tertiären Antriebsmehrfachkammer einsetzen?\n\nTrotzdem gute Arbeit, Juniortechniker dritten Grades! Ihr werdet es sicher bald zum zweiten Grad schaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10187] = { id = 10187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht für den Erzmagier", description = "Auch wenn es hier sehr ungemütlich ist, muntert es uns ein wenig auf, dass der Erzmagier die Misere des Dorfs nicht vergessen hat.\n\n<Der Hüter schaut zum Turm hinauf.>\n\nEs ist lächerlich, oder? Manchmal scheint es, als trenne uns nur eine Wand aus einfachem Stein. Wie leicht vergisst man die Wand aus Magie.\n\nWenn Ihr so nett wärt, erklimmt den Turm und sagt Erzmagier Vargoth, dass wir Fortschritte im Dorf machen und bald einen Weg finden werden, um die Manakreaturen fernzuhalten.", sourceObjective = "Sprecht mit Erzmagier Vargoth im Violetten Turm im Nethersturm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10188] = { id = 10188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Siegel von Krasus", description = "Bevor wir uns vor so vielen Jahren von Azeroth aus aufmachten, haben die Kirin Tor unserer Expedition ein mächtiges Artefakt anvertraut, das Siegel von Krasus. Es hat uns im Kampf gegen die Orcs große Dienste erwiesen und könnte eine wichtige Rolle beim Brechen des Zaubers, der mich gefangen hält, spielen.\n\nAls Kael'thas mich jedoch meiner Besitztümer beraubt hat, gab er das Siegel an Zauberbinderin Maryana, die mit der Garnison zurückblieb. Hätte er gewusst, was er in seinem Besitz hatte, hätte er es nicht so einfach weggegeben.", sourceObjective = "Holt Euch das Siegel von Krasus von Zauberbinderin Maryana in der Manaschmiede Coruu, nordwestlich vom Violetten Turm.", progress = "Wenn ich vom Fluch des Turmes frei sein will, muss ich das Siegel haben.", completion = "Ah, es ist so wundervoll, wie ich es in Erinnerung hatte. Könnt Ihr die Macht, die davon ausgeht, spüren?\n\nNatürlich ist noch viel mehr zu tun, aber Ihr habt meinen tiefsten Dank dafür, dass Ihr mir das Siegel zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10189] = { id = 10189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede B'naar", description = "Vielleicht sind Euch Kaels Manaschmieden auf dem Weg hierher aufgefallen. Das sind diese großen violetten Gebäude, die Energie aus dem Himmel saugen.\n\nWir wurden von den Sha'tar hierher geschickt, um sie zu erkunden. Ihr könnt uns dabei helfen, indem Ihr eine Stammrolle von dort besorgt. Wenn wir eine Vorstellung davon hätten, wer dort als was arbeitet, wäre uns über alle Maßen geholfen.\n\nWir glauben, dass Hauptmann Arathyn, der eine Ballistentruppe direkt außerhalb der Manaschmiede B'naar leitet, eine solche Rolle besitzen könnte. Holt sie für uns.", sourceObjective = "Spionagemeister Thalodien in Area 52 möchte, dass Ihr zum Rand der Manaschmiede B'naar geht und die Stammrolle von B'naar von Hauptmann Arathyn besorgt.\n\nDas Abschließen von Aufgaben für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr bekommen, worum ich Euch gebeten habe, {name}?", completion = "Ausgezeichnet! Mit dieser Stammrolle können wir bessere Entscheidungen treffen, wenn wir die Anhänger Kaels bei den Manaschmieden angreifen.\n\nEigentlich schade, ich mochte es irgendwie, seine Lakaien wahllos zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10190] = { id = 10190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Batterien aufladen", description = "Ich habe die wichtige Aufgabe, die Maschinerie in diesen Ruinen zu sammeln, aber ich habe ein paar Probleme damit, alle meine Bots am Laufen zu halten.\n\nDie Phasenjäger - diese wurmähnlichen Dinger - stecken voller Energie! Man kann sie überall finden, wie sie aus dem Nether herausströmen.\n\nFüllt die Batterie mit diesem Ladeblaster, indem Ihr ihn bei einem Phasenjäger benutzt, wenn er sehr schwach ist, und ihm dann die restliche Energie entzieht.", sourceObjective = "Benutzt den Batterieladeblaster bei genügend Phasenjägern, um den Batterieladestatus auf 10 zu bringen. Bringt die Batterie danach zu Bot-Spezialistin Alley in den Ruinen von Enkaat im Nethersturm zurück.", progress = "Habt Ihr die Batterie schon aufgeladen?", completion = "He, passt auf, auf wen Ihr mit dem Ding zeigt! Ihr habt es auf \"töten\" gestellt!!!\n\nGut, es sieht so aus, als hättet Ihr die Batterie genügend aufgeladen. Ich baue sie gleich in Nr. V ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10191] = { id = 10191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nummer V lebt!", description = "Grüße, {race}. Ich bin aufgeladen und voll einsatzfähig!\n\nIn den Ruinen gibt es ein paar zerbrechliche Draeneimaschinen, die ich wieder beschaffen muss. Ich habe sehr edle Servos in den Stellgliedern meiner Handgelenke und bin mit den neusten verbrennungspneumatischen Beulensaugern ausgestattet. Die Maschinen mit der nötigen Sorgfalt zu behandeln ist also kein Problem für mich.\n\nLeider werden die Geister, die in den Ruinen spuken, mich sehr wahrscheinlich angreifen, daher brauche ich Euch und Eure Freunde als Beschützer.", sourceObjective = "Begleitet Maxx E. Million Nr. V durch die Ruinen von Enkaat und wieder in Sicherheit. Sprecht dann mit Bot-Spezialistin Alley außerhalb der Ruinen von Enkaat im Nethersturm.", progress = "So schnell schon zurück?\n\nIst mit Maxx E. Million Nr. V alles in Ordnung?!", completion = "Ihr habt es geschafft! Ihr habt es geschafft! Ich könnte Euch küssen!\n\nOh verdammt... der Maxx E. Million Nr. V hat schon wieder keine Batterie mehr. Naja, er hat seine Arbeit erledigt, und das ist das Wichtigste.\n\nRaketenchef Doppeldecker wird sich freuen, wenn er diese Draeneimaschinen in der X-52 Netherrakete einbauen kann! Das bedeutet eine Beförderung für mich! Ich bin so glücklich, ich muss Euch einfach belohnen!\n\nHier, sucht Euch etwas davon aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10192] = { id = 10192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus' Kompendium", description = "Die Kirin Tor haben unserer Expedition einen weiteren Gegenstand aus Krasus' Besitz mitgegeben. Es handelt sich dabei um sein Zauberbuch, das Krasus' Kompendium genannt wird. Da es alle Zauber enthält, die Krasus beherrschte, war es uns eine unersetzliche Hilfe im Krieg.\n\nBevor Kael'thas und seine Truppen Kirin'Var besetzt haben, wurde mir das Buch von einem rebellischen Schüler, der begierig darauf war, die Nekromantie zu erlernen, gestohlen. Der Lehrling und seine Anhänger haben sich aufgeteilt und das Buch heimlich studiert, wobei sie sich in ihren Häusern im Süden der Stadt eingeschlossen haben.", sourceObjective = "Holt Euch Krasus' Kompendium - Kapitel 1, Krasus' Kompendium - Kapitel 2 und Krasus' Kompendium - Kapitel 3 vom Ratsplatz von Kirin'Var.", progress = "Habt Ihr das Buch besorgt, {name}?", completion = "<Das Abbild von Erzmagier Vargoth scheint das Kompendium zu begutachten.>\n\nEs ist ein wenig mitgenommen, aber wenn man bedenkt, was es durchmachen musste, ist es ein Wunder, dass es überhaupt überlebt hat. Bewahrt es auf, {name}. Ohne das Buch haben wir kaum eine Chance, den Schutzschild des Turms zu durchbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10193] = { id = 10193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochrangige Ziele", description = "Von den Informationen aus der Stammrolle wissen wir nun, dass die geistigen Führer der Manaschmieden die Warpmeister und Warpingenieure sind. Sie überwachen die Gewinnung der so genannten \"Warpenergie\" in den Manaschmieden und kümmern sich um ihre Lieferung an entfernte Orte über ein unterirdisches Rohrsystem.\n\nDie einzigen weiteren Spezialisten in dieser Gegend sind die Geologen. Alle anderen sind entweder Teil des Militärs oder Magister - beide sehr leicht zu ersetzen.\n\nGeht dort hinein und tötet Kaels Spezialisten. Das wird ihn am meisten treffen.", sourceObjective = "Spionagemeister Thalodien in Area 52 möchte, dass Ihr in die Manaschmiede B'naar geht und 2 Warpmeister des Sonnenzorns, 6 Warpingenieure des Sonnenzorns und 8 Geologen des Sonnenzorns tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ich seid ein zuverlässiger Bursche. {name}. Wenn es etwas gibt, das ich noch mehr mag, als Kaels Schoßhunde zu töten, dann ist es, wenn das jemand anderes für mich erledigt.\n\nSo habe ich weniger Blut auf meinen Klamotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10194] = { id = 10194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimlicher Flug", description = "Während Ihr weg wart, haben meine Männer eine weitere Manaschmiede entdeckt. Sie befindet sich östlich von hier und ist als Manaschmiede Coruu bekannt.\n\nZwei meiner besten Spione haben einen geheimen Landeplatz außerhalb der Manaschmiede eingerichtet. Ihr sollt ihnen helfen, Kaels Truppen zu unterwandern und so viele Informationen wie möglich zu sammeln.\n\nSprecht mit Veronia außerhalb der Stadtmauer. Sie hat einen Windreiter vorbereitet, der Euch zur Manaschmiede Coruu bringen wird. Wenn Ihr dort seid, meldet Euch bei Caledis Morgenhell. Er wird Euch mit Eurer Mission vertraut machen.", sourceObjective = "Sprecht mit Veronia außerhalb von Area 52 und fliegt zur Manaschmiede Coruu.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Euren Flug zu organisieren war nicht gerade billig. Ich hoffe, ihr habt das Zeug zu diesem Auftrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[10196] = { id = 10196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Arakkoafedern", description = "Ich habe erste Erfolge darin, die Arakkoageister näher zu mir zu locken, aber sie sind immer noch sehr schüchtern. Vielleicht trauen sie sich näher, wenn ich meine Verkleidung verbessere.\n\nDazu benötige ich jedoch mehr Arakkoafedern wie die, die Ihr mir bereits gebracht habt. Wenn Ihr noch ein paar Federn bekommen könntet, würde ich sie Euch gerne abnehmen.", sourceObjective = "Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10197] = { id = 10197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine überzeugende Verkleidung", description = "Die Reihen von Kaels Armee zu unterwandern wird keine leichte Aufgabe. Mit meinen geringen Künsten der Illusion könnte ich einen von uns wie einen Anhänger Kaels aussehen lassen, aber es gibt einige Details in ihrer Uniform, die ich nicht nachbilden kann.\n\nBringt mir ein Set ihrer Roben, ein Paar ihrer Handschuhe und ein Gardistenmedaillon des Sonnenzorns. Das wird die Ergebnisse meiner Magie überzeugender machen. Sie tragen alle das gleiche, also solltet Ihr keine Probleme haben, diese Gegenstände zu finden.", sourceObjective = "Bringt ein Set Arkanistenroben des Sonnenzorns, ein Paar Forscherhandschuhe des Sonnenzorns und ein Gardistenmedaillon des Sonnenzorns zu Caledis Morgenhell bei der Manaschmiede Coruu im Nethersturm.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Kleidungsstücke, um die ich Euch gebeten habe?", completion = "Ausgezeichnet! Wenn ich mit Euch fertig bin, werdet Ihr Euch unbemerkt unter die Ränge des Sonnenzorns mischen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10198] = { id = 10198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationen sammeln", description = "Ich habe aus den Teilen, die Ihr mir besorgt habt, eine Uniform hergestellt. Sie ist magisch verbessert, um die Illusion perfekt zu machen.\n\nWir haben beobachtet, wie Kommandant Morgenschmied vor ein paar Minuten hineingegangen ist, um Arkanist Ardonis zu treffen. Er hatte sein gesamtes Gefolge an Wachen bei sich, daher ist das, was sie zu besprechen haben, sicher von größter Wichtigkeit. Versucht, etwas darüber herauszufinden.\n\nAch, das hätte ich fast vergessen. Haltet Euch von den arkanen Golems fern, die in der Manaschmiede patrouillieren. Sie werden Eure Illusion mühelos durchschauen.", sourceObjective = "Benutzt die Sonnenzornverkleidung, geht in die Manaschmiede Coruu und belauscht das Gespräch zwischen Sonnenzornkommandant Morgenschmied und Arkanist Ardonis.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Wir geht es mit der Bespitzelung voran, {name}? Ihr solltet Euch lieber beeilen. Ich werde hier schon ganz kribbelig.", completion = "Die Manaschmiede Duro ist in Schwierigkeiten? Ich bin mir sicher, dass Thalodien sich über diese Neuigkeiten freuen wird. Lasst uns zunächst diese Aufgabe hier fertigstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10199] = { id = 10199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kleine Extrakick", description = "So, nun fehlt mir noch die eine Zutat, die meinem Gebräu den entscheidenden kleinen Kick geben sollte, den wir brauchen.\n\nDer Stich der Netherrochen, die sich in der Nähe der Schieferhautschinder herumtreiben, ist ganz schön heftig. Bringt mir ein paar ihrer Stachel, damit ich das Gift aus ihnen gewinnen kann.\n\nIch bin mir sicher, dass die Ergebnisse explosiv sind!", sourceObjective = "Besorgt 5 Netherrochenstachel und bringt sie zu Stiefels in Area 52 im Nethersturm.", progress = "Wenn ich das Gift von genügend vielen Netherrochenstacheln extrahieren kann, bekommen wir vielleicht den explosivsten Kraftstoff, der gemischt wurde!", completion = "Wow! Ok, jetzt stimmt die Sache.\n\nLasst mich nur schnell die Boshaftigkeit aus diesen kleinen Schönheiten quetschen. Das sollte ein Raketentreibstoff werden, der alle von den Socken haut!\n\nHier, lasst mich das Schieferöl und das Stachelgift mischen, und dann schauen wir mal, was passiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[10200] = { id = 10200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Thalodien", description = "Es wäre besser, wenn diese Information so schnell wie möglich zu Thalodien gelangen würde. Ich bleibe hier und verwische unsere Spuren.\n\nEs wäre alles andere als gut, wenn Kael'thas herausfinden würde, was wir hier getan haben. Geheime Informationen sind immer am besten, wenn der Feind nicht weiß, dass man sie hat.", sourceObjective = "Kehrt zu Spionagemeister Thalodien in Area 52 im Nethersturm zurück.", completion = "Ihr überrascht mich immer wieder, {name}. Das war beeindruckende Spionagearbeit, die Ihr da in der Manaschmiede Coruu geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10201] = { id = 10201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Moment der Wahrheit", description = "Das Öl ist endlich für einen ersten Test bereit. Es scheint dickflüssig genug zu sein, um als hochwertiges Waffenöl zu dienen.\n\nDer einzige Weg, dies herauszufinden ist, einen Profi zu fragen. Seht Ihr Grek da drüben bei den Fahndungsanschlägen? Ich weiß, er ist nicht gerade ein Poet, aber mit Waffen kennt sich der Orc aus!\n\nBringt ihm eine Probe des Öl und bittet ihn, es an seiner Waffe auszuprobieren. Wenn er das getan hat, berichtet mir von seiner Meinung.", sourceObjective = "Geht zu Grek und bittet ihn, das Öl an seiner Waffe auszuprobieren. Bringt das Ergebnis zu Rakoria, wenn er fertig ist.", completion = "<Ihr berichtet Rakoria die Testergebnisse und sie fängt an, schallend zu lachen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10202] = { id = 10202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Abtrünniger", description = "Wir wurden vor Kurzem von einem Magister des Sonnenzorns kontaktiert, der uns beitreten möchte und schwört, dass er uns Informationen geben kann, die wir dringend benötigen. Wir haben uns mit unseren Informanten in Verbindung gesetzt, um zu überprüfen, ob es sich bei ihm um einen Doppelagenten handeln könnte, und er scheint sauber zu sein.\n\nEr befindet sich in der Manaschmiede Ara, was die Kommunikation etwas erschwert. Geht zu ihm und hört Euch an, was er zu sagen hat. Wenn er nur halb so hilfreich ist, wie er behauptet, können wir ihn sicher gut einsetzen.", sourceObjective = "Geht zur Manaschmiede Ara und sprecht mit Magister Theledorn.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Es ist an der Zeit, dass Ihr auftaucht. Ich habe mich schon gefragt, ob die Seher überhaupt interessiert sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[10203] = { id = 10203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unschätzbare Ausrüstung beamen", description = "Habt Ihr den Riss gesehen, der mitten durch Area 52 verläuft? Wir waren das! <Grinsen>\n\nIm Riss befinden sich allerlei Schätze für die X-52 Netherrakete! Das einzige Problem ist nur, dass wir nicht genug Ausrüstung haben.\n\nBis die Brennende Legion dort aufgetaucht ist, führten wir eine Operation in den Ruinen von Arklon aus. Ich möchte, dass Ihr diesen ultrastarken Dekonsolidierungsstrahler zu den Ruinen bringt. Benutzt ihn, um unsere Ausrüstung zum leitenden Ingenieur Zischeldruck im Riss zu beamen.\n\nJuniortechniker dritten Grades {name}, dies ist Eure Chance auf eine Beförderung. Vergeigt sie nicht!", sourceObjective = "Benutzt den ultrastarken Dekonsolidierungsstrahler, um den Hyperdreh-Grab-o-Matik, die servopneumatische Baggerklaue, den multispektralen Geländeabtaster und den großen Wagen voller Sprengstoff zurück nach Area 52 zu beamen. Meldet Euch dann beim leitenden Ingenieur Zischeldruck beim östlichen Ende des Risses in Area 52 im Nethersturm.", progress = "Ist es nicht schön hier? Und jeden Tag finden wir etwas Neues und Exotisches.\n\nWas für ein Glück, dass wir fast das Dorf zerstört haben, als wir hier gegraben haben.", completion = "Ihr müsst derjenige sein, der uns die ganze Ausrüstung von den Ruinen hergebeamt hat! Ein Hoch auf Euch!\n\nIch habe die Ausrüstung bereits an unsere Grabungsorte weiterverteilt. Jetzt können wir unsere Ausgrabungen im großen Stil überall auf der Insel durchführen! Die Netherrakete wird in null Komma nichts fertig werden!\n\nHmm, merkwürdig. Wartet mal, habt Ihr gesagt, Ihr habt uns vier Dinge zurück geschickt? Ich habe nur drei bekommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10204] = { id = 10204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutjuwelenkristalle", description = "Kaels Magister haben den Gebrauch von Manakristallen so weit perfektioniert, dass sie innerhalb von Sekunden große Mengen von Energie aufnehmen können.\n\nDas tun sie, indem sie kleinere Kristallsplitter von Blutjuwelen an größeren und vollen Kristallen aufladen.\n\nGeht zur Manaschmiede B'naar und besorgt einen dieser Splitter von einem Magister des Sonnenzorns und benutzt ihn, um Energie von einem größeren Kristall aufzunehmen.\n\nKehrt zu mir zurück, damit ich die Wirkung der Aura untersuchen kann. Keine Sorge, Nebenwirkungen sollten nur temporär sein.", sourceObjective = "Magistrix Larynna möchte, dass Ihr zur Manaschmiede B'naar geht und einen Blutjuwelensplitter von einem Magister des Sonnenzorns besorgt. Benutzt den Splitter in der Nähe von größeren Blutjuwelenkristallen und kehrt zu ihr in Area 52 zurück.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Hmmm... wie ich erwartet habe.\n\nSolch rohen Energien ausgesetzt zu sein erhöht unsere angeborene Sucht nach Magie gewaltig.\n\nIch bin nicht überrascht, dass Kael mit seinen Taten ungestraft davon kommt, wenn seine Angestellten praktisch die ganze Zeit betrunken sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[10205] = { id = 10205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sphärenräuber Nesaad", description = "Sphärenräuber Nesaad muss erledigt werden! Ich habe keine Ahnung, wie er meinen Angriff überleben konnte, aber er darf seine Taten dort auf keinen Fall fortführen.\n\nGeht zurück und vernichtet Nesaad. Er hat ein kleines Lager des Astraleums im südwestlichen Teil des Hügels.\n\nVersagt nicht, wie ich es tat, {name}.", sourceObjective = "Tötet Sphärenräuber Nesaad und kehrt dann zu Netherpirscher Khay'ji in Area 52 im Nethersturm zurück.", progress = "Ist es vorbei? Ist Sphärenräuber Nesaad tot?", completion = "Ich bin erleichtert zu hören, dass dieser Abschaum endlich vernichtet wurde. Ihr macht Eure Arbeit gut, {name}... darf ich so vermessen sein, Euch beim Namen zu nennen?\n\nWenn Ihr möchtet, habe ich eine weitere Aufgabe für Euch. Eine, die besonders wichtig ist. Jemand mit so offensichtlichen Talenten wie Ihr wird sie sicher leicht bewältigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10206] = { id = 10206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Eure Rolle", description = "Diese astralen Hampelmänner sind genauso opportunistisch wie wir, das muss man ihnen lassen. Aber niemand, und ich meine NIEMAND, wagt sich auf das Gebiet von B.U.M.M.!\n\nDer Hügel im Süden gehört uns!\n\nWenn wir die X-52 Netherrakete fertigstellen wollen, brauchen wir alle neuen Technologien, die wir in die Finger bekommen können. Und da die Astralen von uns stehlen, ist es nur gerecht, wenn wir es ihnen mit gleicher Münze heimzahlen.\n\nWarum geht Ihr nicht zum Hügel und schaut, ob Ihr ihnen etwas von ihrer Technologie vor der Nase wegschnappen könnt.", sourceObjective = "Sammelt 10 Stück Astraltechnologie und bringt sie zu Papa Mauschel in Area 52 im Nethersturm.", progress = "So schnell schon zurück? Nehmt mich besser nicht auf den Arm, {class}.\n\nDer Erfolg des X-52-Projekts hängt davon ab, dass wir das Zeug so schnell wie möglich bekommen!", completion = "Hehe, astrale Deppen!\n\nDanke, dass Ihr uns die Teile gebracht habt, {class}. Ich wette, wir können diese Babys gleich in die Rakete einbauen. Ich frage mich, was sie wohl bewirken? Wird sicher lustig, es herauszufinden!\n\nHm, lasst mich mal schauen ob ich noch ein wenig Wechselgeld für Euch in der Hosentasche habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10207] = { id = 10207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Base: Reaver's Fall REUSE", description = "Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, {class}. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 200 Schritte nach Osten und biegt bei der hervorragenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To'arch.\n\nUnd jetzt weggetreten!", sourceObjective = "Meldet Euch bei Vorpostenkommandant To'arch im Häschersturz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10208] = { id = 10208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verstärkung abschneiden", description = "Direkt im Osten liegt die Front der Legion. Entlang der Front befinden sich die höllischen Portale und Tore, mit deren Hilfe Verstärkung auf die Höllenfeuerhalbinsel und in die ganze Scherbenwelt gebracht wird. Wir müssen diese Portale zerstören!\n\nNehmt diese Zünder. Sie wurden in Area 52 hergestellt und benutzten die eigene Macht der Dämonen als Sprengstoff! Besiegt die Legion beim Portal Xilus und Portal Kruul und haltet nach dämonischen Runensteinen Ausschau. Benutzt den Zünder, um die vier Steine in den Portalen zu sprengen, sobald Ihr genug Steine beisammen habt... und dann genießt das Feuerwerk! Kehrt zu mir zurück, wenn Ihr Eure Aufgabe erfüllt habt.", sourceObjective = "Besiegt die Feinde um Portal Xilus und Portal Kruul herum, um dämonische Runensteine zu sammeln.\n\nBenutzt To'archs Zünder in Portal Xilus und Portal Kruul.\n\nKehrt danach mit To'archs Zünder zu To'arch im Häschersturz auf der Höllenfeuerhalbinsel zurück.", progress = "Die Legion ist bestimmt nicht auf unsere Überraschung gefasst, was, {name}?", completion = "Gut gemacht! Ich konnte die Explosionen fast bis hierher spüren!\n\nJetzt haben wir noch eine weitere Bombenmission für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[10209] = { id = 10209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörer Kanthins Preis", description = "Als nächstes müssen wir meinen Vertrauten, Gletscharius, aus den Händen des Blutelfenbeschwörers, der ihn gefangen hält, befreien. Beschwörer Kanthin war einst einer der erfahrensten Magister in der Streitmacht, die Kael'thas losgeschickt hat, um Kirin'Var auszulöschen. Es ist ganz normal, dass er meinen Vertrauten als Trophäe haben will.\n\nIch bin mir sicher, dass Kanthin, dumm wie er ist, versucht hat, Gletscharius zu seinem Diener zu machen. Ich habe herausgefunden, dass Kanthin sich jetzt in der Manaschmiede Duro aufhält, falls dies Euch etwas sagt.", sourceObjective = "Besiegt Beschwörer Kanthin in der Manaschmiede Duro auf der Insel nördlich des Sonnenzornpostens und holt den Stein des Gletscharius zurück.", progress = "Habt Ihr den Stein von Gletscharius bekommen?", completion = "<Ihr wisst nicht, ob es nur eine Verzerrung ist, aber der Erzmagier scheint zu lächeln.>\n\nJetzt, da ich all meine Besitztümer zurück habe, habe ich alles, um Kael'thas' Magie zu durchbrechen. Ich werde den Zauber gleich wirken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10210] = { id = 10210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A'dal", description = "Willkommen in Shattrath, {class}. Dies ist vielleicht der einzige Ort in der Scherbenwelt, in der Ihr so etwas wie Sicherheit empfinden könnt.\n\nEine Gruppe von Naaru, die als Sha'tar bekannt sind, hat die Dämonen von hier fortgejagt.\n\nWenn Ihr noch nie einen Naaru gesehen habt, solltet Ihr A'dal auf der Terrasse des Lichts besuchen. Der Anführer der Sha'tar ist der ehrfurchtgebietendste Anblick, den ich je gesehen habe. Ganz anders, als alles andere in diesem öden Land.", sourceObjective = "Sprecht mit A'dal, Anführer der Sha'tar in der Mitte der Terrasse des Lichts.", completion = "<Das Licht, das Eure Sinne erfüllt hat, als Ihr Euch A'dal nähertet, wird noch stärker, als Ihr ihn ansprecht. Melodische Klänge ertönen in Eurem Kopf.\n\nIhr seid hier sicher.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10211] = { id = 10211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stadt des Lichts", description = "Belästigt A'dal nicht mit Euren unbedeutenden Fragen, {class}. Er ist vielleicht das mächtigste Wesen, das Ihr je zu Gesicht bekommen werdet.\n\nIhr kommt mir nicht bekannt vor. Ich nehme an, Ihr wollt etwas über die Stadt erfahren?\n\nIhr müsst schon entschuldigen, dass ich selbst keine Führungen mache, aber ich muss einige Pläne mit A'dal besprechen. Vielleicht wärt Ihr ja mit einem herbeigerufenen Diener an meiner statt zufrieden? Ausgezeichnet!", sourceObjective = "Folgt Khadgars Diener und hört Euch an, was er zu erzählen hat. Kehrt nach dieser Aufgabe zu Khadgar zurück.", progress = "Die Geschichten der Lebewesen sind kurz, {name}. Die Geschichten der Städte dauern Jahre.", completion = "Ich hoffe, Ihr habt etwas über Shattrath erfahren, {name}. Lasst es einfach auf Euch wirken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10212] = { id = 10212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Mag'har", description = "Ich muss erst alles in Ordnung bringen, bevor ich gehe. Kehrt zur Großmutter zurück und sagt ihr, dass ihr Enkelsohn kommt.", sourceObjective = "Kehrt zu Großmutter Geyah in Garadar in Nagrand zurück.", completion = "Ihr seid wirklich der Held der Mag'har, {name}. Wärt Ihr nicht gewesen, wären wir sicher von den Ogern und Zerschlagenen überrannt worden.\n\nWir sind ein armes Volk, aber wir haben dennoch einige mächtige Artefakte. Bitte, ich bestehe darauf, dass Ihr Euch eines aus unserem Kasten nehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10213] = { id = 10213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Absturzstelle", description = "Als ich verwundet in der Wüste lag, habe ich gesehen, wie ein goblinscher Zeppelin abgestürzt ist. Er kam im Nordwesten runter, hinter dem Expeditionsrüstlager.\n\nDer Zeppelin hat gebrannt. Schreiende, brennende Goblins fielen wie Bomben vom Himmel. Ich hatte natürlich sehr große Schmerzen und viel Blut verloren. Vielleicht habe ich mir das alles auch nur eingebildet.\n\nWenn Ihr irgendwelche Überlebenden finden solltet, bietet ihnen eine Zuflucht hier im Rückenbrecherposten an.", sourceObjective = "Durchsucht die Absturzstelle nach Überlebenden.", completion = "Wir wurden von der Brennenden Legion abgeschossen, obwohl wir eine Friedensflagge geschwenkt haben. Wer hätte ahnen können, dass die Brennende Legion so gemein ist?\n\nWir können leider nicht mit Euch zum Rückenbrecherposten kommen. Wir müssen den Zeppelin reparieren und dann weiterziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10214] = { id = 10214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt diese Mine zum Beben!", description = "Die Mine wurde von diesem Gan'argpack überrannt, und zu allem Übel sind die Peons der Meinung, dass jetzt die richtige Zeit für ein Schläfchen ist! Ich weiß nicht, wie sie bei all dem Lärm aus der Mine schlafen können, aber das ist mein geringstes Problem.\n\nWenn wir dieses Gan'arggesindel nicht bald loswerden, wird Thrallmars Nachschub an Kupfer und anderen Materialien abgeschnitten. Ich habe schon Wachkommandant Krunk um Hilfe gebeten, aber er sagt, dass er keine Männer schicken kann, solange die Stadt angegriffen wird. Könnt Ihr mir helfen?", sourceObjective = "Tötet 15 Pioniere der Gan'arg und kehrt dann zu Großknecht Razelcraz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10216] = { id = 10216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit geht vor", description = "Shaffars Astrale haben uns ganz aus der Managruft ausgeschlossen. Zum Glück habe ich einen Plan. Auch wenn wir nicht durch die Eingangstür können, bin ich mir sicher, dass es innen viele Transporter gibt.\n\nIch möchte, dass Ihr zuerst den Weg für meine Gruppe freiräumt und dann einen der Transporter aktiviert, damit wir hineinteleportieren können.\n\nAktiviert den Transporter in der Kammer genau vor Shaffars Kammern, wenn Ihr den Weg freigemacht habt. Keine Sorge, ich werde Euch dafür entlohnen...", sourceObjective = "Konstrukteur Morphalius möchte, dass Ihr 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder tötet.\n\nWenn Ihr damit fertig seid, sucht den astralen Transporter in der Kammer vor Shaffars Kammer und aktiviert ihn.", progress = "Dieses Gerät hat über ein Dutzend Knöpfe, von denen Euch keiner bekannt vorkommt.", completion = "<Ihr schließt die Augen und drückt einen Knopf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10218] = { id = 10218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemandes Arbeit zahlt sich aus", description = "Wen habt Ihr erwartet?! Dieser Idiot Morphalius wurde entpriorisiert. Jetzt bin ich hier, um sein Chaos aufzuräumen. Alles, was ich von Euch will, ist, dass Ihr mir den Rücken freihaltet, während ich Shaffars Astralsammler durchgehe und ihnen alles entnehme, was sie gesammelt haben. Wenn ich meinen Auftrag erfolgreich abschließe, wird Haramad selbst Euch belohnen!\n\nWas sagt Ihr? Begleitet mich durch die Managruft und sammelt ein paar unglaubliche Schätze! Die meiste Arbeit habt Ihr ohnehin schon erledigt! Hinter uns ist nichts mehr am Leben, oder?", sourceObjective = "Begleitet Kryoingenieur Sha'heen sicher durch die Managruft, damit er die Astralmaterie aus Shaffars Astralsammlern entnehmen kann.\n\nMeldet Euch bei Nexusprinz Haramad außerhalb der Managruft beim Lager des Konsortiums, wenn Ihr erfolgreich wart.", completion = "Da dies Morphalius' Idee war, habe ich ihm seinen alten Job zurückgegeben. Gut gemacht, kleines Fleischwesen. Wirklich gut!\n\nDenkt daran, wenn Ihr je auf der Suche nach Arbeit und im Nethersturm seid, sucht mich auf der Sturmsäule auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[10220] = { id = 10220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt sie zum Zuhören", description = "Ich wurde hierher geschickt, Kontakt zu den unerschütterlichen Geistern herzustellen. Diese einst stolzen Soldaten der Allianz wurden vor langer Zeit besiegt, und nun spuken ihre Geister in den Ruinen im Westen.\n\nWenn sie sich uns anschließen würden, hätten wir einen mächtigen Verbündeten. Stellt Euch nur vor, eine Armee von untoten Kriegern, die sich unserem Feind entgegenstellt. Aber diese Untoten sind blind vor Hass und wollen sich meinen Vorschlag nicht anhören.\n\nVielleicht kann man sie zwingen, sich uns anzuschließen.", sourceObjective = "Mordiba möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 8 unerschütterliche Krieger und 6 unerschütterliche Zauberhexer beim Expeditionsrüstlager westlich des Rückenbrecherpostens tötet.", completion = "Die Unerschütterlichen haben die Macht der Horde gespürt. Vielleicht haben sie jetzt ja Lust, sich meinen Vorschlag anzuhören.", sourceObjectiveStatus = "unverified-source-field" }
quests[10221] = { id = 10221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dr. Bumm!", description = "{name}, mein früherer Schützling, Sparky Überschub, hat sich geweigert, während seiner Arbeit hier seinen Helm zu tragen und hat sich in den berüchtigten Dr. Bumm verwandelt!\n\nEr hat sich mit einem Großteil unserer Pionierausrüstung nach Nordosten aufgemacht! Seitdem sind er und seine Bummbots eine große Bedrohung für Area 52!\n\nIch möchte, dass Ihr zu seinem Lager außerhalb der Stadt geht und ihm ein Ende macht! Benutzt diese Bummbomben um ihn auszulöschen.\n\nUnd passt auf, dass Ihr ihm oder seinen Bummbots nicht zu nahe kommt!", sourceObjective = "Tötet Dr. Bumm und kehrt dann mit den guten Nachrichten zu dem leitenden Ingenieur Zischeldruck in Area 52 im Nethersturm zurück.", progress = "Habt Ihr uns vor den Verwüstungen durch Dr. Bumm gerettet? Ich verspreche Euch, dass es diesmal keine explodierenden Wagen gibt, auch wenn das wirklich spaßig war!\n\nWir sollten das wirklich öfter tun!", completion = "Ich werde Sparky immer vermissen. <Schnief> Aber jetzt, da wir wissen, dass Dr. Bumm uns nicht mehr tyrannisieren kann, werden wir alle besser schlafen.\n\nLasst Euch das ein Lehre sein. Kommt hier nicht ohne Netherhelm runter!\n\nNun, wie kann ich Euch dafür belohnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10222] = { id = 10222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garnison des Sonnenzornpostens", description = "Nachdem Prinz Kael'thas' Streitkräfte das Dorf zerstört und den Erzmagier im Turm eingesperrt hatten, haben sie sich zum Sonnenzornposten im Nordosten zurückgezogen. Die gleichen Männer, die unser Dorf zerstört und unsere Freunde getötet haben, stoßen nun auf ihren 'unglaublichen Sieg' an, während wir unsere Gefallenen nicht rächen können.\n\nWir dürfen diese Verbrechen nicht ungestraft lassen! Seid unser Instrument der Rache, {name}. Geht zum Sonnenzornposten und fordert das Leben der Verantwortlichen für dieses Verbrechen ein!", sourceObjective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr 10 Bogenschützen des Sonnenzorns tötet.", completion = "Was Ihr getan habt, kann die Gefallenen nicht zurückbringen, aber vielleicht kann es ihre Geister beruhigen. Obwohl ehrlich gesagt kein Blut der Welt meinen Zorn über Kael'thas Taten stillen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10223] = { id = 10223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit Daellis", description = "Den Blutelf, der den Angriff geführt hat, werde ich nie vergessen. Er trug einen Wappenrock mit einem Ding, was ich noch nie zuvor gesehen habe, über einer roten Rüstung.\n\nEr war wild und erbarmungslos, und kämpfte an der Front, wo man kaum einen anderen Blutelfenoffizier je zu Gesicht bekommt. Er war an diesem Tag für den Tod vieler Kirin Tor verantwortlich, aber er blieb nicht lange im Sonnenzornposten. Kael'thas hat ihn zur Manaschmiede Duro beordert, um bei ihrem Versuch, das Gebiet zu kontrollieren, zu helfen. Findet ihn, {name}, und bringt seinen Bogen für immer zum Schweigen.", sourceObjective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr Meister Daellis Morgenschlag tötet.", completion = "<Ihr seid Euch nicht sicher, aber es sieht so aus, als würde Hüter Dierwert gleich anfangen zu weinen.>\n\nEndlich ist es geschafft. Wenn ich könnte, würde ich meine Existenz selbst auslöschen, aber die Wahrheit ist, dass ich nicht loslassen kann. Für die Leute im Dorf ist es schwer, aber zumindest ehrlich. Ich schätze, das ist der Preis, den wir dafür bezahlen müssen, dass wir uns so sehr an diesen Ort gebunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10224] = { id = 10224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenzen für die Motoren", description = "Als Chefingenieur der X-52 ist es meine Pflicht dafür zu sorgen, dass die Hauptmotoren der Netherrakete tiptop in Schuss sind.\n\nUnglücklicherweise habe ich sie noch nicht gebaut.\n\n{class}, ich bin hier in einer Notlage! Ich habe fast alle Teile. Ich brauche nur noch einen Antriebskern.\n\nZum Glück bin ich der Meinung, dass wir die Essenz der Managespenster in der Nähe nutzen können, um die Motoren zu überbrücken.\n\nIhr findet die Managespenster überall bei diesen komischen leuchtenden Gräben im Norden der Insel. Außer hier in Area 52 natürlich.", sourceObjective = "Sammelt 7 Essenzen eines Managespensts und bringt sie zu Chefingenieur Trep bei Area 52 im Nethersturm.", progress = "Habt Ihr schon alle Essenzen?", completion = "Wow, das sind viele Essenzen!\n\nGut, schauen wir mal, was passiert, wenn ich sie mit den Astrallithiummatrixkristallen mische.", sourceObjectiveStatus = "unverified-source-field" }
quests[10225] = { id = 10225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung beim Chefingenieur", description = "{name}! Ich möchte, dass Ihr all diese Astrallithiumkristalle zu Chefingenieur Trep, meinem, äh, Ingenieurschef bringt.\n\nEr sollte wissen, was mit ihnen zu tun ist. Und wenn er es nicht weiß, dann sorgt dafür, dass er es herausfindet.", sourceObjective = "Bringt die Astrallithiummatrixkristalle zu Chefingenieur Trep in Area 52 im Nethersturm.", progress = "Äh, hallo. Ich bin hier ein wenig beschäftigt. Was habt Ihr da?", completion = "Oh, Astrallithiummatrixkristalle! Ja, die klingen wichtig.\n\nLasst sie uns dort drüben hinstellen und ich kümmere mich gleich um sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[10226] = { id = 10226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarenergieextraktor", description = "Verdammt, das hat nicht geklappt.\n\nOk, ich habe eine andere Idee. Ich habe Xyrol einen Elementarenergieextraktor herstellen lassen. Ich weiß nicht genau, was man mit dieser Energie anfangen kann, aber ich werde schon einen Verwendungszweck für sie finden.\n\nDie zerrissenen Rumpler und Sphärenentartungen auf dem Felsvorsprung der Schwindenden Weite im Süden haben genau das, was wir für die Motoren brauchen!\n\nDer Extraktor wird ihre Energie in eine feste Form bringen, die Ihr aufsammeln könnt, nachdem Ihr sie besiegt habt.", sourceObjective = "Extrahiert 5 Einheiten Elementarenergie und bringt sie zu Chefingenieur Trep in Area 52 im Nethersturm.", progress = "Habt Ihr die Energie von diesen Elementaren schon? Oh, keine Hektik oder so. Hängt ja nur mein Leben und meine Karriere davon ab.", completion = "Das ist besser! Gut, ich glaube, jetzt sind wir im Geschäft.\n\nLasst mich dieses Zeug nur kurz in das Zau-ba-Ding hier tun, und ich bin sicher, dass es gleich einen voll funktionsfähigen Phasenantriebskern ausspuckt.\n\nOh, he, ich sollte Euch vielleicht dafür belohnen, dass Ihr meine Haut gerettet habt. Hehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10227] = { id = 10227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe tote Draenei", description = "Ich sehe tote Draenei. Sie sind überall.\n\nPah, niemand glaubt mir, weil ich ein Kind bin. Nichtmal meine Mama glaubt mir.\n\n<Ha'lei zeigt auf Ramdor.>\n\nEr glaubt mir. Er sieht sie auch. Und er regt sich darüber auf!\n\nIrgendwie ist es lustig. Ich sehe Geister und die Leute lächeln mich nur an und tätscheln mir den Kopf, um mich zu beruhigen. Ramdor sieht Geister und sie halten ihn für verrückt. Ich hoffe echt, dass ich nie erwachsen werde!\n\nVielleicht solltet Ihr erst mit Ramdor reden, bevor Ihr da hinein geht. Er war einst ein Totenpriester.", sourceObjective = "Sprecht mit Ramdor dem Wahnsinnigen auf dem Knochenhaufen außerhalb der Auchenaikrypta.", completion = "Das Kind hat Recht. Ich war einst ein \"Totenpriester\".\n\n<Ramdor zuckt zusammen.>\n\nWas für ein abstoßender Titel. Innen findet Ihr die Überbleibsel meines Ordens. Sie sind natürlich alle verrückt! Wahnsinnig! Ich denke, ich habe mich sehr hervorgehoben, da ich der letzte von ihnen mit gesundem Menschenverstand war. Natürlich wurde ich wegen meines Glaubens exkommuniziert.\n\nWas, sagtet Ihr, glaube ich noch gleich?", sourceObjectiveStatus = "unverified-source-field" }
quests[10228] = { id = 10228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ezekiel", description = "Ich bin der Meinung, dass die Toten, um die wir uns seit den letzten 500 Jahren gekümmert haben, in Ruhe gelassen werden sollten. Aber Maladaar hat andere Pläne. Er hat sich in die Krypta des Gedenkens zurückgezogen, um seine Experimente zu beginnen... Nekromantie.\n\nIch hoffe, Ihr hattet nicht vor, dorthin zu gehen... nicht bevor Ihr mir geholfen habt, diese verdammten Geister loszuwerden. Ich weiß, wo sie ihre Schätze aufbewahren, {race}. Jetzt habe ich Eure Aufmerksamkeit, was?\n\nBringt mir das Buch der Toten, das sich im Besitz des Aldors Ezekiel von Shattrath befindet.", sourceObjective = "Sprecht mit Ezekiel von Shattrath in Shattrath.", completion = "Buch der Toten? Nie davon gehört... Worum geht es überhaupt? Wer hat Euch geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[10229] = { id = 10229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Folianten entziffern", description = "Dieser Foliant scheint eine Art Geschichtsbuch zu sein, das in einer Geheimschrift der Allianz geschrieben wurde. Althen der Historiker im Rückenbrecherposten hat die Unerschütterlichen eine Zeit lang studiert. Vielleicht kann er die Geheimschrift der Allianz entziffern und das Buch lesen.", sourceObjective = "Bringt den geheimnisvollen Folianten zu Althen dem Historiker im Rückenbrecherposten.", progress = "Was ist das? Ein Buch von einem unerschütterlichen Geist? Wie merkwürdig. Lasst es mich anschauen, vielleicht kann ich mehr über die Geschichte der Unerschütterlichen erfahren.", completion = "Ich habe mein ganzes Unleben lang alte Geschichte studiert, doch nie zuvor etwas wie dieses Buch gesehen. Er erzählt die gesamte Geschichte des Rüstlagers, sogar die Ereignisse nach seiner Zerstörung.\n\nDie Unerschütterlichen haben ihre Geschichte aufgeschrieben, sogar nach ihrem Tod in der Schlacht. Mit diesem Buch können wir die Unerschütterlichen verstehen und sie sicher davon überzeugen, sich uns anzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10230] = { id = 10230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kampfhorn", description = "Vielleicht haben wir uns ganz falsch an diese \"Unerschütterlichen\" herangewagt.\n\nDieser Foliant sagt, dass das Expeditionsrüstlager der Allianz vor langer Zeit von den Orcs und den Todesrittern zerstört wurde. Die Unerschütterlichen wurden dort als rachedurstige Geister in einer ewigen Schlacht gegen die Klans der Höllenorcs gefangen.\n\nSie denken nur an Rache. Wir müssen ihnen die Chance geben, ihre meist verhassten Feinde zu besiegen. Kehrt noch einmal in die Ruinen des Rüstlagers zurück und sucht Feldkommandant Thalvos. Er trägt ein Kampfhorn, das die Unerschütterlichen rufen kann. Bringt es mir.", sourceObjective = "Besorgt Euch das Kampfhorn der Unerschütterlichen von Feldkommandant Thalvos und bringt es zu Althen dem Historiker im Rückenbrecherposten.", progress = "Wir müssen den Unerschütterlichen bald helfen. Wenn wir sie davon überzeugen können, sich uns anzuschließen, hat die Horde einen starken Verbündeten.", completion = "Gut gemacht, {name}. Dieses alte Horn wird uns helfen, die Unerschütterlich zu rufen.\n\nNatürlich nur, wenn sie es möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10231] = { id = 10231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welches Buch? Ich sehe kein Buch.", description = "Ramdor? Hmm, mal überlegen... Ramdor... Oh ja, der Totenpriester. Was will er denn mit dem Buch? Nun, es ist gleichgültig. Ja, ich habe Euch angelogen und nein, ich habe das Buch nicht. Nicht mehr zumindest. Es wurde gestohlen. Wahrscheinlich von einem dieser widerlichen Flüchtlinge.\n\nIm Übrigen existiert Auchindoun nicht mehr. Wir haben keine Verwendung mehr für das Buch. Wenn Ihr es findet, könnt Ihr es behalten.\n\nWie schon gesagt, ich habe ein paar dieser Grobiane letzte Woche um die Terrasse herumschleichen sehen. Fangt mit Eurer Suche bei ihnen an. Wahrscheinlich spielen sie irgendwo im Armenviertel Würfelspiele.", sourceObjective = "Ezekiel sagt, dass das Buch gestohlen wurde. Eure einzige Spur führt Euch zu den Grobianen. Schaut nach, ob sie irgendwelche Informationen haben.", progress = "Was willsu?", completion = "Ok, Ok! Tut uns nicht weh. Wir hatten das Buch, aber wir haben es verkauft...", sourceObjectiveStatus = "unverified-source-field" }
quests[10232] = { id = 10232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion in Trümmern", description = "Die Brennende Legion ist auf unserem Grund im Trümmerfeld, den Pfad hinunter und über die Brücke nach Osten, einmarschiert!\n\nDas könnte ein großes Problem für uns sein! Die Legion in den Ruinen von Arklon und jetzt auch noch hier! Langsam sieht es für uns und das Raketenprojekt hier in Area 52 schlecht aus!\n\n{name}, ich möchte, dass Ihr dorthin geht und mit den Dämonen fertigwerdet! Ich würde es ja tun, aber ich bin kein Kämpfer.\n\nJa, das riecht nach Ärger, ich fühle es.", sourceObjective = "Tötet 5 Schicksalsschmiede der Mo'arg und 15 Ingenieure der Gan'arg. Kehrt danach zu Papa Mauschel in Area 52 im Nethersturm zurück.", completion = "Nun, das sind gute und schlechte Nachrichten zugleich. Wir haben ihnen einen Schlag versetzt, aber ich weiß nicht, wie es weitergehen soll, wenn die Brennende Legion überall im Nethersturm frei herumrennt - und näher kommt.\n\nIch habe das Gefühl, dass wir einen Gang hochschalten müssen. Ich hoffe, Ihr könnt uns dabei helfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10233] = { id = 10233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Sonnenzornposten anzünden", description = "Die Garnison des Sonnenzornpostens auszulöschen ist nicht genug, um die Blutelfen davon abzuhalten, ihn erneut zu beziehen. Kael'thas Anhänger sind eifrig und hartnäckig. Sobald im Sonnenzorn noch ein Stein auf dem anderen steht, ist dies praktisch eine Einladung für sie, zurückzukehren.\n\nNein, der Posten muss völlig zerstört werden. Sorgt dafür, dass ihre Zelte und Artillerie zu Asche zerfallen!\n\n<Der Geist ballt die Fäuste.>\n\nStehlt die Fackeln von den Flammenbewahrern des Sonnenzorns um Eure Aufgabe zu erfüllen, {name}.", sourceObjective = "Benutzt eine flammende Fackel, zerstört 4 Sonnenzornballisten und 4 Sonnenzornzelte und kehrt dann zu Zaubererleutnant Morran in Kirin'Var zurück.", completion = "<Zauberhexerleutnant Morran nickt grimmig.>\n\nDie Kirin Tor heißen Zerstörung im Allgemeinen nicht gut, aber um unseren Feind zu vernichten überwinden wir jeden Skrupel. Sogar im Tod.", sourceObjectiveStatus = "unverified-source-field" }
quests[10234] = { id = 10234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Müll eines Dämons", description = "Ihr seht aus, als wärt Ihr <ein fähiger junger Mann/eine fähige junge Frau>! Ich habe mich gefragt, ob Ihr mir vielleicht zur Hand gehen könntet.\n\nIm Osten befindet sich das Trümmerfeld, auf dem die Brennende Legion Einzug gehalten hat. Es ist voller Teufelshäscherteile. Dort liegen auch ein paar kleinere Teile herum, um die sie sich nicht zu scheren scheinen.\n\nIch möchte, dass Ihr dorthin geht, und mir ein paar dieser kleineren Teile eines Teufelshäschers besorgt!", sourceObjective = "Sammelt 10 Teile eines Teufelshäschers und bringt sie zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", progress = "Habt Ihr die Teile schon? Wir haben nur wenig Zeit, da die Legion überall gleichzeitig in unser Gebiet vorrückt.", completion = "Ich denke, die müssen reichen. Wenn wir sie nur fortjagen könnten!\n\nHe, da fällt mir etwas ein!", sourceObjectiveStatus = "unverified-source-field" }
quests[10235] = { id = 10235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammnisklaue die Krallen stutzen", description = "Wisst Ihr, was sie entmutigen würde? Wenn wir ihren Anführer erlegen!\n\nWie ich gehört habe, klappt das immer. Und wenn sie sehen, dass so <ein knallharter/eine knallharte:c> {class} wie Ihr ihren Anführer erledigt, dann ziehen sie sicher den Schwanz ein und rennen weg!\n\nGeht dorthin zurück und erlegt den Großen, den sie Verdammnisklaue nennen. Ich habe gehört, dass er sich im östlichen Teil den Trümmerfelds unter dem Rohr aufhält.\n\nBringt mir seine Klaue! Vielleicht können wir sie brauchen.", sourceObjective = "Besorgt Euch Verdammnisklaues Hand und bringt sie zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", progress = "Schon mit Verdammnisklaue abgerechnet?", completion = "Er, äh... er hat was gesagt? SIE WOLLEN AREA 52 ANGREIFEN?\n\nOh, das ist nicht gut... nicht gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[10236] = { id = 10236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Scherbenwelt ist doof!", description = "Ich kann es kaum fassen, dass ich Beutebucht verlassen habe, um in die Scherbenwelt zu kommen. Mein Vetter Quack Lufthans hat mir versprochen, dass ich hier ein Vermögen machen würde, aber stattdessen ist er in seinem Zeppelin auf und davon und hat mich hier zurückgelassen. Nun versuche ich, mir einen sehr bescheidenen Lebensunterhalt mit der Mine zu verdienen.\n\nAber wie soll ich denn überleben, wenn ich dauernd von Höllenebern und Dämonen und Höllenorcs angegriffen werde? Mein Schredder hier ist gestern kaputt gegangen und die Höllenorcs haben meine Ersatzteile gestohlen. Sie haben die Teile in die Große Kluft im Südwesten gebracht und vielleicht dort fallenlassen.", sourceObjective = "Großknecht Razelcraz möchte, dass Ihr ihm 6 Schredderteile besorgt. Kehrt danach zu ihm bei der Mine nordwestlich von Thrallmar zurück.", progress = "Habt Ihr schon ein paar Ersatzteile für meinen Schredder gefunden? Ich möchte ihn wirklich gerne reparieren, damit ich mich weiter dem Bergbau in der Mine widmen kann. Irgendwie muss ich ja ein wenig Geld verdienen. Und wenn ich davon nur eine Fahrkarte nach Beutebucht kaufe. Ohne Rückfahrt!", completion = "Hurra, Ihr habt ein paar Teile gefunden! Jetzt kann ich meinen Schredder hoffentlich wieder zum Laufen bringen. Wenn ich genug Geld verdiene, kann ich vielleicht wieder zurück nach Beutebucht.\n\nIch hoffe, dass mein Vetter Quack Lufthans mit seinem blöden Zeppelin abstürzt. Ich kann es nicht fassen, dass er mich so hinterhältig in die Scherbenwelt gelockt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10237] = { id = 10237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Area 52!", description = "{name}, Ihr müsst so schnell wie möglich nach Area 52 zurückkehren! Beeilt Euch!\n\nSagt dem Raketenchef, dass die Brennende Legion hinter uns her ist!", sourceObjective = "Überbringt Raketenchef Doppeldecker in Area 52 in Nethersturm die schlechten Nachrichten.", completion = "Ha, Ihr macht Witze, oder? Die Brennende Legion gibt uns die Schuld daran?\n\nAber IHR wart das!\n\nOh, ich habe Kopfschmerzen, die so groß wie diese Rakete sind! Ok, ok, wir müssen uns einen anderen Plan einfallen lassen.\n\nWenn die Brennende Legion denkt, dass sie hierher kommen, unser Dorf zerstören und meinen Traum von einer Reise durch den wirbelnden Nether ruinieren kann, dann hat sie sich aber getäuscht.\n\nUnd ich kenne genau den richtigen Goblin, der uns dabei helfen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10238] = { id = 10238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man Goblins zubereitet", description = "Warum sollten die Höllenorcs denn meine Schredderteile stehlen wollen? Ich hasse sie so. Sie schleichen sich einfach in mein Lager hier und klauen immer meine Sachen. Vor ein paar Tagen haben sie drei meiner Peons gestohlen! Jetzt sind alle anderen Peons abgehauen, weil sie Angst hatten, von den Höllenorcs gefressen zu werden.\n\nIch kann meine Mine ohne Peons nicht betreiben. Wenn Ihr meine gestohlenen Peons retten könntet, kommen die anderen vielleicht auch wieder zurück. Die Höllenorcs haben ihre Lager entlang des Walls im Südwesten.", sourceObjective = "Rettet Manni, Moh und Jakk aus den Lagern der Höllenorcs und bringt sie zu Großknecht Razelcraz bei der Mine nordwestlich von Thrallmar zurück.", progress = "Habt Ihr meine Arbeiter schon gerettet? Bitte beeilt Euch, ich fürchte, dass sie gefressen werden, und sie schmecken wahrscheinlich nicht so gut. Wenn sie richtig schrecklich schmecken, werden die Höllenorcs vielleicht richtig böse auf mich.", completion = "Vielen Dank, dass Ihr meine Peons gerettet habt. Vielleicht kann ich sie jetzt dazu bringen, meinen Schredder mit den Teilen, die Ihr gefunden habt, zu reparieren. Dann kann ich wieder etwas Geld verdienen und aus der Scherbenwelt abhauen. Ich kann es kaum abwarten, wieder in Beutebucht zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10239] = { id = 10239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mögliche Energiequelle", description = "Wir sind nicht die Einzigen, die unter dem Zufluss von Manakreaturen leiden. Auch die Blutelfen sind darüber besorgt, ich weiß jedoch nicht, warum.\n\nWas immer sie da drüben tun mögen, sie scheinen nicht damit aufzuhören. Stattdessen erfinden sie immer neue Methoden, um sie zu töten. Die wirksamste davon beinhaltet eine magische Verteidigung, die von einer Art konzentrierter Energie gespeist wird.\n\nSammelt einige dieser Energiequellen und bringt sie mir. Scheut Euch nicht, die Blutelfen zu töten, wenn sich eine Gelegenheit ergeben sollte.", sourceObjective = "Zaubererleutnant Morran in Kirin'Var möchte, dass Ihr ihm 10 Energieisolationswürfel von den Blutelfen der Manaschmiede Coruu bringt.", progress = "Konntet Ihr ein paar ihrer Energiequellen sammeln?", completion = "<Morran dreht einen der Würfel vorsichtig in der Hand.>\n\nIch glaube nicht, dass ich je zuvor so etwas gesehen habe. Es steckt sicher eine Menge Energie darin, aber es ist rohe Energie. Wir müssen vorsichtig damit sein, aber ich glaube, dass wir einen Weg finden können, wie man sie zur Abwehr der Manakreaturen einsetzen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10240] = { id = 10240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Verteidigung errichten", description = "Wir sind dabei, eine Verteidigung um das Dorf herum zu errichten, die mit der Energiequelle der Blutelfen gespeist wird. Ich kann nicht garantieren, dass sie funktionieren wird, aber wir müssen es versuchen.\n\nWenn nicht werden die Manakreaturen weiterhin die Geister der gefallenen Kirin Tor verspeisen.\n\nBenutzt dieses Gerät bei den kleinen Runen um die Verteidigung des Dorfes herum, um die Energie dort freizusetzen. Wenn ich das Feld korrekt gewebt habe, sollten wir die Wirkung bemerken, sobald Ihr das Gerät bei jedem Punkt benutzt habt.", sourceObjective = "Benutzt das Gerät zur Aktivierung von Runen bei der östlichen Rune, der nordöstlichen Rune und der westlichen Rune. Die Runen befinden sich entlang der Verteidigung der Zaubergasse und des Ratsplatz von Kirin'Var. Kehrt zu Zaubererleutnant Morran zurück, wenn Ihr die Aufgabe erfüllt habt.", progress = "Habt Ihr alle Runen aktiviert? Ich bin so gespannt, ob wir die Methode der Blutelfen hier verbessern können. Was einer von Kael'thas Leuten tun kann, kann ein Kirin Tor noch besser!", completion = "Ausgezeichnete Arbeit. Drückt die Daumen, {name}. Ich werde das Schild jetzt aktivieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10241] = { id = 10241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablenkung in der Manaschmiede B'naar", description = "Wir wurden von Sha'tar hierher geschickt, um die Manaschmieden, die Kael'thas' Armee hier betreibt, zu untersuchen. Aber die Seher drohen damit, ihre Spionagearbeiten nicht durchzuführen, wenn wir sie nicht militärisch unterstützen.\n\nWir können uns nicht erlauben, dass diese Mission wegen politischen Differenzen den Bach hinunter geht, daher haben wir uns einverstanden erklärt, die Verteidigung der Manaschmiede zu schwächen, damit die Seher ihre Arbeit verrichten können.\n\nBeweist Eure Loyalität gegenüber den Aldor und tötet die Magister und Blutwärter des Sonnenzorns, die die Manaschmiede B'naar bewachen.", sourceObjective = "Tötet 8 Magister des Sonnenzorns und 8 Blutwärter des Sonnenzorns und kehrt dann zu Exarch Orelis in Area 52 zurück.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Ruf bei den Sehern.", progress = "Habt ihr Eure Aufgabe erfüllt, {name}?", completion = "Ausgezeichnete Arbeit, {name}. Die Seher haben dank Eures Ablenkungsmanövers wichtige Informationen sammeln können. Vielleicht teilen sie sie dieses Mal tatsächlich mit uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[10242] = { id = 10242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rückenbrecherposten", description = "{name}, meine Ausrüstung hier ist leider nicht für alle Tests, die ich durchführen möchte, geeignet. Mein Kollege Apotheker Albreck im Rückenbrecherposten verfügt jedoch über alle Hilfsmittel, die man dazu braucht.\n\nIch habe eine Blutprobe des Blutenden Auges, die mir ein Agent aus Thrallmar besorgt hat. Bringt diese Probe zu Albreck und erlaubt ihm, sie zu untersuchen.\n\nSprecht mit Schwadronskommandant Brack, um zum Rückenbrecherposten zu kommen. Er befindet sich in der Nähe der Wyvern im Süden.", sourceObjective = "Apothekerin Zelana beim Häschersturz möchte, dass Ihr mit Schwadronskommandant Brack sprecht, um auf einem Wyvern zum Rückenbrecherposten zu fliegen. Bringt die Blutprobe des Blutenden Auges zu Apotheker Albreck im Rückenbrecherposten.", progress = "Willkommen im Rückenbrecherposten. Wie kann ich Euch dienen?", completion = "Ein Bluttest also? Es wird mir ein Vergnügen sein. Ich arbeite immer gerne mit Blut...", sourceObjectiveStatus = "unverified-source-field" }
quests[10243] = { id = 10243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Technologie der Naaru", description = "Die Seher haben eine Stammrolle der Manaschmiede B'naar in die Hände bekommen und sind nun dabei, gezielt nach Anschlagsopfern zu suchen.\n\nSie haben jedoch eine kleine Information übersehen, die an den Rand der Schriftrolle gekritzelt wurde. Es scheint eine Art Passwort oder Code zu sein, wie sie für den Zugang zu von den Naaru erschaffenen Technologien wie der Exodar oder der Festung der Stürme benutzt werden.\n\nGeht in die Manaschmiede und haltet nach einer Steuerungskonsole Ausschau. Schreibt die Anzeige so gut es geht auf dieser Rolle ab. Wir müssen unseren Verdacht über die Herkunft von Kaels Technologie erhärten.", sourceObjective = "Geht in die Manaschmiede B'naar und sucht die Steuerkonsole von B'naar.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Die Symbole sehen fremdartig und unlesbar aus.", completion = "Ihr öffnet die Rolle und bereitet Euch vor, die merkwürdigen Symbole abzuschreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10244] = { id = 10244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liesmich", description = "Ihr zerbrecht das Siegel des ziemlich großen Folianten und könnt nicht verstehen, was dort geschrieben steht. Es schein die Sprache der Dämonen zu sein.\n\nIhr könnt jedoch die Bilder erkennen, die ihre eigene Geschichte erzählen.\n\nEs handelt sich eindeutig um eine Bauanleitung für Teufelshäscher, und Ihr wisst ganz sicher, dass Mama Mauschel sich das gerne anschauen würde.", sourceObjective = "Bringt die Bauanleitung für Teufelshäscher zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10245] = { id = 10245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steuerungsabschrift von B'naar", description = "Ihr versucht die Formen abzuschreiben, als sie an Euren Augen vorbeiziehen. Die Ergebnisse sind nicht gerade genau, aber sie sollten genügen, um den Verdacht der Aldor zu bestätigen.", sourceObjective = "Bringt die Steuerungsabschrift von B'naar zu Anachoret Karja in Area 52 im Nethersturm.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Wollen wir mal schauen, was Ihr da habt, {name}.", completion = "Gut gemacht, {name}. Gebt mir ein paar Augenblicke, um die Abschrift zu lesen.\n\nIhr habt den Dank der Priesterschaft, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10246] = { id = 10246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Manaschmiede Coruu", description = "Euer Erfolg in der Manaschmiede B'naar war sehr bemerkenswert. Ich bin sicher, dass Anachoret Karja Euch bitten wird, Eure Leistung als Nächstes in der Manaschmiede Coruu zu wiederholen.\n\nWir haben erfahren, dass ein besonders wichtiges Regiment von Arkanisten und Forschern des Sonnenzorns dort stationiert wurde. Wir würden sie gerne angreifen. Wenn es Euch gelingt, wird das ein vernichtender Schlag für die Streitkräfte unseres Feindes sein.", sourceObjective = "Reist zur Manaschmiede Coruu und tötet 8 Arkanisten des Sonnenzorns und 5 Forscher des Sonnenzorns. Kehrt zu Exarch Orelis zurück, wenn Ihr Eure Aufgabe erledigt habt.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ausgezeichnete Arbeit, {name}. Mit Eurem Einsatz schaffen wir es sicher, den Feind zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10247] = { id = 10247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dr. h. c. tüft. Vomisa", description = "Am Rand des Dorfes im Osten befinden sich die Versuchsgründe. Unser Spitzenobertüftler, Doktor Vomisa, hat hier ein wenig mit einer Kombination aus Teufelshäschertechnologie, Astraltechnologie und natürlich Goblintechnologie herumgespielt.\n\nDas verdanken wir nicht zuletzt Euren Sammelbemühungen, Juniortechniker dritten Grades {name}!\n\nSucht ihn auf! Ich bin mir sicher, dass er einen Weg weiß, wie Area 52 gerettet werden kann.\n\nUnd weil er Euch sicher als Versuchskaninchen einsetzen möchte, würde ich an Eurer Stelle lieber ein paar Freunde mitbringen. Nur für den Fall.", sourceObjective = "Sprecht mit Dr. h. c. tüft. Vomisa in den Versuchsgründen im Nethersturm.", completion = "Wie es scheint, haben wir großes Glück, junger Mann.\n\nIch habe gerade neulich meine neuste Erfindung, den Schrotthäscher X6000, fertig stellen können!\n\nUnd Ihr habt die Ehre, mir dabei zu helfen, ihn zu testen. Dann können wir ihn zur Verteidigung von Area 52 einsetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10248] = { id = 10248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Du, der Roboter", description = "Dr. h. c. tüft. Vomisa zu Euren Diensten. Hier, nehmt diese Steuerung. Ich möchte, dass Ihr sie aktiviert und meinen neu erfundenen Schrotthäscher X6000 mal ausprobiert.\n\nBleibt in der Nähe! Die Steuerung ist an meine Konsole hier gebunden, wenn Ihr zu weit weggeht, wird der Roboter aufhören zu funktionieren.\n\nProbiert alles aus... Ich schaue zu und stelle dann die Servos gemäß Eures Testlaufs ein.", sourceObjective = "Aktiviert die Steuerung für Schrotthäscher X6000 und testet seine Fähigkeiten aus. Gebt Dr. h. c. tüft. Vomisa bei den Versuchsgründen im Nethersturm danach Eure Rückmeldung.", progress = "Was meint Ihr? Muss noch ein wenig optimiert werden, was?", completion = "Nun, mein Junge, das war aber aufregend! Und meiner Meinung nach hat der Schrotthäscher X6000 trotz seines Grünschnabelpiloten gut funktioniert.\n\nHehe, seid nicht beleidigt, ich mache nur Witze. Schließlich habt Ihr gerade Area 52 und die X-52 Netherrakete vor dem sicheren Untergang bewahrt!", sourceObjectiveStatus = "unverified-source-field" }
quests[10249] = { id = 10249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Chef!", description = "Ich bin mir sicher, dass der Raketenchef ein oder zwei Takte mit Euch reden möchte!\n\nAn Eurer Stelle würde ich mich gleich nach Area 52 aufmachen und mit ihm sprechen!", sourceObjective = "Meldet Euch sofort bei Raketenchef Doppeldecker in Area 52 im Nethersturm!", completion = "{name}! Oder sollte ich sagen Juniortechniker ersten Grades {name}?! Ach, wem mache ich etwas vor. Einen Grad zu überspringen ist keine angemessene Belohnung für das, was Ihr getan habt. Ich ernenne Euch zu meinem Ersten Offizier!\n\nIhr habt uns alle gerettet, und noch viel wichtiger, die X-52 Netherrakete! Ich könnte Euch küssen... aber das tue ich nicht.\n\nLasst mich Euch stattdessen die Dankbarkeit von Area 52 zeigen. Wählt etwas aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[10250] = { id = 10250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutige Rache", description = "Im Osten befindet sich ein alter Belagerungsturm der Allianz. Jetzt suchen Plünderer dort nach alten Nägeln und Alteisen. Vor langer Zeit haben bei diesem Turm viele Krieger der Allianz ihr Leben gelassen. Ihr Banner wurde von einem widerlichen Orckommandanten namens Urtrak gestohlen.\n\nStoßt bei diesem Belagerungsturm in das Kampfhorn der Unerschütterlichen, um Urtraks Aufmerksamkeit zu erregen. Vielleicht ruft es auch Krieger herbei, die vor langer Zeit in der Schlacht gestorben sind.", sourceObjective = "Stoßt am alten Belagerungsturm der Allianz in das Kampfhorn der Unerschütterlichen. Tötet Urtrak und kehrt danach zu Althen dem Historiker im Rückenbrecherposten zurück.", progress = "Habt Ihr schon in das Horn gestoßen? Wir müssen es bald tun. Wer weiß, wann Thrallmar die Unterstützung der Unerschütterlichen braucht.", completion = "Ich bin froh, dass die Unerschütterlichen Euch im Kampf unterstützt haben. Ich dachte mir schon, dass sie dem Ruf ihres Schlachthorns folgen würden, aber ich war mir nicht sicher. Vielleicht haben wir ihnen jetzt die Rache ermöglicht, die sie so sehr begehrten.\n\nIhr habt Urtrak getötet. Diesen Sieg müssen wir Kommandant Hogarth im Expeditionsrüstlager der Allianz melden. Er wird verstehen, welche Gefahren Ihr für ihn auf Euch genommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10251] = { id = 10251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Plan des Meisters?", description = "Gestern Abend haben uns ein paar Draenei einen Besuch abgestattet. Sie haben irgendwie erfahren, dass wir das Buch in unserem Besitz haben und uns das großzügige Angebot gemacht, es uns abzunehmen.\n\nWir haben sie nicht gefragt, was sie mit dem Buch wollen, aber der Jüngere sprach die ganze Zeit vom \"großen Plan des Meisters\", was immer das zu bedeuten hat.\n\nIch stelle keine Fragen, wenn es ums Geld geht. Sie haben uns viel Gold geboten und wir haben ihnen das Buch gegeben.\n\nEr sagte, er lebe in Nagrand, im alten verlassenen Rüstlager nördlich von Telaar.", sourceObjective = "Sucht Nitrin den Gelehrten im verlassenen Rüstlager in Nagrand.", completion = "Die Zeichen waren deutlich, aber ich war blind.\n\nDer eiserne Griff der Legion wird von Tag zu Tag stärker. Sogar hier...\n\nIch wusste es... wusste, dass mein Junge mit den Dämonen kommunizierte... Sie haben ihm Macht angeboten und ihm dann einen Vorgeschmack dieser Macht gegeben. Mehr war nicht nötig...\n\nDas Buch ist fort. Levixus hat es genommen... Nur ich und sein dunkler Meister kennen seine Pläne.\n\nFremder, ich weiß nicht, ob Ihr jemals im Leben das Richtige getan habt, aber Ihr müsst eines wissen: der Junge muss aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10252] = { id = 10252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision der Toten", description = "Es hat schon begonnen. Levixus steht auf den Ruinen von Auchindoun und liest aus dem Buch der Toten. Er ruft die Toten beim Namen und unterwirft die gequälten Seelen durch ein dämonisches Ritual seinem Willen. Wenn er kann, wird er ganz Auchindoun erwecken!\n\nAber... Ihr müsst Euch erst vorbereiten. Ihr könnt nicht mit etwas kämpfen, dass Ihr nicht seht.\n\n<Nitrin reicht Euch ein Pergament.>\n\nBringt mir die Gegenstände, die ich für die Tinktur benötige. Sie wird Euren Geist erweitern und Euch ermöglichen, die Geisterwelt zu sehen.", sourceObjective = "Nitrin im verlassenen Rüstlager in Nagrand möchte, dass Ihr ihm 1 Augapfel eines Berggronns, 1 fehlerloser Schnabel eines großen Windrocs und 1 Tran eines gealterten Grollhufs bringt.", progress = "Levixus' Armee wächst mit jeder weiteren Sekunde in ihrer Größe und Stärke. Ihr müsst Euch beeilen.", completion = "Fremder... ich war nicht ganz aufrichtig zu Euch. Wenn Ihr diesen Trank zu Euch nehmt, werdet Ihr die Welt der Geister für alle Zeit sehen können. Diese Tinktur ist Teil des Initiierungsrituals für alle Totenpriester von Auchindoun. Viele werden wahnsinnig, wenn der Effekt eintritt. Die Toten sehen zu können ist... schockierend.\n\n<Nitrin hält Euch den Trank an die Lippen.>\n\nWollt Ihr es tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[10253] = { id = 10253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Levixus der Seelenrufer", description = "Geht jetzt, {name}. Ihr könnt Levixus auf den höchsten Ruinen von Auchindoun finden. Nähert Euch vom Süden der Knochenwüste. Er befindet sich mitten in einem Sturm von Seelen...\n\nVernichtet ihn und nehmt ihm das Buch der Toten ab. Wenn Ihr das verfluchte Buch in Eurem Besitz habt, dann zerstört es! Zerstört es, damit eine solche Grausamkeit nie wieder geschehen kann.", sourceObjective = "Vernichtet Levixus und nehmt Euch das Buch der Toten aus seinem Besitz.\n\nBringt das Buch der Toten zu Ramdor dem Wahnsinnigen außerhalb der Auchenaikrypta am Eingang zu Auchindoun.\n\nIhr hattet eine Vereinbarung, erinnert Ihr Euch?", progress = "Wer seid Ihr und was wollt Ihr? Oh... IHR seid es.", completion = "Wenn der alte Draenei Euch aufgetragen hat, das Buch zu zerstören, warum habt Ihr es dann nicht getan?\n\n<Ramdor starrt Euch an.> Ach, was soll's. Ihr seid vielleicht gierig, aber ehrlich.\n\nIch allerdings... Ich habe gelogen, um an das Buch zu kommen. Ich habe nicht die leiseste Ahnung, wo diese armen, verirrten Seelen ihren Schatz aufbewahren, und wenn ich es wüsste, würde ich es Euch nicht sagen. Aber ich habe trotzdem etwas für Euch. Ihr habt heute etwas Gutes getan. Vielleicht sogar etwas Großartiges... Ihr solltet belohnt werden.\n\nÜbrigens, willkommen im Club.\n\n<Ramdor zeigt auf die Geister.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10254] = { id = 10254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppenkommandant Danath", description = "<Marschall Isildor spuckt in den Staub.>\n\nNun, es ist an der Zeit, dass Ihr Euch Euren Sold verdient. Meldet Euch sofort bei Truppenkommandant Trollbann in der Feste. Er und seine Berater werden sich sicher freuen, Euch zu sehen.\n\n<Marschall Isildor salutiert teilnahmslos.>\n\nFür die Allianz!", sourceObjective = "Marschall Isildor möchte, dass Ihr Euch bei Truppenkommandant Danath Trollbann in der Ehrenfeste meldet.", completion = "Ich bin froh, dass Ihr hier seid, Bruder. Ich bin Danath Trollbann - Anführer der Söhne des Lothar und Truppenkommandant dieser Feste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10255] = { id = 10255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gegengift testen", description = "Ich glaube, in dem Blut ist etwas, das wir als Grundlage für ein Gegengift verwenden können. Schaut mich nicht an, als hätte ich den Verstand verloren!\n\nDas ist in der Natur ganz normal. Oft kann das Heilmittel aus dem Gift selbst gewonnen werden. Und genau das habe ich vor.\n\nWenn wir die Eber von dem dämonischen Einfluss befreien können, verlieren sie hoffentlich ihre Aggressivität und können uns zeigen, wie wir auch den andern Arten helfen können.", sourceObjective = "Probiert das cenarische Gegengift an einem bulligen Hölleneber aus und beobachtet die Folgen. Sobald Ihr die Ergebnisse des Experiments habt, kehrt zu Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.", progress = "Habt Ihr die Ergebnisse des Experiments, {name}?", completion = "<Thiah Rotmähne macht große Augen, als Ihr die Ergebnisse des Experiments beschreibt.>\n\nWie konnte das nur geschehen? Ich bin mir sicher, dass ich das Gegengift richtig hergestellt habe!\n\nIch habe gesehen, wie es mit Spinnen- und Schlangengiften funktioniert hat, warum kehrt sich die Wirkung hier nicht um? Vielleicht ist das eine der vielen Besonderheiten der Scherbenwelt, {name}. Ich leite diese Information am Besten an meine Kameraden weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[10256] = { id = 10256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schlüsselmeister finden", description = "Wenn ich zurückblicke, hätte ich eigentlich wissen müssen, dass Kael'thas' Magie so widerstandsfähig ist. Er war schon immer ein talentierter Magier, aber nie zuvor habe ich etwas so Mächtiges gesehen, wie die Magie, die er beim Angriff auf den Turm gewirkt hat.\n\nDer Schutzschild verhindert, dass ich die Macht, die er aufrechterhält, ausspionieren kann, aber Ihr könnt das trotzdem.\n\nIhr werdet jedoch einen Fokus brauchen. Apex, ein Riese, der Kristalle mit sich herumträgt, streift auf den Weiten westlich der Manaschmiede Duro umher. Einer seiner Kristalle würde einen ausgezeichneten Fokus abgeben.", sourceObjective = "Sucht Apex und besorgt Euch Apex' Kristallfokus. Kehrt dann zum Violetten Turm zurück und benutzt Apex' Kristallfokus in der Nähe von Erzmagier Vargoths Kugel um herauszufinden, wer den Schlüssel zum Fluch des Turms hat.", progress = "Was habt Ihr gesehen?", completion = "<Ihr beschreibt, was Ihr gesehen habt.>\n\nKommandant Sarannis sagt Ihr? Hmm...\n\nSie ist eine von Kael'thas Beratern, aber ganz sicher keine Magierin. Ich kenne sie von dem Angriff auf Kirin'Var. Ich glaube, Ihr habt Recht, {name}. Sie mag den Fluch vielleicht nicht selbst aufrechterhalten, aber sie hat den Schlüssel zum Schild.", sourceObjectiveStatus = "unverified-source-field" }
quests[10257] = { id = 10257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schlüsselstein erobern", description = "Es überrascht mich nicht, dass Kael'thas den Schlüssel zu diesem Schutzschild in die Hände von jemandem wie Kommandantin Sarannis gegeben hat. Prinz Kael'thas mag vielleicht vieles sein, aber sicher kein Narr.\n\nUm diesen Fluch ein für alle Mal zu brechen, müsst Ihr in die Festung der Stürme gehen und den Schlüsselstein besorgen.\n\nWenn der Schlüsselstein zerstört ist, werde ich meine Freiheit wiedererlangen.", sourceObjective = "Reist zur Botanika der Festung der Stürme und besorgt Euch den Schlüsselstein von Kommandantin Sarannis. Bringt ihn danach zu Erzmagier Vargoth im Violetten Turm.", progress = "Habt Ihr den Schlüsselstein?", completion = "<Die Augen des Erzmagiers leuchten auf, als Ihr ihm den Schlüsselstein gebt.>\n\nErstaunlich! Nach dem, was ich von Farahlons Schicksal erblickt habe, bin ich mir nicht sicher, ob ich hinaus will, aber es ist immerhin besser, als für den Rest meiner Tage hier eingesperrt zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10258] = { id = 10258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefallenen ehren", description = "Hogarth, der Kommandant des Rüstlagers, befindet sich im östlichen Turm. Ihr müsst ihm von Eurem Sieg über Urtrak berichten. Vielleicht ist er dann freundlich? Natürlich könnte er auch versuchen, Eure Seele zu fressen. Bei Geistern wie diesen weiß man nie.\n\nDie Unerschütterlichen sind uns immer noch feindlich gesonnen und werden versuchen zu töten, wenn sie können. Seid vorsichtig, {name}.", sourceObjective = "Meldet Euch bei Hogarth, dem Kommandanten des Expeditionsrüstlagers.", completion = "Wir haben die Schlacht vor so langer Zeit gegen die Höllenorcs verloren. Ihr habt uns unsere Ehre zurückgegeben, indem Ihr Urtrak getötet habt.\n\nNehmt Euch eine unserer Waffen. Wenn Ihr gegen unseren verhassten Feind in den Kampf zieht, benutzt diese Waffe, und die unter uns, die frei vom Fluch sind, werden Euch zur Hilfe kommen.\n\nBevor Ihr geht möchten einige, die vor Jahren beim Belagerungsturm gefallen sind, Euch für die Zerstörung unseres Feindes Ehre erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10259] = { id = 10259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Bresche springen", description = "Die Kämpfe bei dem Portal nehmen kein Ende! Die Argentumdämmerung kämpft in einer verzweifelten Schlacht - sollten wir verlieren, wird das Feuer der Dämonen niemals erlöschen.\n\nHelft uns, {name}. Zieht in den Kampf und helft unseren Brüdern und Schwestern. Helft ihnen, sich gegen die Welle der Dunkelheit zu erheben! Die Argentumdämmerung - und die Welt - brauchen Euch!", sourceObjective = "Tötet 6 einfallende Teufelswachen und kehrt dann zum Argentumabgesandten Stolzbrunn zurück.", completion = "Danke, {name}. In den Wirren der Schlacht leuchten Helden wie Sterne in der Dunkelheit. Euer Licht erstrahlt hell und klar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10260] = { id = 10260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netheorologe Kupfernickel", description = "Ihr müsst über die Hauptbrücke vom Schergrat in den Nethersturm gekommen sein. Habt Ihr dort Netheorologe Kupfernickel mit seiner verrückten Ausrüstung gesehen?\n\nMerkwürdig, ich erwarte einen Bericht von ihm, und er ist schon lange überfällig. Wahrscheinlich hat er es vergessen. Ihr kennt ja diese \"Wissenschaftler\".\n\nGeht zurück zur Brücke und nagelt ihn fest. Lasst Euch nicht mit Entschuldigungen abspeisen, bringt mir einfach seinen Bericht.\n\nDanke!", sourceObjective = "Sprecht mit Netheorologe Kupfernickel bei der Brücke, die vom Nethersturm zum Schergrat führt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10261] = { id = 10261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Vernichterservo!", description = "GESUCHT: 1 Vernichterservo, um den kaputten in meinem langhalsigen Spektrumanalysator zu ersetzen.\n\nIhr und Eure Freunde sollten bei den Blutelfen in der Manaschmiede B'naar im Westen nachschauen, ob sie ein paar Ersatzteile haben. Wie es scheint, haben sie dort ein paar Arkanvernichter.\n\nBitte bringt den Servo in unbeschadetem Zustand zu Papa Mauschel in Area 52.", sourceObjective = "Besorgt einen Vernichterservo und bringt ihn zu Papa Mauschel in Area 52 im Nethersturm.", progress = "Ich hoffe, Ihr kommt wegen meiner Suchanzeige!", completion = "Juhuu! Wisst Ihr, wie schwer man an diese Dinge herankommt? Es ist ja nicht so, als ob ich hier draußen täglich eine Teilelieferung bekommen würde.\n\nWisst Ihr was? Als Belohnung lasse ich Euch etwas aus meiner Kramkiste nehmen. Es ist sicher etwas darin, was Ihr brauchen könnt. Wenn nicht, verkauft es einfach weiter.\n\nIn Ordnung, lasst mich das Euch abnehmen und in meinen langhalsigen Spektrumanalysator einbauen, bevor der alte Servo noch explodiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[10262] = { id = 10262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hügel voll Astraler", description = "Es gibt noch etwas anders, bei dem ich Eure Hilfe brauche.\n\nEine Gruppe von Astralen, die als Zaxxis bekannt sind, haben ihre Verbindungen zum Konsortium abgebrochen um ihre eigenen Geschäfte zu machen. Sie machen sogar Geschäfte mit den Blutelfen! Das können wir nicht hinnehmen!\n\nIch habe ihre Gruppe bei dem Hügel im Süden unterwandert, aber als ich ihren Anführer ausgeschaltet hatte, musste ich zurück in die Sicherheit von Area 52 fliehen.\n\n{class}, geht dorthin und bringt mir ihre Insignien. Natürlich tragen nicht alle Insignien, weil sie Feiglinge sind.", sourceObjective = "Sammelt 10 Insignien der Zaxxis und kehrt dann zu Netherpirscher Khay'ji in Area 52 im Nethersturm zurück.", progress = "Ist es vollbracht? Habt Ihr den Abschaum der Zaxxis vom Angesicht der Scherbenwelt ausgerottet und mir ihre Insignien gebracht?", completion = "Diese Insignien sind ein guter Anfang.\n\nUnglücklicherweise haben meine anderen Agenten bei den Zaxxis berichtet, dass Sphärenräuber Nesaad immer noch am Leben ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[10263] = { id = 10263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Konsortium helfen", description = "Die Naaru von Shattrath haben versucht, dem Konsortium beizubringen, die Dinge auf ihre Weise zu sehen.\n\nDas Glück wollte, dass die Geschäftsbeziehungen zwischen den Astralen und den Blutelfen im Nethersturm sich in letzter Zeit drastisch verschlechtert haben.\n\nIm Dorf gibt es einen Mitarbeiter des Konsortiums namens Khay'ji, der vor Kurzem ein paar Probleme mit einer Truppe von abtrünnigen Astralen hatte. Als Mitglied der Aldor möchte ich Euch bitten, ihm zu helfen, wo Ihr nur könnt.", sourceObjective = "Sprecht mit Netherpirscher Khay'ji in Area 52 im Nethersturm.", completion = "Hallo, {race}.\n\nIhr habt nicht zufällig Zeit für einen Wiederbesorgungsauftrag von ziemlicher Wichtigkeit?", sourceObjectiveStatus = "unverified-source-field" }
quests[10264] = { id = 10264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Konsortium helfen", description = "Die Naaru von Shattrath haben versucht, dem Konsortium beizubringen, die Dinge auf ihre Weise zu sehen.\n\nDas Glück wollte, dass die Geschäftsbeziehungen zwischen den Astralen und den Blutelfen im Nethersturm sich in letzter Zeit drastisch verschlechtert haben.\n\nIm Dorf gibt es einen Mitarbeiter des Konsortiums namens Khay'ji, der vor Kurzem ein paar Probleme mit einer Truppe von abtrünnigen Astralen hatte. Als Mitglied der Seher möchte ich Euch bitten, ihm zu helfen, wo Ihr nur könnt.", sourceObjective = "Sprecht mit Netherpirscher Khay'ji in Area 52 im Nethersturm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10265] = { id = 10265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallsammlung des Konsortiums", description = "Unser Anführer, Nexusprinz Haramad, hat mich gebeten, ein Kristallartefakt aus den Ruinen von Arklon im Südosten zu besorgen.\n\nEs sind alte Draeneiruinen. Zum Pech für mich und die Goblins hier hat die Brennende Legion beschlossen, selbst danach zu graben.\n\nWenn Ihr mir weiterhin helfen wollt, nehmt dem Schreckenslord namens Pentatharon das Kristallartefakt ab.", sourceObjective = "Besorgt ein Kristallartefakt von Arklon und bringt es zu Netherpirscher Khay'ji in Area 52 im Nethersturm.", progress = "Ich habe den Eindruck, dass der Prinz nach einem ganz bestimmten Kristall sucht, aber ich bin mir nicht sicher, welcher das ist.\n\nHabt ihr dem Schreckenslord schon seinen abgenommen?", completion = "Lasst mich ihn mal ansehen.\n\nHmm, er scheint nicht besonders zu sein. Ich bezweifle, dass er das ist, obwohl Eure Beschreibung der Vorgehensweisen der Legion in den Ruinen den Anschein erweckt, dass auch sie nach etwas ganz Bestimmten suchen.\n\nWollen wir hoffen, dass es nicht der Kristall ist, den der Nexusprinz so unbedingt haben will.", sourceObjectiveStatus = "unverified-source-field" }
quests[10266] = { id = 10266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte um Unterstützung", description = "Während Ihr in den Ruinen von Arklon wart, habe ich eine Bitte um Unterstützung von einem unserer Mitarbeiter im Feld erhalten. Wie es scheint hat das Konsortium einige Probleme damit, Waren von den Blutelfen zurückzufordern, die sie nicht bezahlen wollen.\n\nBitte begebt Euch von Area 52 aus nach Osten und überquert die Brücke zur nächsten Insel. Ihr findet meinen Gefährten Gahruj im Mittelreichposten in der Biokuppel Mittelreich.", sourceObjective = "Sucht Gahruj und bietet ihm Eure Hilfe an. Er befindet sich im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", completion = "Ja, es ist wahr. Die Blutelfen weigern sich auch dieses Mal, die Waren, die ihnen schon geliefert wurden, zu bezahlen.\n\nDa Netherpirscher Khay'ji Euch geschickt hat, hoffe ich, dass Ihr mir bei dieser Angelegenheit helfen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10267] = { id = 10267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rechtmäßiger Besitz", description = "Unsere Geschäftsbeziehungen mit den Blutelfen scheinen zu Ende zu sein. Vor ein paar Wochen wurde ihnen bei der Manaschmiede Duro eine große Ladung mit Vermessungsausrüstung geliefert. Sie haben sich geweigert, dafür zu bezahlen.\n\n{name}, ich möchte, dass Ihr den Blutelfen in der Manaschmiede Duro im Osten einen Besuch abstattet. Sie scheinen ein paar Probleme mit angreifenden Manakreaturen zu haben, also nutzt aus, dass sie beschäftigt sind.\n\nMir ist egal, was mit ihnen passiert, aber ich hätte meinen rechtmäßigen Besitz gerne zurück.", sourceObjective = "Sammelt 10 Kästen mit Vermessungsausrüstung und bringt sie zu Gahruj im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", progress = "Habt Ihr die Vermessungsausrüstung, um die uns die Blutelfen betrogen haben?", completion = "Nun, ich bin froh, dass wir dieses kleine Geschäft abgeschlossen haben. Ich kann mich nicht erinnern, dass das Konsortium je Geschäfte mit solch flegelhaften und unseriösen Wesen gemacht hätte.\n\nIhr scheint jedoch vertrauenswürdig zu sein, {name}. Vielleicht wollt Ihr mir ja noch einen Gefallen tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[10268] = { id = 10268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz beim Prinzen", description = "Nexusprinz Haramad hat mir zu verstehen gegeben, dass er seinen Besitz unverzüglich und persönlich zurückerhalten möchte. Ich wäre Euch sehr dankbar, wenn Ihr ihm die Waren an meiner statt zurückbringen könntet.\n\nEine Audienz beim Nexusprinzen ist eine große Ehre, und ich bin mir sicher, dass er sehr gerne etwas über Eure Abenteuer im Nethersturm erfahren würde.\n\nSucht ihn in seiner Kammer oben in der Sturmsäule im Norden auf. Er ist oft nur als holografisches Bild anwesend, dass Ihr ansprechen könnt.", sourceObjective = "Bringt die Vermessungsausrüstung zum Bild von Nexusprinz Haramad in der Sturmsäule im Nethersturm.", progress = "Tretet näher.", completion = "Ich heiße Euch in der Sturmsäule willkommen, {class}. Bitte genießt die Gastfreundschaft des Konsortiums.\n\nDie Ausrüstung könnt Ihr irgendwo abstellen. Ich nehme an, dass Ihr sie schon sehr bald wieder mitnehmen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10269] = { id = 10269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triangulationspunkt Eins", description = "Da ist noch ein anderer Grund, warum ich die Vermessungsausrüstung zurückhaben wollte. Es gibt da einen Kristall aus einer alten Draeneilegende, der mir sehr wichtig ist.\n\nMan sagt, dass der Kristall seinem Träger gottgleiche Macht verleiht! Aber es besteht die Gefahr, dass jemand anderes ihn ausgräbt, nämlich die Brennende Legion.\n\n{name}, nehmt die Ausrüstung und benutzt sie, um den ersten Triangulationspunkt zu finden. Wir wissen, dass er sich irgendwo östlich der Manaschmiede Ultris befinden muss.\n\nMeldet Euch danach bei meinem Agenten, Händler Hazzin, auf der Insel der Manaschmiede Ultris.", sourceObjective = "Benutzt das Triangulationsgerät, um den Weg zum ersten Triangulationspunkt zu bestimmen. Wenn Ihr ihn gefunden habt, meldet die Position an Händler Hazzin beim Wachposten des Protektorats auf der Insel der Manaschmiede Ultris im Nethersturm.", progress = "Hallo, Reisender. Seid Ihr zu Hazzin gekommen, weil Ihr meine Waren begehrt?", completion = "<Händler Hazzin senkt seine Stimme zu einem Flüstern.>\n\nAh, ich weiß von Eurem Auftrag. Er ist für Nexusprinz Haramad äußerst wichtig.\n\nJetzt, da wir die Position des ersten Triangulationspunktes herausgefunden haben, müssen wir schnell den zweiten suchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10270] = { id = 10270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nicht-so-bescheidenes Angebot", description = "Aus Eurem Gesicht kann ich lesen, dass Ihr <ein/eine:r> {race} mit Sinn fürs Geschäft seid.\n\nIch habe mir einen Ruf als Händler für exotische und teure Waren erarbeitet, und bin gerade dabei, ein neues Unternehmen zu starten.\n\nIch könnte einen fähigen Unterhändler brauchen, um die Waren vom Sternensturz weiterzuleiten.\n\nZuerst müsst Ihr eine Teleporterplattform wieder aufladen. Im Zugangsschacht Zeon auf der südlichen Seite der Manaschmiede Ultris findet Ihr eine Ersatzenergiezelle. Das Protektorat befindet sich zurzeit dort, deshalb könnt Ihr einfach ihren Signalgebern zu Eurem Ziel folgen.", sourceObjective = "Besorgt Euch die Teleporterenergiezelle und bringt sie zur Astralteleportplattform im Sternensturz östlich der Manaschmiede Ultris. Aktiviert die Plattform und bringt die Teleporterenergiezelle zum Bild von Windhändler Marid, damit er sie einbauen kann.", progress = "Seid Ihr bereit über das Geschäft zu reden, {name}?", completion = "Diese Energiezelle sollte für unsere Zwecke ausreichen. Sobald das Geld zu fließen beginnt, werden wir ihn noch weiter verbessern.\n\nDoch genug davon. Jeder mit Diskussionen verschwendete Augenblick bedeutet verlorenen Gewinn.", sourceObjectiveStatus = "unverified-source-field" }
quests[10271] = { id = 10271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Sache", description = "Wir Ihr sicher gesehen habt, wimmelt es in dieser Gegend von Netherdrachen aller Altersstufen. Alle Netherdrachen, die jungen wie die alten, verfügen über eine Essenz, die bei K... - ähh, meinem Kunden sehr begehrt ist.\n\nDie Meisten sind nicht bereit, dafür ihr Leben aufs Spiel zu setzen, deswegen haben wir die Gegend hier ganz für uns alleine. Ihr könnt damit anfangen, die Essenz von allen Drachen hier zu sammeln, aber es ist von größter Notwendigkeit, dass wir sofort einen steten Nachschub aufbauen. Kehrt zu mir zurück, wenn Ihr eine erste Ladung zusammen habt.", sourceObjective = "Ladet den Essenzsammler auf, indem Ihr ihn bei Netherdrachen und Nethergroßdrachen auf dem Sternensturz anwendet, und kehrt dann zu der Gegend um die Astralteleportplattform zurück.", progress = "Ich bin sicher, dass Ihr viele Fragen habt. Ihr werdet rechtzeitig alle Antworten erhalten.", completion = "Man stelle sich nur vor, dass dieser erbärmliche Astrale diese Essenzen wie Süßigkeiten an die Blutelfen verkaufen wollte...", sourceObjectiveStatus = "unverified-source-field" }
quests[10272] = { id = 10272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein viel versprechender Anfang", description = "Wir sind hierhergekommen, um den Gerüchten über eine merkwürdige Drachenbrut, die vielleicht die Nachkommen von Todesschwinge selbst sein könnten, nachzugehen. Ganz offensichtlich handelt es sich nicht um gewöhnliche schwarze Drachen.\n\nWenn wir eine Gelegenheit hätten, ihre Eier zu untersuchen, könnten wir sicher mehr über sie herausfinden. Ihr Hass auf meinesgleichen sitzt so tief, dass ich nicht nahe genug herangehen kann, um die Eier selbst zu sammeln. Werdet Ihr mir helfen?", sourceObjective = "Sammelt 15 Netherdrachkineier und kehrt dann zu Tyri und Jorad im Sternensturz zurück.", progress = "Konntet Ihr die Eier sammeln?", completion = "Die sollten ihren Zweck erfüllen, {name}. Vielen Dank, dass Ihr uns geholfen habt.\n\nBevor wir weitermachen können gibt es jedoch noch etwas anders, worüber wir sprechen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10273] = { id = 10273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störende Ablenkung", description = "Euer früherer Arbeitgeber, Windhändler Marid, muss davon Wind bekommen haben, dass Ihr nun uns helft. Mithilfe meiner Projektion habe ich gesehen, wie seine Netherpirscher in die Gegend eingedrungen sind, um uns zu suchen.\n\nBis jetzt konnten wir ihnen entkommen, aber wir müssen uns mit Marid auseinandersetzen, bevor das Problem noch größer wird.\n\nWenn Ihr den richtigen Eindruck von Marid hattet, dann würde er alles tun, um den Nachschub seines Produkts zu sichern. Kehrt zu ihm zurück und sagt ihm, dass Ihr bereit seid, einen Handel einzugehen. Lockt ihn fort und tötet ihn.", sourceObjective = "Sprecht mit Windhändler Marid und lockt ihn von seinem Handelsposten fort. Vernichtet ihn und kehrt dann zu Tyri und Jorad im Sternensturz zurück.", progress = "Dieser Marid ist ein Dummkopf, oder sollte ich besser sagen war ein Dummkopf?", completion = "Jetzt, da dieser lästige Astrale beseitigt ist, können wir uns darauf konzentrieren, die Netherdrachen besser verstehen zu lernen. Ich konnte die Eier untersuchen und habe dabei einiges herausgefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10274] = { id = 10274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Sternensturz sichern", description = "Die Netherdrachen verfügen über dasselbe wilde Temperament wie ihre Vorfahren, die schwarzen Drachen. Etwas an ihnen ist jedoch vollkommen anders. Sie schlüpfen schnell und werden schnell reif, indem sie die fremdartigen Energien, die ihre Art zur Zerstörung Draenors getrieben hat, nutzen.\n\nEs gibt so Vieles, was ich noch über sie in Erfahrung bringen muss, aber ich glaube, dass die Mächte für meinen eigenen Schwarm von Vorteil sein könnten. Wenn wir den Anführer dieser Drachen, Veraku, als Zeichen unserer Dominanz vernichten könnten, könnten wir den Rest vielleicht so einschüchtern, dass sie sich uns unterwerfen.", sourceObjective = "Benutzt die Herausforderung des blauen Drachenschwarms um Veraku am südlichen Ende des Sternensturzes zu provozieren. Besiegt ihn und kehrt dann zu Tyri und Jorad im Sternensturz zurück.", progress = "Habt Ihr Veraku schon herausgefordert und getötet?", completion = "Gut gemacht, {name}. Wirklich gut gemacht. Die Netherdrachkin werden zu Anfang keinen blauen Drachen in ihren Reihen akzeptieren, aber wenn ich meine Autorität beweise, werden sie sich fügen. Zerschlagen, isoliert und ohne Führung sind sie leichte Beute für bösartige Mächte. Wir müssen daher regelmäßig ein Auge auf sie werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10275] = { id = 10275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triangulationspunkt Zwei", description = "Ich habe das Triangulationsgerät mit den Informationen des ersten Punkts neu eingestellt. Ihr könnt es genauso wie beim ersten Mal benutzen, um den zweiten Punkt zu bestimmen.\n\nAlles, was ich Euch sagen kann, ist, dass der zweite Punkt sich weit im Westen befindet.\n\nWenn Ihr ihn gefunden habt, sprecht mit Windhändler Tuluman, ein weiterer Agent des Nexusprinzen. Er steht als Waffenhändler getarnt in einem kleinen Handelsposten neben der Brücke, die zur Insel, auf der sich die Manaschmiede Ara befindet, führt.", sourceObjective = "Benutzt das Triangulationsgerät, um den Weg zum zweiten Triangulationspunkt zu bestimmen. Wenn Ihr ihn gefunden habt, meldet die Position an Windhändler Tuluman auf Tulumans Landeplatz auf der anderen Seite der Brücke zu der Insel der Manaschmiede Ara im Nethersturm.", progress = "Wollt Ihr kaufen oder verkaufen?", completion = "Sehr gut, in der Tat. Der Nexusprinz wird zufrieden sein.\n\nJetzt haben wir den zweiten Punkt, der uns den dritten und damit die Umgebung, in der sich der Kristall befindet, verraten wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10276] = { id = 10276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das volle Dreieck", description = "Mit den Daten vom ersten und zweiten Punkt kann ich sicher sagen, dass der Kristall sich auf den Ruinen von Farahlon im Nordosten befindet.\n\nUnglücklicherweise sagen die Daten, dass der Kristall sich bewegt, was bedeutet, dass er bereits gefunden wurde. Wahrscheinlich von der Brennenden Legion!\n\nFalls das tatsächlich so ist, empfehle ich Euch, ein paar Freunde mitzunehmen.\n\nTötet den Dämon, der den Kristall hat, und bringt ihn zu Nexusprinz Haramad.", sourceObjective = "Besorgt Euch den Kristall von Ata'mal und bringt ihn zum Bild von Nexusprinz Haramad in der Sturmsäule im Nethersturm.", progress = "Willkommen zurück, Freund. Wie geht es mit der Suche nach dem Kristall voran?", completion = "In meinen wildesten Träumen habe ich nicht gedacht, dass Ihr den Kristall tatsächlich beschaffen könnt!\n\nUnd Ihr gebt mir ihn sogar! Habt Ihr eine Ahnung, wie mächtig er ist?\n\nEure Selbstlosigkeit ist sehr inspirierend und unvergleichlich, {name}! Ihr habt mir viel zum Nachdenken gegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10277] = { id = 10277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höhlen der Zeit", description = "Grüße, {name}. Bitte folgt der Bewahrerin. Sie wird ein wenig... Licht in die Angelegenheit bringen.", sourceObjective = "Andormu in den Höhlen der Zeit möchte, dass Ihr der Bewahrerin der Zeit durch die Höhle folgt.", progress = "Kehrt nicht zurück, bevor Ihr nicht wenigstens einen groben Eindruck davon bekommen habt, was hier vor sich geht.", completion = "Hoffentlich habt Ihr nun einen besseren Eindruck davon, was von Euch erwartet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10278] = { id = 10278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sphärenrisse", description = "Ich bin lange auf der Suche nach der Wahrheit der Leere durch die Scherbenwelt gereist. Jetzt bin ich alt und schwach. Ich sehe merkwürdige Dinge und bin nicht mehr ich selbst. Vielleicht wollt Ihr mir helfen?\n\nIch muss die Geheimnisse der Leerwandler aufdecken. Westlich des Expeditionsrüstlagers befindet sich ein Ort namens Sphärenfelder. Zeit und Raum sind dort sehr schwach, da die Felder nahe beim Abgrund liegen. Geht dorthin und benutzt den instabilen Sphärenrissgenerator. Er wird einen Sphärenriss erzeugen. Ihr müsst den Sphärennether von den Kreaturen, die durch ihn herauskommen, sammeln.", sourceObjective = "Benutzt den instabilen Sphärenrissgenerator in den Sphärenfeldern. Sammelt 3 Einheiten Sphärennether von instabilen Leerwandlern und kehrt dann zu Ogath dem Verrückten im Rückenbrecherposten zurück.", progress = "Habt Ihr meinen Apparat schon ausprobiert? Ich glaube, dass mein instabiler Sphärenrissgenerator so nahe am Abgrund funktionieren sollte.", completion = "Unglaublich. Ihr habt die Leere selbst berührt! {name}, Ihr habt mein Lebenswerk gerettet. Aber es gibt noch mehr, was getan werden muss, und Ihr könnt mir helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10279] = { id = 10279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Hort des Meisters", description = "Ah, {name}. Wir haben Euch erwartet. Bitte erlaubt, dass einer meiner Brüder Euch zum Meister fliegt. Er wartet unten auf Euch...", sourceObjective = "Sprecht mit Andormu in den Höhlen der Zeit.", completion = "Wir müssen uns auf die vor uns liegende Schlacht vorbereiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[10280] = { id = 10280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderlieferung nach Shattrath", description = "Ich bin ein Astraler, der sein Wort hält, {name}. Ihr habt mich wirklich inspiriert.\n\nIch werde Euch den Kristall von Ata'mal geben, damit Ihr ihn den Naaru überreicht. Da Euer Heldenmut dies möglich gemacht hat, soll Euch die Ehre zuteilwerden, ihn zu übergeben.\n\nIhr könnt meinen persönlichen Teleporter benutzen, um direkt nach Shattrath zu gelangen. Tretet einfach hindurch und er wird Euch dorthin bringen.\n\nGebt den Kristall dem Naaru namens A'dal auf der Terrasse des Lichts.", sourceObjective = "Bringt den Kristall von Ata'mal zu A'dal auf der Terrasse des Lichts in Shattrath.", progress = "<Das musikalische Klingen der Naarusprache erfüllt Euren Geist.>\n\nIch spüre, dass Ihr einen Gegenstand von großer Macht bei Euch tragt, {race}. Was bringt Ihr mir?", completion = "Ihr habt mir den Gesang der Geister zurückgebracht! Prophet Velen hat den Kristall von Ata'mal zur Sicherheit bei seinem Volk zurückgelassen, bevor er auf seine schicksalsträchtige Mission zur Exodar ging.\n\nMerkwürdig, dass er nicht vorhergesehen hat, dass er in die Hände der Brennenden Legion fallen würde, wenn auch nur für kurze Zeit.\n\nOder vielleicht hat er das ja? Es könnte sein, dass er all dies vorhergesehen hat, und ihn dort ließ, damit Ihr ihn mir bringen könnt.\n\nIch spüre, dass dies die Wahrheit ist. Ihr seid ein großer Held unseres Volkes, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10281] = { id = 10281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Formelle Vorstellung", description = "Grüße, {name}. Keine Angst, dies ist nur eine Projektion meiner gegenwärtigen Form. Es ist die einzige Möglichkeit, wie mein Gefährte und ich Wache halten können, ohne uns selbst zu offenbaren.\n\nDer Astrale, der Euch angesprochen hat, Marid, ist nur ein Schwindler, der sich als anständiger Händler ausgibt. Überlegt Euch daher, ob Ihr nicht lieber mit mir zusammenarbeiten wollt. Mein Ziel ist es, mehr über die ungewöhnlichen Drachkin des Sternensturzes herauszufinden. Trefft mich am nördlichen Ende des Sturzes, damit wir über die Details sprechen können.", sourceObjective = "Sucht Tyri am nördlichen Ende des Sternensturzes und sprecht mit ihr.", completion = "Mein Name ist Tyrygosa von Malygos' Brut, aber nennt mich einfach Tyri. Mein Begleiter ist der Paladin Jorad Knüpp.\n\nDie Kunde von den merkwürdigen Drachkin hier verbreitet sich schnell, und ich fürchte, dass sehr viele kommen werden, um sie auszubeuten, bevor sie überhaupt ihre wahre Natur erkannt haben. Wir hoffen, dass wir mit Eurer Hilfe diese Kreaturen kennenlernen können, bevor andere von ihnen erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10282] = { id = 10282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Alte Hügelland", description = "Im Westen findet Ihr die Pfade der Zeit in das Hügelland der Vergangenheit - vor 7 Jahren um genau zu sein.\n\nDie Streitmächte kämpfen gegen den Kriegshäuptling der Horde, Thrall, um ihn davon abzuhalten, aus der Burg Durnholde zu fliehen.\n\nWenn es Thrall nicht gelingt zu fliehen, wird die Welt, wie Ihr sie jetzt kennt, aufhören zu existieren.\n\nRuft eine Gruppe von Abenteurern zusammen und reist auf dem Pfad der Zeit ins Alte Hügelland. Zwei unserer Agenten warten dort auf Euch.\n\nSprecht mit Erozion auf der anderen Seite.", sourceObjective = "Andormu in den Höhlen der Zeit bittet Euch, ins Alte Hügelland zu reisen und mit Erozion zu sprechen.", completion = "Unsere schlimmsten Befürchtungen könnten bald wahr werden. Hinter dieser Störung der Zeitlinien steht ein neuer Drachenschwarm, der als die Ewigen bekannt ist. Wir wissen nicht, woher sie kommen und warum sie die Pfade der Zeit zerstören.\n\nIn dieser Zeitfalte haben sie Taretha Foxton, die Tochter von Tammis Foxton, der rechten Hand von Aedelas Schwarzmoor, Herrscher von Durnholde und Aufseher aller Internierungslager in Azeroth, gekidnappt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10283] = { id = 10283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarethas Ablenkungsmanöver", description = "Taretha spielte eine entscheidende Rolle bei Thralls Überleben und Erziehung und prägte Thralls Leben maßgeblich.\n\nEs war Taretha, die die Wachen von Durnholde ablenkte, damit Thrall entkommen konnte.\n\nJetzt haben die Ewigen Taretha gefangen und halten sie in Tarrens Mühle fest. Ohne unsere Einmischung wird das Ablenkungsmanöver niemals stattfinden. Ihr müsst den Brandsatz, den ich Euch gegeben habe, nehmen und die Internierungsbaracken in Durnholde anzünden. Wenn Ihr das erledigt habt, sprecht mit dem jungen Thrall im Kellergefängnis der Burg.", sourceObjective = "Reist zur Burg Durnholde und platziert mithilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke.\n\nSprecht mit Thrall im Kellergefängnis der Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt.", progress = "Wer seid Ihr?", completion = "Ihr seid Freunde von Taretha? Das ist also ihr neuer Plan? Nun gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[10284] = { id = 10284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Durnholde", description = "Ihr schaut mich an und seht nur einen Jungen, aber tief in meinem Herz und meiner Seele halte ich meine Träume versteckt. Ich habe Pläne für mein Volk, Fremder. Eines Tages werden sie ihre Unterdrücker überwältigen und in Einheit auferstehen. Sie werden ihre Fesseln abwerfen und aus diesem Aufstand soll die orcische Horde entstehen.\n\nIch verspreche Euch, Fremder, dass ich Euch suchen werde, wenn wir heil hier herauskommen und ich die Möglichkeiten habe, Eure selbstlose Tat zu belohnen... Ich werde Euch finden.\n\n<Thrall nickt.>\n\nWir fliehen, wenn Ihr bereit seid.", sourceObjective = "Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen.\n\nSprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt.", progress = "<Erozion nickt.>", completion = "Ihr habt eine großartig Aufgabe erledigt, {name}. Nun müssen die Erinnerungen des jungen Kriegshäuptlings an diese Ereignisse wieder so verändert werden, wie sie einst waren... Andormu erwartet Euch im Hort des Meisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[10285] = { id = 10285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Andormu", description = "Diese Zeitachse wurde wiederhergestellt und der Angriff des ewigen Drachenschwarms auf das Hügelland vorerst abgewendet.\n\nKehrt sofort zu Andormu zurück. Er wartet im Hort des Meisters auf Eure Ankunft.", sourceObjective = "Kehrt zu dem jungen Andormu in den Höhlen der Zeit in Tanaris zurück.", completion = "Bitte nehmt ein Geschenk des Bronzeschwarzms an. Diese Gegenstände werden Euch auf Euren Reisen durch die Zeit unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10286] = { id = 10286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelions Geheimnis", description = "Arelions Tagebuch enthält überhaupt keine wissenschaftlichen Studien. Er beschreibt seine Eskapaden mit einer jungen Blutelfe! Wie konnte ich nur so dumm sein?\n\nUnglücklicherweise nennt das Tagebuch den Namen des Flittchens nicht. Aledis, ein Kollege von Arelion, war sein bester Freund und Vertrauter. Befragt ihn und findet heraus, mit wem er eine Affäre hatte.\n\nIch habe gesehen, wie Aledis sich vor Kurzem aus der Falkenwacht in Richtung Zangarmarschen aufgemacht hat. Folgt der Straße nach Norden aus dem Dorf heraus. Sie biegt nach einer Weile nach Westen in Richtung Zangarmarschen ab.", sourceObjective = "Magistrix Carinda möchte, dass Ihr Magister Aledis befragt. Aledis wurde zuletzt auf einer Reise von der Falkenwacht zu den Zangarmarschen gesehen.", completion = "Ich werde reden, {class}. Nehmt die Waffe runter, ich will nicht noch mehr Ärger haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10287] = { id = 10287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die enttarnte Geliebte", description = "Ich bin Arelions Freund, aber ich werde für ihn nicht die Prügel meines Lebens einstecken. Seine Geliebte ist Viera Sonnenwisper.\n\nSagt das seinem Drachen von Ehefrau. Was will sie schon dagegen tun?", sourceObjective = "Kehrt zu Magistrix Carinda in die Falkenwacht auf der Höllenfeuerhalbinsel zurück.", completion = "Viera Sonnenwisper? Diese widerliche kleine Göre.\n\nIch werde ihr zeigen, dass man mit mir keine Spielchen treibt!", sourceObjectiveStatus = "unverified-source-field" }
quests[10288] = { id = 10288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ankunft in der Scherbenwelt", description = "Ich möchte, dass Ihr mit Amish Wildhammer sprecht. Ihr findet ihn etwa 30 Schritt südlich von hier. Nehmt den ersten Flug zur Ehrenfeste. Wenn Ihr dort angekommen seid, werdet Ihr von Marschall Isildor begrüßt werden. Gebt ihm diese Empfehlung, in der ich notiert habe, wo Ihr meiner Meinung nach am hilfreichsten sein könntet.\n\nIch habe Euch einen Befehl erteilt, Soldat, nun fort mit Euch! Und auch wenn Ihr darauf brennt, uns im Kampf gegen den Feind hier zu unterstützen, dürft Ihr keine Zeit verschwenden. Die Ehrenfeste braucht Euch sogar noch mehr als wir.", sourceObjective = "Kommandant Duron beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Durons Bericht zu Flugmeister Amish Wildhammer bringt.", progress = "Ich habe gehört, wie Ihr mit Duron gesprochen habt. Ihr müsst einen wichtigen Auftrag haben!", completion = "Berichte für die Ehrenfeste? Kein Problem, einer meiner Greifen wird Euch schnell und sicher dorthin bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10289] = { id = 10289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Thrallmar", description = "Wenn Ihr bereit seid, rufe ich einen Flügeldrachen, der Euch nach Thrallmar bringt. Wenn Ihr angekommen seid, bringt Orions Bericht zu General Krakork.\n\nLok'tar ogar, {name} - Viel Glück.", sourceObjective = "Nehmt Vlagga Freyfeders Windreiter nach Thrallmar. Bringt Orions Bericht zu General Krakork.", progress = "Ein Bericht von Orion? Gebt ihn mir, schnell!\n\n<Stirnrunzelnd überfliegt General Krakork den zerknitterten Brief.>\n\nVerdammt, es ist genau so, wie wir es befürchtet haben. Orion und seine Krieger können jeden Moment überrannt werden!", completion = "Ich werde alle Truppen, die ich entbehren kann, zu Orion beim Dunklen Portal schicken. Die Legion wird den Schlachtruf der Horde nicht so bald vergessen! Ihr, {name}, habt Thrallmar heute einen großen Dienst erwiesen. Ich glaube, Ihr könnt uns hier eine große Hilfe sein. Natürlich nur, wenn Ihr klug genug seid, um zu überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10290] = { id = 10290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Farahlit", description = "Im Nordosten gibt es eine Region, die Netherstein genannt wird. Früher war sie unter einem fruchtbaren und grünen Land verborgen. Die neu gefundenen Kristallformationen haben uns ein Mineral gezeigt, das wir zur Ehre der früheren Identität des Landes Farahlit genannt haben.\n\nDie kleine Menge Farahlit, die wir bis jetzt abgebaut haben, erfreut sich jetzt schon großer Beliebtheit bei unseren Kunden. Das hochwertigste Mineral stammt jedoch nicht von den Ablagerungen, sondern von den Riesen, die um den Netherstein herum leben. Ich biete Euch einen Teil des Gewinns an, wenn Ihr mir helft, hochwertiges Farahlit zu besorgen.", sourceObjective = "Sammelt 4 Stück Rohfarahlit und kehrt dann zu Zuben Elgenubi in der Sturmsäule zurück.", progress = "Ich bin mir bewusst, dass das Sammeln von Farahlit sehr gefährlich ist, aber die Möglichkeiten sind gewaltig. Ein Händler, der nicht bereit ist, Risiken auf sich zu nehmen, kann seine Türen gleich schließen und sich den Ärger ersparen.", completion = "Ah ja, genau die Qualität, die ich mir erhofft habe. Wenn wir genügend Nachschub von den Riesen bekommen, brauchen wir die Kristalle nicht mehr abbauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10291] = { id = 10291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Nazgrel", description = "Auch wenn unsere Krieger keine ebenbürtigen Gegner haben, ist unsere Stellung in diesem Ödland immer noch angreifbar. Meldet Euch bei Nazgrel in der Kaserne. Er braucht gute Agenten... wie Euch. Wenn wir unsere Stellung hier nicht halten können, sind wir für niemanden eine Hilfe! Geht jetzt.", sourceObjective = "General Krakork in Thrallmar möchte, dass Ihr mit Nazgrel sprecht.", completion = "Wir haben schon viele tapfere Krieger an dieses verfluchte Land verloren. Ich habe kein Interesse daran, noch mehr ungeprüfte Rekruten in das Massaker zu schicken.\n\n<Nazgrel schaut Euch durch seine zottige Wolfsmaske streng an.>\n\nAber wenn General Krakork Euch zu mir geschickt hat, muss an Euch ja etwas dran sein. Was sagt Ihr also, {name}? Werdet Ihr dem Kriegshäuptling mit Ehre dienen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10292] = { id = 10292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Energie!", description = "Ein wertvolles Gut in kleinen Häppchen zu sammeln hat das malerische Flair eines Familienunternehmens, aber auf dem heutigen Markt ist es einfach nicht konkurrenzfähig.\n\nNein, wir brauchen einen Weg, Farahlit in Massenproduktion zu beschaffen! Dann wäre der Hauptanteil des Marktes unser!\n\nIch habe eine Idee, aber sie erfordert eine mächtige, konzentrierte Energiequelle. Solch eine Energiequelle kann man nur an einem Ort finden. Geht zu den Lagern der Legion nördlich von hier und besorgt Euch ein paar ihrer Schusswaffen.", sourceObjective = "Zuben Elgenubi möchte, dass Ihr 8 Schusswaffen der Legion besorgt und sie zur Sturmsäule bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10293] = { id = 10293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kristallader anzapfen", description = "Jetzt, da wir ein solides Grundprodukt haben, benötigen wir etwas von höherer Qualität. Das Farahlit, das wir bisher gesammelt haben, ist zwar ganz nett, aber es gibt noch besseres da draußen.\n\nWir müssen eine Probe direkt von Felsnarbe, dem Patriarchen der Riesen von Farahlon, besorgen! Ihr solltet ihn bei den anderen Riesen in der Gegend um den Nethersteine herum finden können. Aus seinem Rücken ragen große Farahlitstücke heraus; genau was wir brauchen. Tötet den Riesen und sammelt einen Farahlitkern von ihm.", sourceObjective = "Zuben Elgenubi in der Sturmsäule möchte, dass Ihr einen Farahlitkern besorgt.", progress = "Ihr seid immer noch am Leben, was bedeutet, dass Ihr entweder den Kern besorgt oder Eure Meinung geändert habt. Was davon stimmt?", completion = "Gut gemacht! Ich kann kaum abwarten, es auszuprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10294] = { id = 10294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leerengrat", description = "Wir müssen meinen Sphärenrissgenerator verbessern. Ihr müsst ihn zum Leerengrat bringen. Geht von hier aus nach Osten, um die verdorbene Festung Zeth'Gor herum. Im Osten hinter Zeth'Gor befindet sich ein kleiner Pass durch die Berge. Hinter diesem Pass findet Ihr den Leerengrat, einen schrecklichen Ort direkt am Abgrund.\n\nIhr müsst die Wandler, die Ihr dort findet, töten und mir Splitter ihrer Seele bringen. Mit ihrer Macht werden wir den Sphärenrissgenerator verbessern und ein Portal in die jenseitige Dimension öffnen, das nicht mehr geschlossen werden kann.", sourceObjective = "Geht zum Leerengrat und tötet die Kreaturen, die Ihr dort findet. Sammelt 40 Seelensplitter des Leerengrats und kehrt dann zu Ogath dem Verrückten im Rückenbrecherposten zurück.", progress = "Habt Ihr es schon getan? Habt Ihr die Splitter?", completion = "Ausgezeichnet. Der verbesserte Sphärenrissgenerator ist fast fertig. Es gibt nur noch einen letzten Bestandteil, den wir brauchen. Bald können wir einen stabilen Sphärenriss öffnen, den wir in den kommenden Jahren untersuchen können.\n\nWer weiß, welche fremdartigen Kreaturen durch ihn hindurchkommen werden? Stellt Euch nur vor, {name}, die Macht, die ein solches Wissen mit sich brächte, wäre unermesslich!", sourceObjectiveStatus = "unverified-source-field" }
quests[10295] = { id = 10295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Abgrund", description = "Mein Sphärenrissgenerator ist fertig. Ihr könnt damit jetzt einen wahren Prinzen der Leere rufen, eine Kreatur, deren Seelensplitter uns deutlich mehr darüber verraten wird, was dahinter liegt.\n\nGeht nach Süden in den Leerengrat und benutzt meinen Sphärenrissgenerator in der Nähe der Steine der Leere. Haltet nach einer Gruppe von Kristallen am Ende des Abgrunds Ausschau. Ein riesiger Sphärenriss wird sich auftun, aus dem dann sicher der Baron der Leere Galaxis entsteigen wird.\n\nZerstört diese Kreatur und bringt mir seinen Seelensplitter.", sourceObjective = "Tötet Galaxis und sammelt seinen Seelensplitter. Bringt den Splitter zu Ogath dem Verrückten im Rückenbrecherposten.", progress = "Habt Ihr den Baron der Leere Galaxis schon vernichtet?", completion = "Ihr habt mein Lebenswerk gerettet, {name}.\n\nSie haben mich wahnsinnig genannt, mich ausgelacht und gedacht, meine Besessenheit auf den Leerengrat und die Sphärenfelder hätte mich krank gemacht. Mit diesem Seelensplitter kann ich das Geheimnis der Leerwandler lüften. Ich werde die Macht über den Abgrund beherrschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10296] = { id = 10296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Morast", description = "Der ewige Drachenschwarm versucht nun nicht einmal mehr, seine Pläne geheim zu halten. Sie haben vor, den Wächter, Medivh, zu töten und zu verhindern, dass das Dunkle Portal jemals geöffnet wird. Auf den ersten Blick scheint das ein Gefallen für die Streitkräfte der Allianz zu sein, aber tatsächlich wären die Folgen katastrophal und würden in der Zerstörung Eurer Welt enden.\n\nIhr müsst auf dem Pfad der Zeit zum Schwarzen Morast reisen. Geht zuerst nach Westen und dann nach Süden, vorbei an meinem zukünftigen Ich, bis Ihr zu dem Tunnel kommt, in dem die Sumpfwesen leben. Durchquert ihn und sprecht mit Sa'at.", sourceObjective = "Reist durch die Höhlen der Zeit in den Schwarzen Morast während der Öffnung des Dunklen Portals und sprecht mit Sa'at.", completion = "Wenn die Orcs nie nach Azeroth gelangen, wird die Allianz sich nie formieren. Schließlich wird ein Bürgerkrieg ausbrechen, der die menschlichen Königreiche noch weiter schwächen wird.\n\nLetzten Endes wird die Brennende Legion in Azeroth einmarschieren, und da es keine Verteidiger gibt, das Land völlig zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[10297] = { id = 10297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Öffnung des Dunklen Portals", description = "Hinter diesem Pfad der Zeit, im Herzen des Schwarzen Morasts, arbeitet Medivh verbissen an der Öffnung des Dunklen Portals.\n\nÜberall im Morast werden sich Zeitlöcher öffnen, aus denen die Ewigen herausströmen werden mit dem Ziel, Medivhs Schilde und schließlich auch Medivh selbst zu vernichten.\n\nTötet die Lords des Zeitlochs und ihre Anführer, bis Medivh erfolgreich war.", sourceObjective = "Sa'at im Schwarzen Morast der Höhlen der Zeit möchte, dass Ihr Medivh verteidigt, bis er das Dunkle Portal geöffnet hat.\n\nKehrt zu Sa'at zurück, wenn Ihr erfolgreich wart.", progress = "Ihr dürft das Chronosignal nur einmal pro Zeitfalte benutzen.", completion = "Ihr habt Eure Arbeit gut gemacht, {name}. Das Kind, Andormu, möchte erneut mit Euch sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10298] = { id = 10298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held des Schwarms", description = "Kehrt zum Kind, Andormu, zurück, {name}. Er erwartet Euch außerhalb dieser Zeitfalte im Hort des Meisters.\n\nIch höre Flügelschlagen. Die Wächter der Sande interessieren sich für Eure Fähigkeiten. Vielleicht möchten auch sie mit Euch sprechen.", sourceObjective = "Kehrt zum Kind, Andormu, in den Höhlen der Zeit in Tanaris zurück.", completion = "Ihr habt die Gegenwart und die Zukunft dieser Welt ein weiteres Mal gerettet, {name}. Bitte nehmt diese Gegenstände als Belohnung für Eure Erfolge.", sourceObjectiveStatus = "unverified-source-field" }
quests[10299] = { id = 10299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede B'naar abschalten", description = "Wir können die Manaschmieden nicht mit Gewalt abschalten, da wir sonst eine Explosion auslösen könnten, die die Scherbenwelt bis in den Kern erschüttern würde.\n\nLaut Eurer Abschrift gibt es einen Notschalter, der die Technologie dauerhaft abschaltet - ein Sicherheitsmechanismus, der bei der Technologie der Naaru Standard ist.\n\nFür diesen Vorgang braucht Ihr einen Kristall, der Euch die Kommunikation mit der Konsole ermöglicht. Dieser Zugangskristall befindet sich unseren Informationen zufolge im Besitz eines Vorarbeiters namens Theredis.", sourceObjective = "Anachoret Karja möchte, dass Ihr in die Manaschmiede B'naar geht und einen Zugangskristall von Vorarbeiter Theredis besorgt. Benutzt ihn bei der Steuerkonsole von B'naar, um sie abzuschalten und meldet Euch danach bei Anachoret Karja zurück.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Wart Ihr bei Eurer Aufgabe erfolgreich, {name}?", completion = "Das Licht ist Euch wohl gesonnen, {name}. Wir haben alle für Euren Erfolg gebetet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10300] = { id = 10300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Stab wiederherstellen", description = "<Ravandwyr untersucht den Stab und bemerkt, dass das Kopfstück fehlt.>\n\nDas ist einfach barbarisch! Ekkorash muss das kristallene Kopfstück abgenommen haben, um es mit einem anderen Schmuckstück zu verwenden, und hat gar nicht gemerkt, dass es zum Rest des Stabs dazugehört!\n\nSolange er nicht komplett ist, ist die Macht des Stabs stark verringert. Ich könnte ihn jedoch mit einem geeigneten Draeneikristall reparieren. Ich habe gehört, wie die Goblins von den Kristallen der Geister in den Ruinen von Enkaat im Norden gesprochen haben.", sourceObjective = "Besorgt 4 fehlerlose Kristallsplitter von den Geistern in den Ruinen von Enkaat und bringt sie zu Ravandwyr in Area 52.", progress = "Habt Ihr schon ein paar geeignete Kristalle für ein neues Kopfstück des Stabs gefunden?", completion = "<Ravandwyr untersucht die Kristalle genau und wählt dann einen aus.>\n\nDieser Kristall sollte funktionieren. Ich werde den Sockel des Stabs umformen, damit das neue Kopfstück passt.\n\nErzmagier Vargoth wird enttäuscht sein, wenn er ihn sieht, aber ich bin bereit, die Enttäuschung meines Meisters in Kauf zu nehmen, wenn er nur endlich wieder frei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10301] = { id = 10301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kompendium öffnen", description = "Auch wenn ich froh bin, dass ich das meiste von Krasus' Kompendium zurück habe, ist es ohne das heliotrope Oculus nutzlos. Seht Ihr, Krasus war sich der unermesslichen Macht des Buchs bewusst und hat Vorkehrungen getroffen, damit es vor gierigen Blicken geschützt bleibt.\n\nNur ein Magier mit großem Wissen kann dem Kompendium mithilfe des Oculus' seine Geheimnisse entlocken.\n\nWährend Kael'thas' Angriff hat einer seiner Leutnants, Zauberhäscherin Marathelle, das Octulus aus dem Turm gestohlen und es zum Sonnenzornposten gebracht. Sie hält es sicher für ein hübsches kleines Schmuckstück.", sourceObjective = "Besorgt Euch das heliotrope Oculus von Zauberhäscherin Marathelle im Sonnenzornposten.", progress = "Habt Ihr das Oculus besorgt?", completion = "Ausgezeichnet, {name}. Jetzt haben wir fast alles, was wir benötigen, um Kael'thas' Magie zu durchbrechen.\n\nUnd wenn die Blutelfen unter dem Verlust ihres Kommandanten hier leiden, dann umso besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[10302] = { id = 10302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unberechenbare Mutanten", description = "Die verstrahlten Kraftkerne der Exodar haben der Umwelt hier verheerenden Schaden zugefügt. Die deutlichste Auswirkung ist das Auftauchen merkwürdiger Kreaturen, die anscheinend in ihrer Nähe wie Pilze aus dem Boden schießen.\n\nVielleicht gibt es etwas, was wir für sie tun können, aber im Augenblick sind sie einfach zu viele für uns.\n\nIch möchte, dass Ihr losgeht und ihre Zahl reduziert. Vielleicht fällt mir danach eine andere Lösung ein.", sourceObjective = "Tötet 8 unberechenbare Mutanten und kehrt dann zu Botanikerin Taerix bei der Absturzstelle im Am'mental zurück.", progress = "Ich arbeite an einer Lösung, die für die merkwürdigen Kreaturen große Wirkung haben sollte. Ich brauche nur mehr Zeit.", completion = "Ihr seid fertig? Das sind gute Nachrichten. Hoffentlich finden wir einen Weg, bei dem wir diese mutierten Kreaturen nicht töten müssen.\n\nIch glaube, ich habe einen Plan entwickelt, der uns eine alternative Lösungsmöglichkeit für unser Problem bietet, aber ich werde Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10303] = { id = 10303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutelfen", description = "Ihr müsst... die Bedrohung durch die Blutelfen... auslöschen. Findet heraus... was sie... vorhaben!\n\nSie sind auf dem... Kamm hinter mir.", sourceObjective = "Tötet 10 Blutelfenspäher und kehrt dann zu Tolaan im Schattenkamm im Am'mental zurück.", completion = "Diese Blutelfen wollen uns alle töten. Wie können wir sie davon abhalten?", sourceObjectiveStatus = "unverified-source-field" }
quests[10304] = { id = 10304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger Aldar", description = "Mit Eurer Hilfe konnten wir schneller, als wir gehofft hatten, eine Lösung für unser Problem finden.\n\nIch habe keine weitere Arbeit für Euch, meine Lehrlinge schaffen den Rest alleine.\n\nIhr solltet mit Verteidiger Aldar auf der anderen Seite des Schiffs sprechen.", sourceObjective = "Sprecht mit Verteidiger Aldar bei der Absturzstelle im Am'mental.", completion = "{name}, richtig? Ich habe viel Gutes über Euch und die Arbeit, die Ihr in der kurzen Zeit, in der Ihr hier wart, geleistet habt, gehört.\n\nWir sind auf Eure Hilfe angewiesen, um die Dinge wieder zu normalisieren. Ich bin mir sicher, dass auch Zhanaa da drüben Eure Hilfe brauchen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[10305] = { id = 10305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bannzauberin Belmara", description = "Dieser abgenutzte, dicke Foliant ist kein Zauberbuch, wie Ihr es vielleicht von einem Magier der Kirin Tor erwartet hättet. Die Seiten dieses Bandes sind voll von handgeschriebenen Geschichten mit bunten Zeichnungen.\n\nDer Foliant scheint viel älter zu sein, als seine Besitzerin und stammt vielleicht aus ihrem Familienerbe. Möglicherweise war das starke Band zu diesem Buch das, was Belmaras Geist an die Ruinen von Kirin'Var gefesselt hat. Wenn Ihr es auf seinen rechten Platz im Bücherregal zurückbringt, kommt ihr Geist vielleicht zur Ruhe.", sourceObjective = "Sucht die Wohnung von Bannzauberin Belmara in der Zaubergasse und bringt das Buch zurück auf seinen Platz im Bücherregal. Sprecht danach mit Hüter Dierwert in Kirin'Var.", progress = "Was habt Ihr gefunden, {name}?", completion = "Ja, ich habe davon gehört, dass Bannzauberin Belmara ein altes Buch mit Geschichten hatte, aber ich wusste nicht, dass sie es mit in die Scherbenwelt gebracht hatte. Ich bin mir sicher, dass ihr Geist nun, da Ihr es gefunden und zurückgebracht habt, ruhen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10306] = { id = 10306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörer Luminrath", description = "Der Mantel, der ohne Zweifel von Hochelfen geschneidert wurde, ist sogar für die Verhältnisse der Kirin Tor reich verziert. Die Symbole und Zeichen ergeben für Euch keinen Sinn, aber sie scheinen die Kleidung eindeutig mit Magie zu verstärken.\n\nVielleicht bindet dieser Gegenstand seinen früheren Besitzer an diese Existenzebene. Wenn das so ist, würde die Verbindung des Geistes mit dieser Welt vielleicht zerbrechen, wenn Ihr den Mantel zurück in die Kommode in Beschwörer Luminraths Wohnung bringt.", sourceObjective = "Sucht die Wohnung von Beschwörer Luminrath in der Zaubergasse und bringt den Mantel zurück in seine Kommode. Sprecht danach mit Hüter Dierwert in Kirin'Var.", completion = "Wir haben immer Scherze darüber gemacht, dass Luminrath zu allem diesen Mantel tragen würde. Für ihn passte Rot genauso gut zu Weiß wie zu Schwarz, Violett, Blau, Gelb, Orange und Grün. Er hätte niemals zwei Tage hintereinander die selbe Robe getragen, aber der Mantel war immer dabei...", sourceObjectiveStatus = "unverified-source-field" }
quests[10307] = { id = 10307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cohlien Frostwirker", description = "Während Ihr die Kappe betrachtet, fragt Ihr Euch, ob ein Magier der Kirin Tor überhaupt so einen Hut besitzen würde. Der Zustand der Kappe lässt darauf schließen, dass der Gnom das Haus nie ohne sie verlassen hätte.\n\nIhr probiert den Hut kurz auf und bemerkt keine magischen Eigenschaften außer einem schwachen Zwang zu tanzen.\n\nVielleicht bindet dieser geschätzte Besitz den Geist des toten Magiers an das Dorf. Wenn Ihr die Kappe zurück in die Schließkiste in Cohliens Wohnung legen würdet, könntet Ihr den Geist des Magiers vielleicht befreien.", sourceObjective = "Sucht die Wohnung von Cohlien Frostwirker in der Zaubergasse und bringt die Kappe zurück in seine Schließkiste. Sprecht danach mit Hüter Dierwert in Kirin'Var.", completion = "<Der Hüter lächelt, als Ihr Cohliens Name erwähnt.>\n\nIhr habt absolut Recht mit der Kappe. Er trug sie die ganze Zeit und lies sie nicht aus den Augen.\n\nEin paar Mal hat sich einer seiner Kollegen die Kappe \"ausgeliehen\" und sie zum Scherz versteckt. Ich brauche nicht zu erwähnen, dass die Androhung eines Frostblitzes von Cohlien ihn schnell zum Umdenken bewegt hat.\n\nIch werde den kleinen Cohlien vermissen. Er war sehr beliebt bei den Elfendamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10308] = { id = 10308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch ein Hügel voller Astraler", progress = "Das Konsortium ist sehr daran interessiert, alle Rebellen der Zaxxis beim Hügel im Süden auszulöschen.\n\n{class}, wenn Ihr Euch bei uns noch beliebter machen wollt, dann geht zurück und besorgt noch mehr ihrer Insignien.", completion = "Verräter, alle!\n\nGute Arbeit, {class}! Wenn Ihr nochmals dort hinunter gehen solltet, bin ich immer noch auf der Suche nach weiteren Insignien für meine Sammlung." }
quests[10309] = { id = 10309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelshäscher mit Herz", description = "Seht Ihr den kaputten Teufelshäscher im Süden? Ist er nicht schön?\n\nIch möchte sein Herz!\n\nWas? Natürlich hat er ein Herz... wer hat denn keins?\n\n<N.D. sieht für einen kurzen Moment beleidigt aus.>\n\nGeht dort hinüber, öffnet ihn und bringt mir, was ich möchte, dann bekommt Ihr auch einen schönen Finderlohn.\n\nOh, und ich würde an Eurer Stelle ein oder zwei Freunde mitnehmen. Diese Astralen der Zaxxis sind eine ziemlich verschlagene Truppe!\n\nNehmt diesen Teufelsschocker, um seinem Herz einen Stromimpuls zu geben, wenn Ihr bereit seid, loszulegen.", sourceObjective = "Besorgt das Herz des Teufelshäschers und bringt es zu N. D. Mieskamp beim Hügel im Nethersturm.", progress = "Meine Augen müssen von der ganzen Netherstrahlung hier schlechter werden. Habt Ihr schon das Herz des Teufelshäschers?", completion = "Wow, schaut Euch das an... ein schlagendes Teufelshäscherherz! Nun, es schlägt nicht wirklich, aber Ihr wisst schon, was ich meine.\n\nIch kann es kaum abwarten, dieses Ding zu benutzen. Oder ich verkaufe es. Ich kenne ein paar Depp... äh Kunden, die daran interessiert sein könnten.\n\nHier, Ihr habt Euch die Belohnung verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[10310] = { id = 10310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage am Warptor!", description = "Jetzt, da die Brennende Legion sich auf dem Trümmerfeld der Teufelshäscher in der Nähe befindet, müssen wir alles tun, um den Zuwachs der Dämonen in dieser Gegend aufzuhalten.\n\nSie haben ein Warptor im Süden in einer Gegend, die sie bezeichnenderweise Invasionspunkt: Zerstörer genannt haben.\n\nIch möchte, dass Ihr mit mir dorthin geht und mich beschützt, während ich das Tor sabotiere.\n\nGeht danach zum Mittelreichposten in der Biokuppel Mittelreich im Norden und meldet Gahruj unseren Erfolg.\n\nWir werden ein oder zwei Freunde von Euch für diesen Auftrag brauchen.", sourceObjective = "Begleitet Drijya zum Warptor beim Invasionspunkt: Zerstörer und sorgt für seine Sicherheit, während er das Tor sabotiert. Sprecht danach mit Gahruj im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", completion = "Das sind ausgezeichnete Neuigkeiten, mein Freund!\n\nIhr und Drijya haben uns einen großen Dienst erweisen. Jetzt, da das Warptor außer Gefecht ist, können die Dämonen in der Nähe keine Verstärkung mehr holen.\n\nBitte erlaubt mir, Euch in der Art des Konsortiums zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10311] = { id = 10311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drijya braucht Eure Hilfe", description = "{class}, schön ein hilfreiches Gesicht hier zu sehen.\n\nDie Brennende Legion bei dem Teufelshäscherhügel hier in der Nähe wird immer mutiger, und ich mache mir Sorgen um unsere Sicherheit. Die Dämonen erhalten immer mehr Verstärkung aus dem Invasionspunkt: Zerstörer im Süden.\n\nMein Gefährte, Drijya, hat sich dorthin aufgemacht, um die Gegend zu erkunden und zu schauen, ob er etwas gegen die Warptore der Legion ausrichten kann.\n\nBitte findet ihn und helft ihm, wo Ihr könnt.", sourceObjective = "Sprecht mit Drijya in der Nähe des Invasionspunkts: Zerstörer im Nethersturm.", completion = "Ich hoffe, dass Gahruj Euch hierher geschickt hat, um mir bei meinem Auftrag zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10312] = { id = 10312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Annalen von Kirin'Var", description = "Die Geister zum Schweigen zu bringen hat leider nichts an Ihrer Aggressivität geändert. Die bösartigen Geister, die Ihr vernichtet habt, tauchen nun wieder in den Straßen des Dorfs auf.\n\nWir müssen herausfinden, was dahinter steckt. Die Zerstörung Kirin'Vars war nur der Anfang, sonst hätten sich die Geister schon längst beruhigt.\n\nIm Rathaus im Süden von Kirin'Var gibt es ein Stadtregister, in dem alle Einwohner eingetragen sind. Ich habe gehört, dass Kampfmagier Dathric es zuletzt hatte. Vielleicht trägt sein Geist es noch mit sich herum.", sourceObjective = "Besorgt die Annalen von Kirin'Var aus dem Rathaus von Kirin'Var und bringt es zu Hüter Dierwert.", progress = "Konntet Ihr das Stadtregister finden?", completion = "<Hüter Dierwert nimmt Euch das Buch ab und blättert es durch.>\n\nHmm...\n\nSieht aus, als hätte ich Recht gehabt. Es scheint ein Muster zu geben.\n\nDie aggressivsten und gefährlichsten Geister stimmen mit den mächtigsten und hochrangigsten Kirin Tor, die in dem Dorf gelebt haben, überein. Dagegen scheint man die Dorfleute und Händler übersehen zu haben. Was könnte das bedeuten?", sourceObjectiveStatus = "unverified-source-field" }
quests[10313] = { id = 10313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warpenergien messen", description = "Wenn uns unser Instinkt nicht täuscht und diese Manaschmieden die Technologie der Festung der Stürme nutzen, könnte die ganze Scherbenwelt in großer Gefahr schweben.\n\nDie Energieauflademechanismen der Festung der Stürme waren niemals dafür gedacht, sie so nahe an bewohntem Land zu benutzen. Die Warpenergien könnten dieses Land zerstören, sogar wenn sie durch Kaels' Rohrleitungen fließen.\n\nBringt diese Kugel zur Manaschmiede B'naar. Sie ist so eingestellt, dass sie die Warpenergien messen kann. Benutzt sie an der Stelle, an der die Rohrleitungen in die Erde führen.", sourceObjective = "Exarch Orelis in Area 52 möchte, dass Ihr die Warpmesskugel zur Manaschmiede B'naar bringt und sie in der Nähe der vier Rohrleitungen benutzt.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eurer Ehre bei den Sehern.", progress = "Habt Ihr die Messungen, um die ich Euch gebeten habe, durchgeführt, {name}?", completion = "Das sind schlimme Nachrichten, {name}. Die Warpenergien, die aus den Rohren herausströmen, sind gefährlich hoch.\n\nWir müssen einen Weg finden, um die Manaschmieden abzuschalten, oder der kleine Rest, der noch von der Scherbenwelt übrig ist, wird in tausend Stücke gesprengt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10314] = { id = 10314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hartnäckiger Verdacht", description = "Das merkwürdige magische Gerät ähnelt nichts, was Ihr je zuvor gesehen habt. Es wurde mit Sicherheit nicht von Blutelfen hergestellt.\n\nAls Ihr bemerkt, dass die Geister sich näher an das Haus bewegen, stellt Ihr fest, dass die Kugel stärker zu leuchten beginnt, und wieder schwächer wird, als die Geister sich entfernen. Es steht außer Frage, dass sie mit der Beeinflussung der Geister in Verbindung steht.\n\nWie sie jedoch funktioniert, bleibt ein Geheimnis. Vielleicht kann Hüter Dierwert sich ja einen Reim darauf machen, wenn Ihr ihm die Überreste einiger Geister und Eure Beobachtungen zuteilwerden lasst.", sourceObjective = "Sammelt 10 abscheuliche Überreste von den wahnsinnigen Geistern auf dem Kapellenhof in Kirin'Var und bringt sie zu Hüter Dierwert.", progress = "Was habt Ihr herausgefunden, {name}?", completion = "<Hüter Dierwert untersucht die Überreste.>\n\nDas Gerät, das Ihr beschreibt, klingt nach einem nekromantischen Fokus... Ich hätte wissen sollen, dass dieser bösartige Lehrling sich dazu herablassen würde. Ich dachte, seine Ausbildung würde ihn daran hindern, so weit zu gehen, aber ich schätze, ich habe mich getäuscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10315] = { id = 10315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nethermanten neutralisieren", description = "Die Blutelfen sind Dummköpfe! Ich bin froh, dass unsere Handelsbeziehungen mit ihnen auseinander gebrochen sind. Auf all meinen Reisen durch den Kosmos habe ich nie so selbstsüchtige Wesen gesehen!\n\nSie zerstören weiterhin unser Land mit ihren Manaschmieden. Wollen wir mal schauen, ob wir ihnen bei der Manaschmiede Ara jenseits der Brücke Einhalt gebieten können.\n\nDie Nethermanten kanalisieren die Energie der Blutjuwelen, um den Energiefluss zu stabilisieren. Geht dort hin und löscht sie aus!", sourceObjective = "Tötet 15 Nethermanten des Sonnenzorns und kehrt dann zu Netherpirscher Oazul auf Tulumans Landeplatz im Nethersturm zurück.", completion = "Alles, was wir tun, um sie von ihren Taten in den Manaschmieden abzuhalten, ist gut.\n\nMan kann offenbar nicht vernünftig mit ihnen reden. Und was auch immer ihre Anführer vorhaben, sie müssen verrückt sein.\n\nAls Belohnung für Eure treuen Dienste für die Ziele des Konsortiums möchte ich Euch in Eurer Landeswährung bezahlen, wenn Ihr nichts dagegen habt.", sourceObjectiveStatus = "unverified-source-field" }
